(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("manilius-astronomica-b", [{"t": "<i>M. Manilii Astronomicon libri quinque. Latin text after the Latin Library edition; line numbers follow that text (Books II–IV counted continuously, so they run a few lines past the Housman–Goold numbering).<\/i>"}, {"sp": "HDR", "t": "Liber I"}, {"st": "1.1", "t": "Carmine divinas artes et conscia fati"}, {"st": "1.2", "t": "sidera, diversos hominum variantia casus,"}, {"st": "1.3", "t": "caelestis rationis opus, deducere mundo"}, {"st": "1.4", "t": "aggredior primusque novis Helicona movere"}, {"st": "1.5", "t": "cantibus et viridi nutantis vertice silvas,"}, {"st": "1.6", "t": "hospita sacra ferens nulli memorata priorum."}, {"st": "1.7", "t": "hunc mihi tu, Caesar, patriae princepsque paterque,"}, {"st": "1.8", "t": "qui regis augustis parentem legibus orbem"}, {"st": "1.9", "t": "concessumque patri mundum deus ipse mereris,"}, {"st": "1.10", "t": "das animum viresque facis ad tanta canenda."}, {"st": "1.11", "t": "iam propiusque favet mundus scrutantibus ipsum"}, {"st": "1.12", "t": "et cupit aetherios per carmina pandere census."}, {"st": "1.13", "t": "hoc sub pace vacat tantum; iuvat ire per ipsum"}, {"st": "1.14", "t": "aera et immenso spatiantem vivere caelo"}, {"st": "1.15", "t": "signaque et adversos stellarum noscere cursus."}, {"st": "1.16", "t": "quod solum novisse parum est. impensius ipsa"}, {"st": "1.17", "t": "scire iuvat magni penitus praecordia mundi,"}, {"st": "1.18", "t": "quaque regat generetque suis animalia signis,"}, {"st": "1.19", "t": "cernere et in numerum Phoebe modulante referre."}, {"st": "1.20", "t": "bina mihi positis lucent altaria flammis,"}, {"st": "1.21", "t": "ad duo templa precor duplici circumdatus aestu"}, {"st": "1.22", "t": "carminis et rerum; certa cum lege canentem"}, {"st": "1.23", "t": "mundus et immenso vatem circumstrepit orbe"}, {"st": "1.24", "t": "vixque soluta suis immittit verba figuris."}, {"st": "1.25", "t": "quem primum interius licuit cognoscere terris"}, {"st": "1.26", "t": "munere caelestum. quis enim condentibus illis"}, {"st": "1.27", "t": "clepsisset furto mundum, quo cuncta reguntur?"}, {"st": "1.28", "t": "quis foret humano conatus pectore tantum,"}, {"st": "1.29", "t": "invitis ut dis cuperet deus ipse videri?"}, {"st": "1.30", "t": "tu princeps auctorque sacri, Cyllenie, tanti;"}, {"st": "1.31", "t": "per te iam caelum interius, iam sidera nota"}, {"st": "1.32", "t": "sublimis aperire vias imumque sub orbem,"}, {"st": "1.33", "t": "et per inane suis parentia finibus astra"}, {"st": "1.34", "t": "nominaque et cursus signorum, pondera, vires,"}, {"st": "1.35", "t": "major uti facies mundi foret et veneranda"}, {"st": "1.36", "t": "non species tantum, sed et ipsa potentia rerum,"}, {"st": "1.37", "t": "sentirentque deum gentes quam maximus esset."}, {"st": "1.38", "t": "[qui sua disposuit per tempora, cognita ut essent"}, {"st": "1.39", "t": "omnibus et mundi facies caelumque supernum.]"}, {"st": "1.40", "t": "et natura dedit vires seque ipsa reclusit,"}, {"st": "1.41", "t": "regalis animos primum dignata movere"}, {"st": "1.42", "t": "proxima tangentis rerum fastigia caelo,"}, {"st": "1.43", "t": "qui domuere feras gentes oriente sub ipso,"}, {"st": "1.44", "t": "quas secat Euphrates, in quas et Nilus inundat,"}, {"st": "1.45", "t": "qua mundus redit et nigras super evolat urbes."}, {"st": "1.46", "t": "tunc qui templa sacris coluerunt omne per aevum"}, {"st": "1.47", "t": "delectique sacerdotes in publica vota"}, {"st": "1.48", "t": "officio vinxere deum, quibus ipsa potentis"}, {"st": "1.49", "t": "numinis accendit castam praesentia mentem,"}, {"st": "1.50", "t": "inque deum deus ipse tulit patuitque ministris."}, {"st": "1.51", "t": "hi tantum movere decus primique per artem"}, {"st": "1.52", "t": "sideribus videre vagis pendentia fata."}, {"st": "1.53", "t": "singula nam proprio signarunt tempora casu,"}, {"st": "1.54", "t": "longa per assiduas complexi saecula curas:"}, {"st": "1.55", "t": "nascendi quae cuique dies, quae vita fuisset,"}, {"st": "1.56", "t": "in quas fortunae leges quaeque hora valeret,"}, {"st": "1.57", "t": "quantaque quam parvi facerent discrimina motus."}, {"st": "1.58", "t": "postquam omnis caeli species redeuntibus astris"}, {"st": "1.59", "t": "percepta in proprias sedes, et reddita certis"}, {"st": "1.60", "t": "fatorum ordinibus sua cuique potentia formae,"}, {"st": "1.61", "t": "per varios usus artem experientia fecit"}, {"st": "1.62", "t": "exemplo monstrante viam speculataque longe"}, {"st": "1.63", "t": "deprendit tacitis dominantia legibus astra"}, {"st": "1.64", "t": "et totum aeterna mundum ratione moveri"}, {"st": "1.65", "t": "fatorumque vices certis discernere signis."}, {"st": "1.66", "t": "nam rudis ante illos nullo discrimine vita"}, {"st": "1.67", "t": "in speciem conversa operum ratione carebat"}, {"st": "1.68", "t": "et stupefacta novo pendebat lumine mundi,"}, {"st": "1.69", "t": "tum velut amissis maerens, tum laeta renatis"}, {"st": "1.70", "t": "sideribus, variosque dies incertaque noctis"}, {"st": "1.71", "t": "tempora nec similis umbras iam sole regresso,"}, {"st": "1.72", "t": "iam propiore suis poterant discernere causis."}, {"st": "1.73", "t": "necdum etiam doctas sollertia fecerat artes,"}, {"st": "1.74", "t": "terraque sub rudibus cessabat vasta colonis;"}, {"st": "1.75", "t": "tumque in desertis habitabat montibus aurum,"}, {"st": "1.76", "t": "immotusque novos pontus subduxerat orbes;"}, {"st": "1.77", "t": "nec vitam pelago nec ventis credere vota"}, {"st": "1.78", "t": "audebant; se quisque satis novisse putabant."}, {"st": "1.79", "t": "sed cum longa dies acuit mortalia corda"}, {"st": "1.80", "t": "et labor ingenium miseris dedit et sua quemque"}, {"st": "1.81", "t": "advigilare sibi iussit fortuna premendo,"}, {"st": "1.82", "t": "seducta in varias certarunt pectora curas,"}, {"st": "1.83", "t": "et quodcumque sagax temptando repperit usus,"}, {"st": "1.84", "t": "in commune bonum commentum laeta dederunt."}, {"st": "1.85", "t": "tune et lingua suas accepit barbara leges,"}, {"st": "1.86", "t": "et fera diversis exercita frugibus arva,"}, {"st": "1.87", "t": "et vagus in caecum penetravit navita pontum,"}, {"st": "1.88", "t": "fecit et ignotis itiner commercia terris."}, {"st": "1.89", "t": "tum belli pacisque artes commenta vetustas;"}, {"st": "1.90", "t": "semper enim ex aliis alias proseminat usus."}, {"st": "1.91", "t": "ne vulgata canam: linguas didicere volucrum,"}, {"st": "1.92", "t": "consultare fibras et rumpere vocibus angues,"}, {"st": "1.93", "t": "sollicitare umbras imumque Acheronta movere"}, {"st": "1.94", "t": "in noctemque dies, in lucem vertere noctes."}, {"st": "1.95", "t": "omnia conando docilis sollertia vicit."}, {"st": "1.96", "t": "nec prius imposuit rebus finemque manumque,"}, {"st": "1.97", "t": "quam caelum ascendit ratio cepitque profundam"}, {"st": "1.98", "t": "naturam rerum causis viditque quod usquam est;"}, {"st": "1.99", "t": "nubila cur tanto quaterentur pulsa fragore,"}, {"st": "1.100", "t": "hiberna aestiva nix grandine mollior esset,"}, {"st": "1.101", "t": "arderent terrae solidusque tremesceret orbis,"}, {"st": "1.102", "t": "cur imbres ruerent, ventos quae causa moveret,"}, {"st": "1.103", "t": "pervidit solvitque animis miracula rerum"}, {"st": "1.104", "t": "eripuitque Iovi fulmen viresque tonantis"}, {"st": "1.105", "t": "et sonitum ventis concessit, nubibus ignem."}, {"st": "1.106", "t": "quae postquam in proprias deduxit singula causas,"}, {"st": "1.107", "t": "vicinam ex alto mundi cognoscere molem"}, {"st": "1.108", "t": "intendit totumque animo comprendere caelum,"}, {"st": "1.109", "t": "attribuitque suas formas, sua nomina signis,"}, {"st": "1.110", "t": "quasque vices agerent certa sub sorte notavit,"}, {"st": "1.111", "t": "omniaque ad numen mundi faciemque moveri,"}, {"st": "1.112", "t": "sideribus vario mutantibus ordine fata."}, {"st": "1.113", "t": "hoc mihi surgit opus non ullis ante sacratum"}, {"st": "1.114", "t": "carminibus. faveat magno fortuna labori,"}, {"st": "1.115", "t": "annosa et molli contingat vita senecta,"}, {"st": "1.116", "t": "ut possim rerum tantas emergere moles"}, {"st": "1.117", "t": "magnaque cum parvis simili percurrere cura."}, {"st": "1.118", "t": "et quoniam caelo descendit carmen ab alto,"}, {"st": "1.119", "t": "et venit in terras fatorum conditus ordo,"}, {"st": "1.120", "t": "ipsa mihi primum naturae forma canenda est,"}, {"st": "1.121", "t": "ponendusque sua totus sub imagine mundus."}, {"st": "1.122", "t": "quem sive ex nullis repetentem semina rebus"}, {"st": "1.123", "t": "natali quoque egere placet semperque fuisse"}, {"st": "1.124", "t": "et fore principio pariter fatoque carentem:"}, {"st": "1.125", "t": "seu permixta chaos rerum primordia quondam"}, {"st": "1.126", "t": "discrevit partu, mundumque enixa nitentem"}, {"st": "1.127", "t": "fugit in infernas caligo pulsa tenebras;"}, {"st": "1.128", "t": "sive individuis in idem reditura soluta"}, {"st": "1.129", "t": "principiis natura manet post saecula mille,"}, {"st": "1.130", "t": "et paene ex nihilo summa est nihilumque futurum,"}, {"st": "1.131", "t": "caecaque materies caelum, perfecit et orbem;"}, {"st": "1.132", "t": "sive ignis fabricavit opus flammaeque micantes,"}, {"st": "1.133", "t": "quae mundi fecere oculos habitantque per omne"}, {"st": "1.134", "t": "corpus et in caelo vibrantia fulmina fingunt;"}, {"st": "1.135", "t": "seu liquor hoc peperit, sine quo riget arida rerum"}, {"st": "1.136", "t": "materies ipsumque vorat, quo solvitur, ignem;"}, {"st": "1.137", "t": "aut neque terra patrem novit nec flamma nec aer"}, {"st": "1.138", "t": "aut umor, faciuntque deum per quattuor artus"}, {"st": "1.139", "t": "et mundi struxere globum prohibentque requiri"}, {"st": "1.140", "t": "ultra se quicquam, cum per se cuncta"}, {"st": "1.141", "t": "creentur,"}, {"st": "1.142", "t": "frigida nec calidis desint, aut umida siccis,"}, {"st": "1.143", "t": "spiritus aut solidis, sitque haec discordia concors,"}, {"st": "1.144", "t": "quae nexus habilis et opus generabile fingit,"}, {"st": "1.145", "t": "atque omnis partus elementa capacia reddit; --"}, {"st": "1.146", "t": "semper erit genus in pugna, dubiumque manebit"}, {"st": "1.147", "t": "quod latet et tantum supra est hominemque deumque;"}, {"st": "1.148", "t": "sed facies quaecumque tamen sub origine rerum,"}, {"st": "1.149", "t": "convenit et certo digestum est ordine corpus."}, {"st": "1.150", "t": "ignis in aetherias volucer se sustulit oras"}, {"st": "1.151", "t": "summaque complexus stellantis culmina caeli"}, {"st": "1.152", "t": "flammarum vallo naturae moenia fecit."}, {"st": "1.153", "t": "proximus in tenuis descendit spiritus auras"}, {"st": "1.154", "t": "aeraque extendit medium per inania mundi;"}, {"st": "1.155", "t": "ignem flatus alit vicinis subditus astris."}, {"st": "1.156", "t": "tertia sors undas stravit fluctusque natantis"}, {"st": "1.157", "t": "aequora per fudit toto nascentia ponto,"}, {"st": "1.158", "t": "ut liquor exhalet tenuis atque evomat auras"}, {"st": "1.159", "t": "aeraque ex ipso ducentem semina pascat."}, {"st": "1.160", "t": "ultima subsedit glomerato pondere tellus,"}, {"st": "1.161", "t": "convenitque vagis permixtus limus harenis"}, {"st": "1.162", "t": "paulatim ad summum tenui fugiente liquore;"}, {"st": "1.163", "t": "quoque magis puras umor secessit in auras,"}, {"st": "1.164", "t": "et siccata magis struxerunt aequora terram,"}, {"st": "1.165", "t": "adiacuitque cavis fluidum convallibus aequor,"}, {"st": "1.166", "t": "emersere fretis montes, orbisque per undas"}, {"st": "1.167", "t": "exsiliit vasto clausus tamen undique ponto."}, {"st": "1.167b", "t": "imaque de cunctis mediam tenet undique sedem,"}, {"st": "1.168", "t": "idcircoque manet stabilis, quia totus ab illa"}, {"st": "1.169", "t": "tantundem refugit mundus fecitque cadendo"}, {"st": "1.170", "t": "undique ne caderet (medium totius et imum est),"}, {"st": "1.171", "t": "ictaque contractis consistunt corpora plagis"}, {"st": "1.172", "t": "et concurrendo prohibent in longius ire."}, {"st": "1.173", "t": "quodni librato penderet pondere tellus,"}, {"st": "1.174", "t": "non ageret cursus mundi subeuntibus astris"}, {"st": "1.175", "t": "Phoebus ad occasum et numquam remearet ad ortus,"}, {"st": "1.176", "t": "lunave submersos regeret per inania cursus,"}, {"st": "1.177", "t": "nec matutinis fulgeret Lucifer horis,"}, {"st": "1.178", "t": "Hesperos emenso dederat qui lumen Olympo."}, {"st": "1.179", "t": "nunc quia non imo tellus deiecta profundo,"}, {"st": "1.180", "t": "sed medio suspensa manet, sunt pervia cuncta,"}, {"st": "1.181", "t": "qua cadat et subeat caelum rursusque resurgat."}, {"st": "1.182", "t": "nam neque fortuitos ortus surgentibus astris"}, {"st": "1.183", "t": "nec totiens possum nascentem credere mundum"}, {"st": "1.184", "t": "solisve assiduos partus et fata diurna,"}, {"st": "1.185", "t": "cum facies eadem signis per saecula constet,"}, {"st": "1.186", "t": "idem Phoebus eat caeli de partibus isdem,"}, {"st": "1.187", "t": "lunaque per totidem luces mutetur et orbes,"}, {"st": "1.188", "t": "et natura vias servet, quas fecerat ipsa,"}, {"st": "1.189", "t": "nec tirocinio peccet circumque feratur"}, {"st": "1.190", "t": "aeterna cum luce dies, qui tempora monstrat"}, {"st": "1.191", "t": "nunc his nunc illis eadem regionibus orbis,"}, {"st": "1.192", "t": "semper et ulterior vadentibus ortus ad ortum,"}, {"st": "1.193", "t": "occasumve obitus, caelum et cum sole perennet."}, {"st": "1.194", "t": "nec vero natura tibi admiranda videri"}, {"st": "1.195", "t": "pendentis terrae debet. cum pendeat ipse"}, {"st": "1.196", "t": "mundus et in nullo ponat vestigia fundo,"}, {"st": "1.197", "t": "quod patet ex ipso motu cursuque volantis,"}, {"st": "1.198", "t": "cum suspensus eat Phoebus currusque reflectat"}, {"st": "1.199", "t": "huc illuc agiles et servet in aethere metas,"}, {"st": "1.200", "t": "cum luna et stellae volitent per inania mundi,"}, {"st": "1.201", "t": "terra quoque aerias leges imitata pependit."}, {"st": "1.202", "t": "est igitur tellus mediam sortita cavernam"}, {"st": "1.203", "t": "aeris et tote pariter sublata profundo"}, {"st": "1.204", "t": "nec patulas distenta plagas, sed condita in orbem"}, {"st": "1.205", "t": "undique surgentem pariter pariterque cadentem."}, {"st": "1.206", "t": "haec est naturae facies; sic mundus et ipse"}, {"st": "1.207", "t": "in convexa volans teretes facit esse figuras"}, {"st": "1.208", "t": "stellarum; solisque orbem lunaeque rotundum"}, {"st": "1.209", "t": "aspicimus, tumido quaerentis corpore lumen,"}, {"st": "1.210", "t": "quod globus obliquos totus non accipit ignes."}, {"st": "1.211", "t": "haec aeterna manet divisque simillima forma,"}, {"st": "1.212", "t": "cui neque principium est usquam, nec finis in ipsa,"}, {"st": "1.213", "t": "sed similis tote ore manet perque omnia par est."}, {"st": "1.214", "t": "sic tellus glomerata manet mundique figura."}, {"st": "1.215", "t": "idcirco terris non omnibus omnia signa"}, {"st": "1.216", "t": "conspicimus. nusquam invenies fulgere Canopum,"}, {"st": "1.217", "t": "donec Niliacas per pontum veneris oras;"}, {"st": "1.218", "t": "sed quaerent Helicen, quibus ille supervenit ignis,"}, {"st": "1.219", "t": "quod laterum tractus habitant, medioque tumore"}, {"st": "1.220", "t": "eripiunt terrae caelum visusque coercent."}, {"st": "1.221", "t": "te testem dat, luna, sui glomeraminis orbis,"}, {"st": "1.222", "t": "quae cum mersa nigris per noctem deficis umbris,"}, {"st": "1.223", "t": "non omnis pariter confundis sidere dempto,"}, {"st": "1.224", "t": "sed prius eoae quaerunt tua lumina gentes,"}, {"st": "1.225", "t": "post, medio subiecta polo quaecumque coluntur,"}, {"st": "1.226", "t": "ultima ad hesperios infectis volveris alis"}, {"st": "1.227", "t": "seraque in extremis quatiuntur gentibus aera."}, {"st": "1.228", "t": "quodsi plana foret tellus, semel orta per omnem"}, {"st": "1.229", "t": "deficeret pariter toti miserabilis orbi."}, {"st": "1.230", "t": "sed quia per teretem deducta est terra tumorem,"}, {"st": "1.231", "t": "his modo, post illis apparet Delia terris"}, {"st": "1.232", "t": "exoriens simul atque cadens; quia fertur in orbem"}, {"st": "1.233", "t": "ventris et acclivis pariter declivia iungit"}, {"st": "1.234", "t": "atque alios superat gyros aliosque relinquit."}, {"st": "1.235", "t": "ex quo colligitur terrarum forma rotunda."}, {"st": "1.236", "t": "hanc circum variae gentes hominum atque ferarum"}, {"st": "1.237", "t": "aeriaeque colunt volucres. pars eius ad arctos"}, {"st": "1.238", "t": "eminet, austrinis pars est habitabilis oris"}, {"st": "1.239", "t": "sub pedibusque iacet nostris supraque videtur"}, {"st": "1.240", "t": "ipsa sibi fallente solo declivia longa"}, {"st": "1.241", "t": "et pariter surgente via pariterque cadente."}, {"st": "1.242", "t": "hanc ubi ad occasus nostros sol aspicit ortus,"}, {"st": "1.243", "t": "illic orta dies sopitas excitat urbes"}, {"st": "1.244", "t": "et cum luce refert operum vadimonia terris;"}, {"st": "1.245", "t": "nos in nocte sumus somnosque in membra vocamus."}, {"st": "1.246", "t": "pontus utrosque suis distinguit et alligat undis."}, {"st": "1.247", "t": "hoc opus immensi constructum corpore mundi"}, {"st": "1.248", "t": "membraque naturae diversa condita forma"}, {"st": "1.249", "t": "aeris atque ignis terrae pelagique iacentis"}, {"st": "1.250", "t": "vis animae divina regit, sacroque meatu"}, {"st": "1.251", "t": "conspirat deus et tacita ratione gubernat"}, {"st": "1.252", "t": "mutuaque in cunctas dispensat foedera partes,"}, {"st": "1.253", "t": "altera ut alterius vires faciatque feratque,"}, {"st": "1.255", "t": "summaque per varias maneat cognata figuras."}, {"st": "1.256", "t": "nunc tibi signorum lucentis undique flammas"}, {"st": "1.257", "t": "ordinibus certis referam, primumque canentur"}, {"st": "1.258", "t": "quae media obliquo praecingunt ordine mundum"}, {"st": "1.259", "t": "solemque alternis vicibus per tempora portant"}, {"st": "1.260", "t": "atque alia adverso luctantia sidera mundo;"}, {"st": "1.261", "t": "omnia, quae possis caelo numerare sereno;"}, {"st": "1.262", "t": "e quibus et ratio fatorum ducitur omnis,"}, {"st": "1.263", "t": "ut sit idem mundi primum quod continet arcem."}, {"st": "1.264", "t": "aurato princeps Aries in vellere fulgens"}, {"st": "1.265", "t": "respicit admirans aversum surgere Taurum"}, {"st": "1.266", "t": "summisso vultu Geminos et fronte vocantem."}, {"st": "1.267", "t": "quos sequitur Cancer, Cancrum Leo, Virgo Leonem."}, {"st": "1.268", "t": "aequato tum Libra die cum tempore noctis"}, {"st": "1.269", "t": "attrahit ardenti fulgentem Scorpion astro."}, {"st": "1.270", "t": "in cuius caudam contento dirigit arcu"}, {"st": "1.271", "t": "mixtus equo volucrem missurus iamque sagittam."}, {"st": "1.272", "t": "tum venit angusto Capricornus sidere flexus;"}, {"st": "1.273", "t": "post hunc inflexa defundit Aquarius urna"}, {"st": "1.274", "t": "Piscibus assuetas avide subeuntibus undas,"}, {"st": "1.275", "t": "quos Aries tangit claudentis ultima signa."}, {"st": "1.276", "t": "at qua fulgentis caelum consurgit ad Arctos,"}, {"st": "1.277", "t": "omnia quae summo despectant sidera mundo,"}, {"st": "1.278", "t": "nec norunt obitus unoque in vertice tendunt."}, {"st": "1.279", "t": "in diversa situ caelumque et sidera torquens"}, {"st": "1.280", "t": "aera per gelidum tenuis deducitur axis"}, {"st": "1.281", "t": "libratumque regit diverso cardine mundum,"}, {"st": "1.281b", "t": "sidereus circa medium quem volvitur orbis"}, {"st": "1.282", "t": "aetheriosque rotat cursus; immotus at ille"}, {"st": "1.283", "t": "in binas Arctos magni per inania mundi"}, {"st": "1.284", "t": "perque ipsum terrae directus constitit orbem."}, {"st": "1.285", "t": "nec vero e solido stat robore corporis eius,"}, {"st": "1.286", "t": "nec grave pondus habet, quod onus ferat aetheris alti;"}, {"st": "1.287", "t": "sed cum aer omnis semper volvatur in orbem,"}, {"st": "1.288", "t": "quoque semel coepit, totus volet undique in ipsum,"}, {"st": "1.289", "t": "quodcumque in medio est, circa quod cuncta moventur,"}, {"st": "1.290", "t": "usque adeo tenue, ut verti non possit in ipsum"}, {"st": "1.291", "t": "nec iam inclinari nec se convertere in orbem,"}, {"st": "1.292", "t": "hoc dixere axem, quia motum non habet ullum,"}, {"st": "1.293", "t": "ipse videt circa volitantia cuncta moveri."}, {"st": "1.294", "t": "summa tenent eius miseris notissima nautis"}, {"st": "1.295", "t": "signa per immensum cupidos ducentia pontum:"}, {"st": "1.296", "t": "maioremque Helice major decircinat arcum,"}, {"st": "1.297", "t": "septem illam stellae certantes lumine signant,"}, {"st": "1.298", "t": "qua duce per fluctus Graiae dant vela carinae."}, {"st": "1.299", "t": "angusto Cynosura brevis torquetur in orbe"}, {"st": "1.300", "t": "quam spatio, tam luce minor; sed iudice vincit"}, {"st": "1.301", "t": "maiorem Tyrio. Poenis haec certior auctor,"}, {"st": "1.302", "t": "non apparentem pelago quaerentibus orbem."}, {"st": "1.303", "t": "nec paribus positae sunt frontibus; utraque caudam"}, {"st": "1.304", "t": "vergit in alterius rostro sequiturque sequentem."}, {"st": "1.305", "t": "has inter fusus circumque amplexus utramque"}, {"st": "1.306", "t": "dividit et cingit stellis ardentibus Anguis,"}, {"st": "1.307", "t": "ne coeant abeantve suis a sedibus umquam."}, {"st": "1.308", "t": "hunc inter mediumque orbem, quo sidera septem"}, {"st": "1.309", "t": "per bis sena volant contra nitentia signa"}, {"st": "1.310", "t": "mixta ex diversis consurgunt viribus astra"}, {"st": "1.311", "t": "hine vicina polo Phoebique hinc proxima flammis;"}, {"st": "1.312", "t": "quae quia dissimilis, qua pugnat, temperat aer,"}, {"st": "1.313", "t": "frugiferum sub se reddunt mortalibus orbem."}, {"st": "1.314", "t": "proxima frigentis Arctos boreamque rigentem"}, {"st": "1.315", "t": "nixa venit species genibus sibi conscia causae."}, {"st": "1.316", "t": "a tergo nitet Arctophylax, idemque Bootes,"}, {"st": "1.317", "t": "quod stimulis iunctis instat de more iuvencis;"}, {"st": "1.318", "t": "Arcturumque rapit medio sub pectore secum."}, {"st": "1.319", "t": "at parte ex alia claro volat orbe Corona,"}, {"st": "1.320", "t": "luce micans varia; nam stella vincitur una"}, {"st": "1.321", "t": "circulus, in media radiat quae maxima fronte"}, {"st": "1.322", "t": "candidaque ardenti distinguit lumina flamma:"}, {"st": "1.323", "t": "Gnosia desertae fulgent monimenta puellae."}, {"st": "1.324", "t": "at Lyra diductis per caelum cornibus inter"}, {"st": "1.325", "t": "sidera conspicitur, qua quondam ceperat Orpheus"}, {"st": "1.326", "t": "omne quod attigerat cantu manesque per ipsos"}, {"st": "1.327", "t": "fecit iter domuitque infernas carmine leges."}, {"st": "1.328", "t": "hinc caelestis honos similisque potentia causae:"}, {"st": "1.329", "t": "tunc silvas et saxa trahens, nunc sidera ducit"}, {"st": "1.330", "t": "et rapit immensum mundi revolubilis orbem."}, {"st": "1.331", "t": "Serpentem magnis Ophiuchus nomine signis"}, {"st": "1.332", "t": "dividit, ut tote cingentem corpore corpus"}, {"st": "1.333", "t": "explicet et nodes sinuataque terga per orbes:"}, {"st": "1.334", "t": "respicit ille tamen molli cervice reflexus"}, {"st": "1.335", "t": "et redit effusis per laxa volumina palmis:"}, {"st": "1.336", "t": "semper erit paribus bellum, quia viribus aequant."}, {"st": "1.337", "t": "proxima sors Cycni, quem caelo Iuppiter ipse"}, {"st": "1.338", "t": "imposuit, formae pretium, qua cepit amantem,"}, {"st": "1.339", "t": "cum deus in niveum descendit versus olorem"}, {"st": "1.340", "t": "tergaque fidenti subiecit plumea Ledae."}, {"st": "1.341", "t": "nunc quoque diductas volitat stellatus in alas."}, {"st": "1.342", "t": "hinc imitata nitent cursumque habitumque Sagittae"}, {"st": "1.343", "t": "sidera. tum magni Iovis ales fertur in altum,"}, {"st": "1.344", "t": "assueto volitans gestet ceu fulmina mundo,"}, {"st": "1.345", "t": "digna Iove et caelo, quod sacris instruit armis."}, {"st": "1.346", "t": "tum quoque de ponto surgit Delphinus ad astra,"}, {"st": "1.347", "t": "oceani caelique decus, per utrumque sacratus."}, {"st": "1.348", "t": "quem rapido conatus Equus comprendere cursu"}, {"st": "1.349", "t": "festinat pectus fulgenti sidere clarus."}, {"st": "1.350", "t": "et finitur in Andromeda; [quam Perseus armis"}, {"st": "1.351", "t": "eripit et sociat sibi, cui] succedit iniquo"}, {"st": "1.352", "t": "divisum spatio, quod tertia lampada dispar"}, {"st": "1.353", "t": "conspicitur paribus, Deltoton nomine sidus,"}, {"st": "1.354", "t": "ex simili dictum; Cepheusque et Cassiepia"}, {"st": "1.355", "t": "in poenas signata suas iuxtaque relictam"}, {"st": "1.356", "t": "Andromedam vastos metuentem pristis hiatus,"}, {"st": "1.357", "t": "expositam ponto deflet scopulisque revinctam,"}, {"st": "1.358", "t": "ni veterem Perseus caelo quoque servet amorem"}, {"st": "1.359", "t": "auxilioque iuvet fugiendaque Gorgonis ora"}, {"st": "1.360", "t": "sustineat spoliumque sibi pestemque videnti."}, {"st": "1.361", "t": "tum vicina ferens nixo vestigia Tauro"}, {"st": "1.362", "t": "Heniochus studio mundumque et nomen adeptus,"}, {"st": "1.363", "t": "quem primum curru volitantem Iuppiter alto"}, {"st": "1.364", "t": "quadriiugis conspexit equis caeloque sacravit."}, {"st": "1.365", "t": "hunc subeunt Haedi claudentes sidere pontum,"}, {"st": "1.366", "t": "nobilis et mundi nutrito rege Capella,"}, {"st": "1.367", "t": "cuius ab uberibus magnum ile ascendit Olympum."}, {"st": "1.368", "t": "lacte fero crescens ad fulmina vimque tonandi;"}, {"st": "1.369", "t": "hanc ergo aeternis merito sacravit in astris"}, {"st": "1.370", "t": "Iuppiter et caeli caelum mercede rependit."}, {"st": "1.371", "t": "Pleiadesque Hyadesque feri pars utraque Tauri"}, {"st": "1.372", "t": "in boream scandunt. haec sunt aquilonia signa."}, {"st": "1.373", "t": "aspice nunc infra solis surgentia cursus,"}, {"st": "1.374", "t": "quae super exustas labuntur sidera terras"}, {"st": "1.375", "t": "quaeque inter gelidum Capricorni sidus et axe"}, {"st": "1.376", "t": "imo subnixum vertuntur lumina mundum,"}, {"st": "1.377", "t": "altera pars orbis sub quis iacet invia nobis"}, {"st": "1.378", "t": "ignotaeque hominum gentes nec transita regna,"}, {"st": "1.379", "t": "commune ex uno lumen ducentia sole"}, {"st": "1.380", "t": "diversasque umbras laevaque cadentia signa"}, {"st": "1.381", "t": "et dextros ortus caelo spectantia verso."}, {"st": "1.382", "t": "nec minor est illis mundus nec lumine peior,"}, {"st": "1.383", "t": "nec numerosa minus nascuntur sidera in orbem."}, {"st": "1.384", "t": "cetera non cedunt; uno vincuntur in astro,"}, {"st": "1.385", "t": "Augusto, sidus nostro quod contigit orbi,"}, {"st": "1.386", "t": "Caesar nunc terris, post caelo maximus auctor."}, {"st": "1.387", "t": "cernere vicinum Geminis licet Oriona,"}, {"st": "1.388", "t": "in magnam caeli tendentem bracchia partem"}, {"st": "1.389", "t": "nec minus extento surgentem ad sidera passu,"}, {"st": "1.390", "t": "singula fulgentis umeros cui lumina signant"}, {"st": "1.391", "t": "et tribus obliquis demissus ducitur ensis."}, {"st": "1.392", "t": "at caput Orion excelso immersus Olympo"}, {"st": "1.393", "t": "per tria subducto signatur lumina vultu,"}, {"st": "1.394", "t": "non quod clara minus, sed quod magis alta recedunt."}, {"st": "1.395", "t": "hoc duce per totum decurrunt sidera mundum."}, {"st": "1.396", "t": "subsequitur rapido contenta Canicula cursu,"}, {"st": "1.397", "t": "qua nullum terris violentius advenit astrum"}, {"st": "1.398", "t": "nec gravius cedit; nunc horrida frigore surgit,"}, {"st": "1.399", "t": "nunc vacuum soli fulgentem deserit orbem:"}, {"st": "1.400", "t": "sic in utrumque movet mundum et contraria reddit."}, {"st": "1.401", "t": "hanc qui surgentem, primo cum redditur ortu,"}, {"st": "1.402", "t": "montis ab excelso speculantur vertice Tauri,"}, {"st": "1.403", "t": "eventus frugum varios et tempora dicunt,"}, {"st": "1.404", "t": "quaeque valetudo veniat, concordia quanta;"}, {"st": "1.405", "t": "bella facit pacemque refert varieque revertens"}, {"st": "1.406", "t": "sic movet, ut vidit mundum, vultuque gubernat."}, {"st": "1.407", "t": "magna fides hoc posse color cursusque micantis"}, {"st": "1.408", "t": "in radios: vix sole minor, nisi quod procul haerens"}, {"st": "1.409", "t": "frigida caeruleo contorquet lumina vultu."}, {"st": "1.410", "t": "cetera vincuntur specie, nec clarius astrum"}, {"st": "1.411", "t": "tinguitur oceano caelumve revisit ab undis."}, {"st": "1.412", "t": "tunc Procyon veloxque Lepus, tum nobilis Argo"}, {"st": "1.413", "t": "in caelum subducta mari, quod prima cucurrit,"}, {"st": "1.414", "t": "emeritum magnis mundum tenet acta periclis,"}, {"st": "1.415", "t": "servando dea facta deos. cui proximus Anguis"}, {"st": "1.416", "t": "squamea dispositis imitatur lumina flammis."}, {"st": "1.417", "t": "et Phoebo sacer Ales et una gratus Iaccho"}, {"st": "1.418", "t": "Crater et duplici Centaurus imagine fulget,"}, {"st": "1.419", "t": "pars hominis, tergo pectus commissus equino."}, {"st": "1.420", "t": "ipsius hinc mundo templum est, victrixque solutis"}, {"st": "1.421", "t": "Ara nitet sacris, vastos cum terra gigantes"}, {"st": "1.422", "t": "in caelum furibunda tulit. tum di quoque magnos"}, {"st": "1.423", "t": "quaesivere deos; dubitavit Iuppiter ipse,"}, {"st": "1.424", "t": "quod poterat non posse timens, cum surgere terram"}, {"st": "1.425", "t": "cerneret, ut verti naturam crederet omnem,"}, {"st": "1.426", "t": "montibus atque aliis aggestos crescere montes,"}, {"st": "1.427", "t": "et tam vicinos fugientia sidera colles,"}, {"st": "1.428", "t": "* arma importantis et rupta matre creatos,"}, {"st": "1.429", "t": "* discordes vultum permixtaque corpora partus."}, {"st": "1.430", "t": "necdum pestiferum sibi quemquam (aut) numina norat"}, {"st": "1.431", "t": "si qua forent maiora suis. tunc Iuppiter Arae"}, {"st": "1.432", "t": "sidera constituit, quae nunc quoque maxima fulgent."}, {"st": "1.433", "t": "quam propter Cetus convolvens squamea terga"}, {"st": "1.434", "t": "orbibus insurgit tortis et fluctuat alvo,"}, {"st": "1.435", "t": "intentans morsum, similis iam iamque tenenti,"}, {"st": "1.436", "t": "qualis ad expositae fatum Cepheidos undis"}, {"st": "1.437", "t": "expulit adveniens ultra sua litora pontum."}, {"st": "1.438", "t": "tum notius Piscis venti de nomine dictus"}, {"st": "1.439", "t": "exsurgit de parte noti; cui iuncta feruntur"}, {"st": "1.440", "t": "flexa per ingentis stellarum flumina gyros."}, {"st": "1.441", "t": "alterius capiti coniungit Aquarius undas"}, {"st": "1.442", "t": "amnis, et in medium coeunt et sidera miscent."}, {"st": "1.443", "t": "his, inter solisque vias Arctosque latentes"}, {"st": "1.444", "t": "axem quae mundi stridentem pondere torquent,"}, {"st": "1.445", "t": "orbe peregrino caelum depingitur astris,"}, {"st": "1.446", "t": "quae notia antiqui dixerunt sidera vates."}, {"st": "1.447", "t": "ultima quae mundo semper volvuntur in imo,"}, {"st": "1.448", "t": "quis innixa manent caeli fulgentia templa,"}, {"st": "1.449", "t": "nusquam in conspectum redeuntia, cardine verso"}, {"st": "1.450", "t": "sublimis speciem mundi similisque figuras"}, {"st": "1.451", "t": "astrorum referunt. et versas frontibus Arctos"}, {"st": "1.452", "t": "uno distingui medias claudique Dracone"}, {"st": "1.453", "t": "credimus exemplo. quamvis fugientia visus"}, {"st": "1.454", "t": "hunc orbem caeli vertentis sidera cursu"}, {"st": "1.455", "t": "cardine tam simili fultum, quam vertice, pingunt."}, {"st": "1.456", "t": "haec igitur magno divisas aethere sedes"}, {"st": "1.457", "t": "signa tenent mundi totum deducta per orbem."}, {"st": "1.458", "t": "tu modo corporeis similis ne quaere figuras,"}, {"st": "1.459", "t": "omnia ut aequali fulgentia membra colore"}, {"st": "1.460", "t": "deficiat nihil aut vacuum qua lumine cesset."}, {"st": "1.461", "t": "non poterit mundus sufferre incendia tanta,"}, {"st": "1.462", "t": "omnia si plenis ardebunt sidera membris."}, {"st": "1.463", "t": "quicquid subduxit flammis, natura pepercit"}, {"st": "1.464", "t": "succubitura oneri, formas disiungere tantum"}, {"st": "1.465", "t": "contenta et stellis ostendere sidera certis."}, {"st": "1.466", "t": "linea designat species, atque ignibus ignes"}, {"st": "1.467", "t": "respondent, media extremis atque ultima summis"}, {"st": "1.468", "t": "creduntur; satis est, si se non omnia celant."}, {"st": "1.469", "t": "praecipue medio cum luna implebitur orbe,"}, {"st": "1.470", "t": "certa nitent mundo tum lumina, conditur omne"}, {"st": "1.471", "t": "stellarum vulgus, fugiunt sine nomine signa."}, {"st": "1.472", "t": "pura licet vacuo tum cernere sidera caelo,"}, {"st": "1.473", "t": "nec fallunt numero, parvis nec mixta feruntur."}, {"st": "1.474", "t": "et quo clara magis possis cognoscere signa,"}, {"st": "1.475", "t": "non varios obitus norunt variosque recursus,"}, {"st": "1.476", "t": "certa sed in proprias oriuntur sidera luces,"}, {"st": "1.477", "t": "natalesque suos occasumque ordine servant."}, {"st": "1.478", "t": "nec quicquam in tanta magis est mirabile mole,"}, {"st": "1.479", "t": "quam ratio et certis quod legibus omnia parent."}, {"st": "1.480", "t": "nusquam turba nocet, nihil ullis partibus errat,"}, {"st": "1.481", "t": "laxius aut brevius mutatove ordine fertur."}, {"st": "1.482", "t": "quid tam confusum specie, quid tam vice certum est?"}, {"st": "1.483", "t": "ac mihi tam praesens ratio non ulla videtur,"}, {"st": "1.484", "t": "qua pateat mundum divino numine verti"}, {"st": "1.485", "t": "atque ipsum esse deum nec forte coisse magistra,"}, {"st": "1.486", "t": "ut voluit eredi, qui primus moenia mundi"}, {"st": "1.487", "t": "seminibus struxit minimis inque illa resolvit,"}, {"st": "1.488", "t": "e quis et maria et terras et sidera caeli"}, {"st": "1.489", "t": "aetheraque immensis fabricantem finibus orbes"}, {"st": "1.490", "t": "solventemque alios constare et cuncta reverti"}, {"st": "1.491", "t": "in sua principia et rerum mutare figuras."}, {"st": "1.492", "t": "quis credat tantas operum sine numine moles,"}, {"st": "1.493", "t": "ex minimis caecoque creatum foedere mundum?"}, {"st": "1.494", "t": "si fors ista dedit nobis, fors ipsa gubernet;"}, {"st": "1.495", "t": "at cur dispositis vicibus consurgere signa"}, {"st": "1.496", "t": "et velut imperio praescriptos reddere cursus"}, {"st": "1.497", "t": "cernimus ac nullis properantibus ulla relinqui?"}, {"st": "1.498", "t": "cur eadem aestivas exornant sidera noctes"}, {"st": "1.499", "t": "semper et hibernas eadem, certamque figuram"}, {"st": "1.500", "t": "cuiusque dies reddit mundo certamque relinquit?"}, {"st": "1.501", "t": "iam tum, cum Graiae verterunt Pergama gentes,"}, {"st": "1.502", "t": "Arctos et Orion adversis frontibus ibant,"}, {"st": "1.503", "t": "haec contenta suos in vertice flectere gyros,"}, {"st": "1.504", "t": "ille ex diverso vertentem surgere contra"}, {"st": "1.505", "t": "obvius et toto semper decurrere mundo."}, {"st": "1.506", "t": "temporaque obscurae noctis deprendere signis"}, {"st": "1.507", "t": "iam poterant, caelumque suas distinxerat horas."}, {"st": "1.508", "t": "quot post excidium Troiae sunt eruta regna!"}, {"st": "1.509", "t": "quot capti populi! quotiens fortuna per orbem"}, {"st": "1.510", "t": "servitium imperiumque tulit varieque revertit!"}, {"st": "1.511", "t": "Troianos cineres in quantum oblita refovit"}, {"st": "1.512", "t": "imperium! fatis Asiae iam Graecia pressa est."}, {"st": "1.513", "t": "saecula dinumerare piget, quotiensque recurrens"}, {"st": "1.514", "t": "lustrarit mundum vario sol igneus orbe."}, {"st": "1.515", "t": "omnia mortali mutantur lege creata,"}, {"st": "1.516", "t": "nec se cognoscunt terrae vertentibus annis"}, {"st": "1.517", "t": "exutas variam faciem per saecula gentes."}, {"st": "1.518", "t": "at manet incolumis mundus suaque omnia servat,"}, {"st": "1.519", "t": "quae nec longa dies auget minuitque senectus,"}, {"st": "1.520", "t": "nec motus puncto curvat cursusque fatigat:"}, {"st": "1.521", "t": "idem semper erit, quoniam semper fuit idem."}, {"st": "1.522", "t": "non alium videre patres aliumve nepotes"}, {"st": "1.523", "t": "aspicient: deus est, qui non mutatur in aevo."}, {"st": "1.524", "t": "numquam transversas solem decurrere ad Arctos"}, {"st": "1.525", "t": "nec mutare vias et in ortum vertere cursus"}, {"st": "1.526", "t": "auroramque novis nascentem ostendere terris,"}, {"st": "1.527", "t": "nec lunam certos excedere luminis orbes"}, {"st": "1.528", "t": "sed servare modum, quo crescat quove recedat,"}, {"st": "1.529", "t": "nec cadere in terram pendentia sidera caelo"}, {"st": "1.530", "t": "sed dimensa suis consumere tempora signis:"}, {"st": "1.531", "t": "non casus opus est, magni sed numinis ordo."}, {"st": "1.532", "t": "haec igitur texunt aequali sidera tractu"}, {"st": "1.533", "t": "ignibus in varias caelum laqueantia formas."}, {"st": "1.534", "t": "altius his nihil est; haec sunt fastigia mundi;"}, {"st": "1.535", "t": "publica naturae domus his contenta tenetur"}, {"st": "1.536", "t": "finibus amplectens pontum terrasque iacentis."}, {"st": "1.537", "t": "omnia concordi tractu veniuntque caduntque,"}, {"st": "1.538", "t": "qua semel incubuit caelum versumque resurgit."}, {"st": "1.539", "t": "ipse autem quantum convexo mundus Olympo"}, {"st": "1.540", "t": "obtineat spatium, quantis bis sena ferantur"}, {"st": "1.541", "t": "finibus astra, docet ratio, cui nulla resistunt"}, {"st": "1.542", "t": "claustra nec immensae moles, ceduntque recessus,"}, {"st": "1.543", "t": "omnia succumbunt, ipsum est penetrabile caelum."}, {"st": "1.544", "t": "nam quantum a terris atque aequore signa recedunt,"}, {"st": "1.545", "t": "tantum bina patent. quacumque inciditur orbis"}, {"st": "1.546", "t": "per medium, pars efficitur tum tertia gyri,"}, {"st": "1.547", "t": "exiguo dirimens solidam discrimine summam."}, {"st": "1.548", "t": "summum igitur caelum bis bina refugit ab imo"}, {"st": "1.549", "t": "astra, &lt;e&gt; bis senis ut sit pars tertia signis."}, {"st": "1.550", "t": "sed quia per medium est tellus suspensa profundum,"}, {"st": "1.551", "t": "binis a summo signis discedit et imo."}, {"st": "1.552", "t": "hinc igitur quodcumque supra te suspicis ipse,"}, {"st": "1.553", "t": "qua per inane meant oculi quaque ire recusant."}, {"st": "1.554", "t": "binis aequandum est signis, sex tanta"}, {"st": "1.555", "t": "rotundae"}, {"st": "1.556", "t": "efficiunt orbem zonae, qua signa feruntur"}, {"st": "1.557", "t": "bis sex aequali spatio texentia caelum."}, {"st": "1.558", "t": "nec mirere vagos partus eadem esse per astra"}, {"st": "1.559", "t": "et mixtum ingenti generis discrimine fatum,"}, {"st": "1.560", "t": "singula cum tantum teneant tantoque ferantur"}, {"st": "1.561", "t": "tempore; sex tota surgentia sidera luce"}, {"st": "1.562", "t": "*"}, {"st": "1.563", "t": "*"}, {"st": "1.564", "t": "*"}, {"st": "1.565", "t": "*"}, {"st": "1.566", "t": "*"}, {"st": "1.567", "t": "*"}, {"st": "1.568", "t": "*"}, {"st": "1.569", "t": "restat ut aetherios fines tibi reddere coner"}, {"st": "1.570", "t": "filaque dispositis vicibus comitantia caelum"}, {"st": "1.571", "t": "per quae dirigitur signorum flammeus ordo."}, {"st": "1.572", "t": "[circulus a summo nascentem vertice mundum"}, {"st": "1.573", "t": "permeat Arctophylaca petens per terga draconis]"}, {"st": "1.574", "t": "circulus ad boream fulgentem sustinet Arcton"}, {"st": "1.575", "t": "sexque fugit solidas a caeli vertice partes."}, {"st": "1.576", "t": "alter ad extremi decurrens sidera Cancri,"}, {"st": "1.577", "t": "in quo consummat Phoebus lucemque moramque"}, {"st": "1.578", "t": "tardaque per longos circumfert lumina flexus,"}, {"st": "1.579", "t": "aestivum medio nomen sibi sumit ab aestu"}, {"st": "1.580", "t": "temporis et titulo potitur metamque volantis"}, {"st": "1.581", "t": "solis et extremos designat fervidus actus"}, {"st": "1.582", "t": "et quinque in partes aquilonis distat ab orbe."}, {"st": "1.583", "t": "tertius in media mundi regione locatus"}, {"st": "1.584", "t": "ingenti spira totum praecingit Olympum"}, {"st": "1.585", "t": "parte ab utraque videns axem, quo limite Phoebus"}, {"st": "1.586", "t": "componit paribus numeris noctemque diemque"}, {"st": "1.587", "t": "veris et autumni currens per tempora mixta,"}, {"st": "1.588", "t": "cum medium aequali distinguit limite caelum"}, {"st": "1.581b", "t": "quattuor et gradibus sua fila reducit ab aestu."}, {"st": "1.582b", "t": "proximus hunc ultra brumalis nomine limes"}, {"st": "1.583b", "t": "ultima designat fugientis limina solis"}, {"st": "1.584b", "t": "invidaque obliqua radiorum munera flamma"}, {"st": "1.585b", "t": "dat per iter minimum nobis; sed finibus illis,"}, {"st": "1.586b", "t": "quos super incubuit, longa stant tempora luce,"}, {"st": "1.587b", "t": "vixque dies transit candentem extenta per aestum,"}, {"st": "1.588b", "t": "bisque iacet binis summotus partibus orbis."}, {"st": "1.589", "t": "unus ab his superest extremo proximus axi"}, {"st": "1.590", "t": "circulus, austrinas qui stringit et obsidet Arctos."}, {"st": "1.591", "t": "hic quoque brumalem per partes quinque relinquit,"}, {"st": "1.592", "t": "et quantum a nostro sublimis cardine gyrus,"}, {"st": "1.593", "t": "distat ab adverso tantundem proximus illi."}, {"st": "1.594", "t": "[sic tibi per binas vertex a vertice partes"}, {"st": "1.595", "t": "divisus duplici summa circumdat Olympum"}, {"st": "1.596", "t": "et per quinque notat signantis tempore fines.]"}, {"st": "1.597", "t": "his eadem est via quae mundo pariterque rotantur"}, {"st": "1.598", "t": "inclines sociosque ortus occasibus aequant,"}, {"st": "1.599", "t": "quandoquidem secti, qua totus volvitur orbis,"}, {"st": "1.600", "t": "fila trahunt alti cursum comitantia caeli"}, {"st": "1.601", "t": "intervalla pari servantes limite semper"}, {"st": "1.602", "t": "divisosque semel fines sortemque dicatam."}, {"st": "1.603", "t": "sunt duo, quos recipit ductos a vertice vertex,"}, {"st": "1.604", "t": "inter se adversi, qui cunctos ante relatos"}, {"st": "1.605", "t": "seque secant gemino coeuntes cardine mundi"}, {"st": "1.606", "t": "transversoque polo rectum ducuntur in axem,"}, {"st": "1.607", "t": "tempora signantes anni caelumque per astra"}, {"st": "1.608", "t": "quattuor in partes divisum mensibus aequis."}, {"st": "1.609", "t": "alter ab excelso decurrens limes Olympo"}, {"st": "1.610", "t": "serpentis caudam siccas et dividit Arctos,"}, {"st": "1.611", "t": "et iuga Chelarum medio volitantia gyro"}, {"st": "1.612", "t": "extremamque secans Hydram mediumque sub austris"}, {"st": "1.613", "t": "Centaurum adverso concurrit rursus in axe"}, {"st": "1.614", "t": "et redit in caelum squamosaque tergora Ceti"}, {"st": "1.615", "t": "Lanigerique notat fines clarumque Trigonum"}, {"st": "1.616", "t": "Andromedaeque sinus imos, vestigia matris"}, {"st": "1.617", "t": "principiumque suum repetito cardine claudit."}, {"st": "1.618", "t": "alter in hunc medium summumque incumbit in axem"}, {"st": "1.619", "t": "perque pedes primos cervicem transit et Ursae,"}, {"st": "1.620", "t": "quam septem stellae primam iam sole remoto"}, {"st": "1.621", "t": "producunt nigrae praebentem lumina nocti,"}, {"st": "1.622", "t": "et Geminis Cancrum dirimit stringitque flagrantem"}, {"st": "1.623", "t": "ore Canem clavumque Ratis, quae vicerat aequor."}, {"st": "1.624", "t": "inde axem occultum per gyri signa prioris"}, {"st": "1.625", "t": "transversa atque illo rursus de limite tangit"}, {"st": "1.626", "t": "te, Capricorne, tuisque Aquilam designat ab astris,"}, {"st": "1.627", "t": "perque Lyram inversam currens spirasque Draconis:"}, {"st": "1.628", "t": "posteriora pedum Cynosurae praeterit astra"}, {"st": "1.629", "t": "transversamque secat vicino cardine caudam."}, {"st": "1.630", "t": "hic fretum coit ipse sibi memor, unde profectus."}, {"st": "1.631", "t": "atque hos aeterna fixerunt tempora sede"}, {"st": "1.632", "t": "immotis per signa modis statione perenni."}, {"st": "1.633", "t": "hos volucris fecere duos; namque alter ab ipsa"}, {"st": "1.634", "t": "consurgens Helice medium praecidit Olympum"}, {"st": "1.635", "t": "discernitque diem sextamque examinat horam"}, {"st": "1.636", "t": "et paribus spatiis occasus cernit et ortus."}, {"st": "1.637", "t": "hic mutat per signa vices; seu si quis eoos"}, {"st": "1.638", "t": "seu petit hesperios, supra se circinat orbem"}, {"st": "1.639", "t": "verticibus super astantem mediumque secantem"}, {"st": "1.640", "t": "caelum et diviso signantem culmine mundum"}, {"st": "1.641", "t": "(quando aliis aliud medium est; volat hora per orbem),"}, {"st": "1.642", "t": "cumque loco terrae caelumque et tempora mutat."}, {"st": "1.643", "t": "atque ubi se primis extollit Phoebus ab undis,"}, {"st": "1.644", "t": "illis sexta manet, quos tum premit aureus orbis."}, {"st": "1.645", "t": "rursus ad hesperios sexta est, ubi cedit in umbras;"}, {"st": "1.646", "t": "nos primam ac summam sextam numeramus utramque"}, {"st": "1.647", "t": "et gelidum extremo lumen sentimus ab igni."}, {"st": "1.648", "t": "alterius fines si vis cognoscere gyri,"}, {"st": "1.649", "t": "circumfer faciles oculos vultumque per orbem."}, {"st": "1.650", "t": "quicquid erit caelique imum terraeque supremum,"}, {"st": "1.651", "t": "qua coit ipse sibi nullo discrimine mundus"}, {"st": "1.652", "t": "redditque aut recipit fulgentia sidera ponto,"}, {"st": "1.653", "t": "praecingit tenui transversum limite mundum."}, {"st": "1.654", "t": "haec quoque per totum volitabit linea caelum,"}, {"st": "1.655", "t": "non tantum ad medium vergens mediumque repente"}, {"st": "1.656", "t": "orbem, nunc septem ad stellas nec mota sub astra,"}, {"st": "1.657", "t": "sed quacumque vagae tulerint vestigia plantae"}, {"st": "1.658", "t": "has modo terrarum nunc has gradientis in oras,"}, {"st": "1.659", "t": "semper erit novus et terris mutabitur arcus;"}, {"st": "1.660", "t": "quippe aliud caelum ostendens aliudque relinquens"}, {"st": "1.661", "t": "dimidium teget et referet varioque notabit"}, {"st": "1.662", "t": "fine et cum visu pariter sua fila movente."}, {"st": "1.663", "t": "hic terrestris erit, quia terram amplectitur"}, {"st": "1.664", "t": "orbis,"}, {"st": "1.665", "t": "[et mundum pleno praecingit limite gyrus]"}, {"st": "1.666", "t": "atque a fine trahens titulum memoratur horizon."}, {"st": "1.667", "t": "his adice obliquos adversaque fila trahentis"}, {"st": "1.668", "t": "inter se gyros, quorum fulgentia signa"}, {"st": "1.669", "t": "alter habet, per quae Phoebus moderatur habenas,"}, {"st": "1.670", "t": "subsequiturque suo solem vaga Delia curru,"}, {"st": "1.671", "t": "et quinque adverso luctantia sidera mundo"}, {"st": "1.672", "t": "exercent varias naturae lege choreas."}, {"st": "1.673", "t": "hunc tenet a summo Cancer, Capricornus ab imo,"}, {"st": "1.674", "t": "bis recipit, lucem qui circulus aequat et umbras,"}, {"st": "1.675", "t": "Lanigeri et Librae signo sua fila secantem."}, {"st": "1.676", "t": "sic per tres gyros inflexus ducitur orbis"}, {"st": "1.677", "t": "rectaque devexo fallit vestigia clivo;"}, {"st": "1.678", "t": "nec visus aciemque fugit tantumque notari"}, {"st": "1.679", "t": "mente potest, sicut cernuntur mente priores,"}, {"st": "1.680", "t": "sed nitet ingenti stellatus balteus orbe"}, {"st": "1.681", "t": "insignemque facit caelato lumine mundum"}, {"st": "1.682", "t": "et ter vicenas partes patet atque trecentas"}, {"st": "1.683", "t": "in longum; bis sex latescit fascia partes,"}, {"st": "1.684", "t": "quae cohibet vario labentia sidera cursu."}, {"st": "1.685", "t": "alter in adversum positus succedit ad Arctos"}, {"st": "1.686", "t": "et paulum a boreae gyro sua fila reducit"}, {"st": "1.687", "t": "transitque inversae per sidera Cassiepiae."}, {"st": "1.688", "t": "inde per obliquum descendens tangit Olorem"}, {"st": "1.689", "t": "aestivosque secat fines Aquilamque supinam"}, {"st": "1.690", "t": "temporaque aequantem gyrum zonamque ferentem"}, {"st": "1.691", "t": "Solis equos inter caudam, qua Scorpius ardet,"}, {"st": "1.692", "t": "extremamque Sagittari laevam atque Sagittam."}, {"st": "1.693", "t": "inde suos sinuat flexus crura pedesque"}, {"st": "1.694", "t": "Centauri alterius rursusque ascendere caelum"}, {"st": "1.694b", "t": "incipit Argivumque Ratem per aplustria summa"}, {"st": "1.695", "t": "et medium mundi gyrum Geminosque per ima"}, {"st": "1.696", "t": "signa secat, subit Heniochum, teque, unde profectus,"}, {"st": "1.697", "t": "Cassiepia, petens super ipsum Persea transit"}, {"st": "1.698", "t": "orbemque ex illa coeptum concludit in ipsa"}, {"st": "1.699", "t": "trisque secat medios gyros et signa ferentem"}, {"st": "1.700", "t": "partibus e binis, quotiens praeciditur ipse."}, {"st": "1.701", "t": "nec quaerendus erit: visus incurrit in ipsos"}, {"st": "1.702", "t": "sponte sua seque ipse docet cogitque notari."}, {"st": "1.703", "t": "namque in caeruleo candens nitet orbita mundo"}, {"st": "1.704", "t": "ceu missura diem subito caelumque recludens."}, {"st": "1.705", "t": "ac veluti virides discernit semita campos,"}, {"st": "1.706", "t": "quam terit assiduo renovans iter orbita tractu;"}, {"st": "1.707", "t": "[inter divisas aequalibus est via partis]"}, {"st": "1.708", "t": "ut freta canescunt sulcum ducente carina"}, {"st": "1.709", "t": "accipiuntque viam fluctus spumantibus undis,"}, {"st": "1.710", "t": "quam tortus verso movit de gurgite vertex,"}, {"st": "1.711", "t": "candidus in nigro lucet sic limes Olympo"}, {"st": "1.712", "t": "caeruleum findens ingenti lumine mundum."}, {"st": "1.713", "t": "utque suos arcus per nubila circinat Iris,"}, {"st": "1.714", "t": "sic superincumbit signato culmine limes"}, {"st": "1.715", "t": "candidus et resupina facit mortalibus ora,"}, {"st": "1.716", "t": "dum nova per caecam mirantur lumina noctem"}, {"st": "1.717", "t": "inquiruntque sacras humano pectore causas,"}, {"st": "1.718", "t": "num se diductis conetur solvere moles"}, {"st": "1.719", "t": "segminibus, raraque labent compagine rimae"}, {"st": "1.720", "t": "admittantque novum laxato tegmine lumen; --"}, {"st": "1.724", "t": "quid sibi non timeant, magni cum vulnera caeli"}, {"st": "1.725", "t": "conspiciant, feriatque oculos iniuria mundi? --"}, {"st": "1.726", "t": "an coeat mundus, duplicisque extrema cavernae"}, {"st": "1.727", "t": "conveniant caelique oras et sidera iungant,"}, {"st": "1.728", "t": "perque ipsos fiat nexus manifesta cicatrix"}, {"st": "1.729", "t": "fusuram faciens mundi, stipatus et orbis"}, {"st": "1.730", "t": "aeriam in nebulam clara compagine versus"}, {"st": "1.731", "t": "in cuneos alti cogat fundamina caeli."}, {"st": "1.732", "t": "an melius manet illa fides, per saecula prisca"}, {"st": "1.733", "t": "illac solis equos diversis cursibus isse"}, {"st": "1.734", "t": "atque aliam trivisse viam, longumque per aevum"}, {"st": "1.735", "t": "exustas sedes incoctaque sidera flammis"}, {"st": "1.736", "t": "caeruleam verso speciem mutasse colore,"}, {"st": "1.737", "t": "infusumque loco cinerem mundumque sepultum?"}, {"st": "1.738", "t": "fama etiam antiquis ad nos descendit ab annis"}, {"st": "1.739", "t": "Phaethontem patrio curru per signa volantem,"}, {"st": "1.740", "t": "dum nova miratur propius spectacula mundi"}, {"st": "1.741", "t": "et puer in caelo ludit curruque superbus"}, {"st": "1.742", "t": "luxuriat mundo, cupit et maiora parente,"}, {"st": "1.743", "t": "monstratas liquisse vias orbemque rigenti"}, {"st": "1.744", "t": "imposuisse polo; nec signa insueta tulisse"}, {"st": "1.745", "t": "errantis meta flammas cursumque solutum,"}, {"st": "1.746", "t": "* deflexum solito cursu curvisque quadrigis."}, {"st": "1.747", "t": "quid querimur flammas totum saevisse per orbem,"}, {"st": "1.748", "t": "terrarumque rogum cunctas arsisse per urbes,"}, {"st": "1.749", "t": "cum vaga dispersi fluitarunt lumina currus,"}, {"st": "1.750", "t": "et caelum exustum est? luit ipse incendia mundus,"}, {"st": "1.748b", "t": "et nova vicinis flagrarunt sidera flammis"}, {"st": "1.749b", "t": "nunc quoque praeteriti faciem referentia casus."}, {"st": "1.750b", "t": "nec mihi celanda est famae vulgata vetustas"}, {"st": "1.751", "t": "mollior: e niveo lactis fluxisse liquorem"}, {"st": "1.752", "t": "pectore reginae divum caelumque colore"}, {"st": "1.753", "t": "infecisse suo. quapropter lacteus orbis"}, {"st": "1.754", "t": "dicitur, et nomen causa descendit ab ipsa."}, {"st": "1.755", "t": "an maior densa stellarum turba corona"}, {"st": "1.756", "t": "convexit flammas et crasso lumine candet,"}, {"st": "1.757", "t": "et fulgore nitet collato clarior orbis?"}, {"st": "1.758", "t": "an fortes animae dignataque nomina caelo"}, {"st": "1.759", "t": "corporibus resoluta suis terraeque remissa"}, {"st": "1.760", "t": "huc migrant ex orbe suumque habitantia caelum"}, {"st": "1.761", "t": "aetherios vivunt annos mundoque fruuntur?"}, {"st": "1.762", "t": "atque hic Aeacidas, hic et veneramur Atridas"}, {"st": "1.763", "t": "Tydidemque ferum terraeque marisque triumphis"}, {"st": "1.764", "t": "naturae victorem Ithacum Pyliumque senecta"}, {"st": "1.765", "t": "insignem triplici Danaumque ad Pergama reges,"}, {"st": "1.766", "t": "[castra ducum et caeli victamque sub Hectore Troiam]"}, {"st": "1.767", "t": "Auroraeque nigrum partum stirpemque Tonantis"}, {"st": "1.768", "t": "rectorem Lyciae; nec te, Mavortia virgo,"}, {"st": "1.769", "t": "praeteream regesque alios, quos Thraecia misit"}, {"st": "1.770", "t": "atque Asiae gentes et Magno maxima Pella;"}, {"st": "1.771", "t": "quique animi vires et strictae pondera mentis"}, {"st": "1.772", "t": "prudentes habuere viri, quibus omnis in ipsis"}, {"st": "1.773", "t": "census erat, iustusque Solon fortisque Lycurgus,"}, {"st": "1.774", "t": "aetheriusque Platon et qui fabricaverat illum"}, {"st": "1.775", "t": "damnatusque suas melius damnavit Athenas,"}, {"st": "1.776", "t": "Persidis et victor, strarat quae classibus aequor."}, {"st": "1.777", "t": "Romanique viri, quorum iam maxima turba est:"}, {"st": "1.778", "t": "Tarquinioque minus reges, et Horatia proles,"}, {"st": "1.779", "t": "tota acies partus, nec non et Scaevola trunco"}, {"st": "1.780", "t": "nobilior, maiorque viris et cloelia virgo,"}, {"st": "1.781", "t": "et Romana ferens, quae texit, moenia Cocles,"}, {"st": "1.782", "t": "et commilitio volucris Corvinus adeptus"}, {"st": "1.783", "t": "et spolia et nomen, qui gestat in alite Phoebum,"}, {"st": "1.784", "t": "et Iove qui meruit caelum Romamque Camillus"}, {"st": "1.785", "t": "servando posuit, Brutusque a rege receptae"}, {"st": "1.786", "t": "conditor, et Pyrrhi per bella Papirius ultor,"}, {"st": "1.787", "t": "Fabricius Curiusque pares, et tertia palma"}, {"st": "1.788", "t": "Marcellus, Cossusque prior de rege necato,"}, {"st": "1.789", "t": "certantesque Deci votis similesque triumphis,"}, {"st": "1.790", "t": "invictusque mora Fabius, victorque necantis"}, {"st": "1.791", "t": "Livius Hasdrubalis socio per bella Nerone,"}, {"st": "1.792", "t": "Scipiadaeque duces, fatum Carthaginis unum,"}, {"st": "1.793", "t": "Pompeiusque orbis domitor per trisque triumphos"}, {"st": "1.794", "t": "ante deum princeps, et censu Tullius oris"}, {"st": "1.795", "t": "emeritus caelum, et &lt;tu,&gt; Claudi magna propago,"}, {"st": "1.796", "t": "Aemiliaeque domus proceres, clarique Metelli,"}, {"st": "1.797", "t": "et Cato fortunae victor, matrisque sub armis"}, {"st": "1.798", "t": "miles Agrippa suae. Venerisque ab origine proles"}, {"st": "1.799", "t": "Iulia descendit caelo caelumque replevit,"}, {"st": "1.800", "t": "quod regit Augustus socio per signa Tonante,"}, {"st": "1.801", "t": "cernit et in coetu divum magnumque Quirinum"}, {"st": "1.802", "t": "altius aetherii quam candet circulus orbis."}, {"st": "1.803", "t": "illa deum sedes, haec illis proxima, divum"}, {"st": "1.804", "t": "qui virtute sua similes vestigia tangunt."}, {"st": "1.805", "t": "ac prius incipiam stellis quam reddere vires"}, {"st": "1.806", "t": "signorumque canam fatalia carmine iura,"}, {"st": "1.807", "t": "implenda est mundi facies, corpusque per omne"}, {"st": "1.808", "t": "quid, quod ubique nitet, vigeat quandoque, notandum est."}, {"st": "1.809", "t": "sunt alia adverso pugnantia sidera mundo,"}, {"st": "1.810", "t": "quae terram caelumque inter volitantia pendent."}, {"st": "1.811", "t": "[Saturni, Iovis et Martis Solisque, sub illis"}, {"st": "1.812", "t": "Mercurius Venerem inter agit Lunamque locatus.]"}, {"st": "1.813", "t": "sunt etiam raris orti natalibus ignes,"}, {"st": "1.814", "t": "protinus et rapti. subitas candescere flammas"}, {"st": "1.815", "t": "aera per liquidum tractosque perire cometas"}, {"st": "1.816", "t": "rata per ingentis viderunt saecula motus."}, {"st": "1.817", "t": "sive, quod ingenitum terra spirante vaporem"}, {"st": "1.818", "t": "umidior sicca superatur spiritus aura,"}, {"st": "1.819", "t": "nubila cum longo cessant dispulsa sereno,"}, {"st": "1.820", "t": "et solis radiis arescit torridus aer,"}, {"st": "1.821", "t": "apta alimenta sibi demissus corripit ignis"}, {"st": "1.822", "t": "materiamque sui deprendit flamma capacem. --"}, {"st": "1.823", "t": "et quia non solidum est corpus, sed rara vagantur"}, {"st": "1.824", "t": "principia aurarum volucrique simillima fumo,"}, {"st": "1.825", "t": "in breve vivit opus coeptaque incendia fine"}, {"st": "1.826", "t": "subsistunt pariterque cadunt fulgentque cometae."}, {"st": "1.827", "t": "quod nisi vicinos agerent occasibus ortus"}, {"st": "1.828", "t": "et tam parva forent accensis tempora flammis,"}, {"st": "1.829", "t": "alter nocte dies esset caelumque rediret"}, {"st": "1.830", "t": "inversum et somno totum deprenderet orbem."}, {"st": "1.831", "t": "tum quia non una specie dispergitur omnis"}, {"st": "1.832", "t": "aridior terrae vapor et comprenditur igni,"}, {"st": "1.833", "t": "diversas quoque per facies accensa feruntur"}, {"st": "1.834", "t": "lumina, quae subitis exsistunt nata tenebris."}, {"st": "1.835", "t": "nam modo, ceu longi fluitent de vertice crines,"}, {"st": "1.836", "t": "flamma comas imitata volat, tenuisque capillos"}, {"st": "1.837", "t": "diffusos radiis ardentibus explicat ignis."}, {"st": "1.838", "t": "nunc prior haec facies dispersis crinibus exit,"}, {"st": "1.839", "t": "et glomus ardentis sequitur sub imagine barbae"}, {"st": "1.845", "t": "hirta figurantis tremulo sub lumine menta."}, {"st": "1.840", "t": "interdum aequali laterum compagine ductus"}, {"st": "1.841", "t": "quadratamve trabem fingit teretemve columnam."}, {"st": "1.842", "t": "quin etiam tumidis exaequat dolia flammis"}, {"st": "1.843", "t": "procere distenta uteros, parvosque catillos"}, {"st": "1.844", "t": "mentitur curvos ignis glomeratus in orbes."}, {"st": "1.846", "t": "lampadas et fissas ramosos fundit in ignes."}, {"st": "1.847", "t": "praecipites stellae passimque volare videntur,"}, {"st": "1.848", "t": "cum vaga per nitidum scintillant lumina mundum"}, {"st": "1.849", "t": "et tenuem longis iaculantur crinibus ignem;"}, {"st": "1.850", "t": "excurruntque procul volucris imitata sagittas,"}, {"st": "1.851", "t": "arida cum gracili tenuatur semita filo."}, {"st": "1.852", "t": "sunt autem cunctis permixti partibus ignes,"}, {"st": "1.853", "t": "qui gravidas habitant fabricantis fulmina nubes"}, {"st": "1.854", "t": "et penetrant terras Aetnamque minantur Olympo"}, {"st": "1.855", "t": "et calidas reddunt ipsis in fontibus undas"}, {"st": "1.856", "t": "ac silice in dura viridique in cortice sedem"}, {"st": "1.857", "t": "inveniunt, cum silva sibi collisa crematur:"}, {"st": "1.858", "t": "ignibus usque adeo natura est omnis abundans."}, {"st": "1.859", "t": "ne mirere faces subitas erumpere caelo"}, {"st": "1.860", "t": "aeraque accensum flammis lucere coruscis"}, {"st": "1.861", "t": "arida complexum spirantis semina terrae,"}, {"st": "1.862", "t": "quae volucer pascens ignis sequiturque fugitque,"}, {"st": "1.863", "t": "fulgura cum videas tremulum vibrantia lumen,"}, {"st": "1.864", "t": "imbribus e mediis et caelum fulmine ruptum, --"}, {"st": "1.865", "t": "sive igitur ratio praebentis semina terrae"}, {"st": "1.866", "t": "in volucres ignes potuit generate cometas,"}, {"st": "1.867", "t": "sive illas natura faces ut cuncta creavit"}, {"st": "1.868", "t": "sidera per tenues caelo lucentia flammas,"}, {"st": "1.869", "t": "(sed trahit ad semet rapido Titanius aestu"}, {"st": "1.870", "t": "involvitque suo flammantis igne cometas,"}, {"st": "1.871", "t": "ac modo dimittit, sicut Cyllenius orbis"}, {"st": "1.872", "t": "et Venus, accenso cum ducit vespere noctem,"}, {"st": "1.873", "t": "saepe nitent falluntque oculos rursusque revisunt)"}, {"st": "1.874", "t": "seu deus instantis fati miseratus in orbem"}, {"st": "1.875", "t": "signa per affectus caelique incendia mittit;"}, {"st": "1.876", "t": "numquam futtilibus excanduit ignibus aether:"}, {"st": "1.877", "t": "squalidaque elusi deplorant arva coloni,"}, {"st": "1.878", "t": "et sterilis inter sulcos defessus arator"}, {"st": "1.879", "t": "ad iuga maerentis cogit frustrata iuvencos."}, {"st": "1.880", "t": "aut gravibus morbis et lenta corpora tabe"}, {"st": "1.881", "t": "corripit exustis letalis flamma medullis"}, {"st": "1.882", "t": "labentisque rapit populos, totasque per urbes"}, {"st": "1.883", "t": "publica succensis peraguntur fata sepulcris."}, {"st": "1.884", "t": "qualis Erechtheos pestis populata colonos"}, {"st": "1.885", "t": "extulit antiquas per funera pacis Athenas,"}, {"st": "1.886", "t": "alter in alterius labens cum fata ruebant."}, {"st": "1.887", "t": "nec locus artis erat medicae nec vota valebant;"}, {"st": "1.888", "t": "cesserat officium morbis, et funera deerant"}, {"st": "1.889", "t": "mortibus et lacrimae; lassus defecerat ignis,"}, {"st": "1.890", "t": "et coacervatis ardebant corpora membris,"}, {"st": "1.891", "t": "ac tanto quondam populo vix contigit heres."}, {"st": "1.892", "t": "talia significant lucentes saepe cometae:"}, {"st": "1.893", "t": "funera cum facibus veniunt terrisque minantur"}, {"st": "1.894", "t": "ardentis sine fine rogos, cum mundus et ipsa"}, {"st": "1.895", "t": "aegrotet natura, hominum sortita sepulcrum."}, {"st": "1.896", "t": "quin et bella canunt ignes subitosque tumultus"}, {"st": "1.897", "t": "et clandestinis surgentia fraudibus arma,"}, {"st": "1.898", "t": "externas modo per gentes, -- ut foedere rupto"}, {"st": "1.899", "t": "cum fera ductorem rapuit Germania Varum"}, {"st": "1.900", "t": "infecitque trium legionum sanguine campos,"}, {"st": "1.901", "t": "arserunt toto passim minitantia mundo"}, {"st": "1.902", "t": "lumina, et ipsa tulit bellum natura per ignes"}, {"st": "1.903", "t": "opposuitque suas vires finemque minata est."}, {"st": "1.904", "t": "nec mirere graves rerumque hominumque ruinas:"}, {"st": "1.905", "t": "saepe domi culpa est; nescimus credere caelo; --"}, {"st": "1.906", "t": "civilis etiam motus cognataque bella"}, {"st": "1.907", "t": "significant. nec plura alias incendia mundus"}, {"st": "1.908", "t": "sustinuit, quam cum ducibus iurata cruentis"}, {"st": "1.909", "t": "arma Philippeos implerunt agmine campos."}, {"st": "1.910", "t": "vixque etiam sicca miles Romanus harena"}, {"st": "1.911", "t": "ossa verum lacerosque prius superastitit artus,"}, {"st": "1.912", "t": "imperiumque suis conflixit viribus ipsum,"}, {"st": "1.913", "t": "perque patris pater Augustus vestigia vicit."}, {"st": "1.914", "t": "necdum finis erat: restabant Actia bella"}, {"st": "1.915", "t": "dotali commissa acie, repetitaque rerum"}, {"st": "1.916", "t": "alea, et in ponto quaesitus rector Olympi,"}, {"st": "1.917", "t": "femineum sortita iugum cum Roma pependit,"}, {"st": "1.918", "t": "atque ipsa Isiaco certarunt fulmina sistro."}, {"st": "1.919", "t": "restabant profugo servilia milite bella,"}, {"st": "1.920", "t": "cum patrios armis imitatus filius hostis"}, {"st": "1.921", "t": "aequora Pompeius cepit defensa parenti."}, {"st": "1.922", "t": "sed satis hoc fatis fuerit. iam bella quiescant,"}, {"st": "1.923", "t": "atque adamanteis discordia vincta catenis"}, {"st": "1.924", "t": "aeternos habeat frenos in carcere clausa."}, {"st": "1.925", "t": "sit pater invictus patriae, sit Roma sub illo,"}, {"st": "1.926", "t": "cumque deum caelo dederit, non quaerat in orbe."}, {"sp": "HDR", "t": "Liber II"}, {"st": "2.1", "t": "Maximus Iliacae gentis certamina vates"}, {"st": "2.2", "t": "et quinquaginta regum regemque patremque"}, {"st": "2.3", "t": "Hectoraque Aeacidae victamque sub Hectore Troiam,"}, {"st": "2.4", "t": "erroremque ducis totidem, quot vicerat, annis"}, {"st": "2.5", "t": "&lt;infestum experti dominum maris atque renato 4a"}, {"st": "2.6", "t": "instantem bello geminataque Pergama ponto"}, {"st": "2.7", "t": "ultimaque in patria captisque penatibus arma"}, {"st": "2.8", "t": "ore sacro cecinit; patriam cui turba petentum,"}, {"st": "2.9", "t": "dum dabat, eripuit, cuiusque ex ore profusos"}, {"st": "2.10", "t": "omnis posteritas latices in carmina duxit"}, {"st": "2.11", "t": "amnemque in tenuis ausa est deducere rivos 10"}, {"st": "2.12", "t": "unius fecunda bonis. sed proximus illi"}, {"st": "2.13", "t": "Hesiodus memorat divos divumque parentes"}, {"st": "2.14", "t": "et chaos enixum terras orbemque sub illo"}, {"st": "2.15", "t": "infantem et primos titubantia sidera cursus"}, {"st": "2.16", "t": "Titanasque senes, Iovis et cunabula magni 15"}, {"st": "2.17", "t": "et sub fratre viri nomen, sine matre parentis,"}, {"st": "2.18", "t": "atque iterum patrio nascentem corpore Bacchum,"}, {"st": "2.19", "t": "silvarumque deos secretaque numina Nymphas. 23"}, {"st": "2.20", "t": "quin etiam ruris cultus legesque notavit 19"}, {"st": "2.21", "t": "militiamque soli, quod colles Bacchus amaret,"}, {"st": "2.22", "t": "quod fecunda Ceres campos, quod Pallas utrumque,"}, {"st": "2.23", "t": "atque arbusta vagis essent quod adultera pomis;"}, {"st": "2.24", "t": "omniaque immenso volitantia lumina mundo, 18"}, {"st": "2.25", "t": "pacis opus, magnos naturae condit in usus. 24"}, {"st": "2.26", "t": "astrorum quidam varias dixere figuras,"}, {"st": "2.27", "t": "signaque diffuso passim labentia caelo"}, {"st": "2.28", "t": "in proprium cuiusque genus causasque tulere;"}, {"st": "2.29", "t": "Persea et Andromedan poena matremque dolentem"}, {"st": "2.30", "t": "solventemque patrem, raptamque Lycaone natam,"}, {"st": "2.31", "t": "officioque Iovis Cynosuram, lacte Capellam 30"}, {"st": "2.32", "t": "et furto Cycnum, pietate ad sidera ductam"}, {"st": "2.33", "t": "Erigonen ictuque Nepam spolioque Leonem"}, {"st": "2.34", "t": "et morsu Cancrum, Pisces Cythereide versa,"}, {"st": "2.35", "t": "Lanigerum victo ducentem sidera ponto,"}, {"st": "2.36", "t": "ceteraque ex variis pendentia casibus astra 35"}, {"st": "2.37", "t": "aethera per summum voluerunt fixa revolvi."}, {"st": "2.38", "t": "quorum carminibus nihil est nisi fabula caelum"}, {"st": "2.39", "t": "terraque composuit mundum quae pendet ab illo."}, {"st": "2.40", "t": "quin etiam ritus pastorum et Pana sonantem"}, {"st": "2.41", "t": "in calamos Sicula memorat tellure creatus, 40"}, {"st": "2.42", "t": "nec silvis silvestre canit perque horrida motus"}, {"st": "2.43", "t": "rura serit dulcis Musamque inducit in aulas."}, {"st": "2.44", "t": "ecce alius pictas volucres ac bella ferarum,"}, {"st": "2.45", "t": "ille venenatos angues aconitaque et herbas"}, {"st": "2.46", "t": "fata refert vitamque sua radice ferentis. 45"}, {"st": "2.47", "t": "quin etiam tenebris immersum Tartaron atra"}, {"st": "2.48", "t": "in lucem de nocte vocant orbemque revolvunt"}, {"st": "2.49", "t": "interius versum naturae foedere rupto."}, {"st": "2.50", "t": "omne genus rerum doctae cecinere sorores,"}, {"st": "2.51", "t": "omnis ad accessus Heliconos semita trita est, 50"}, {"st": "2.52", "t": "et iam confusi manant de fontibus amnes"}, {"st": "2.53", "t": "nec capiunt haustum turbamque ad nota ruentem."}, {"st": "2.54", "t": "integra quaeramus rorantis prata per herbas"}, {"st": "2.55", "t": "undamque occultis meditantem murmur in antris,"}, {"st": "2.56", "t": "quam neque durato gustarint ore volucres, 55"}, {"st": "2.57", "t": "ipse nec aetherio Phoebus libaverit igni."}, {"st": "2.58", "t": "nostra loquar, nulli vatum debebimus orsa,"}, {"st": "2.59", "t": "nec furtum sed opus veniet, soloque volamus"}, {"st": "2.60", "t": "in caelum curru, propria rate pellimus undas."}, {"st": "2.61", "t": "namque canam tacita naturae mente potentem 60"}, {"st": "2.62", "t": "infusumque deum caelo terrisque fretoque"}, {"st": "2.63", "t": "ingentem aequali moderantem foedere molem,"}, {"st": "2.64", "t": "totumque alterno consensu vivere mundum"}, {"st": "2.65", "t": "et rationis agi motu, cum spiritus unus"}, {"st": "2.66", "t": "per cunctas habitet partes atque irriget orbem 65"}, {"st": "2.67", "t": "omnia pervolitans corpusque animale figuret."}, {"st": "2.68", "t": "quod nisi cognatis membris contexta maneret"}, {"st": "2.69", "t": "machina et imposito pareret tota magistro"}, {"st": "2.70", "t": "ac tantum mundi regeret prudentia censum,"}, {"st": "2.71", "t": "non esset statio terris, non ambitus astris, 70"}, {"st": "2.72", "t": "erraretque vagus mundus standove rigeret,"}, {"st": "2.73", "t": "nec sua dispositos servarent sidera cursus"}, {"st": "2.74", "t": "noxque alterna diem fugeret rursumque fugaret,"}, {"st": "2.75", "t": "non imbres alerent terras, non aethera venti"}, {"st": "2.76", "t": "nec pontus gravidas nubes nec flumina pontum 75"}, {"st": "2.77", "t": "nec pelagus fontes, nec staret summa per omnis"}, {"st": "2.78", "t": "par semper partes aequo digesta parente,"}, {"st": "2.79", "t": "ut neque deficerent undae nec sideret orbis"}, {"st": "2.80", "t": "nec caelum iusto maiusve minusve volaret."}, {"st": "2.81", "t": "motus alit, non mutat opus. sic omnia toto 80"}, {"st": "2.82", "t": "dispensata manent mundo dominumque sequuntur."}, {"st": "2.83", "t": "hic igitur deus et ratio, quae cuncta gubernat,"}, {"st": "2.84", "t": "ducit ab aetheriis terrena animalia signis,"}, {"st": "2.85", "t": "quae, quamquam longo, cogit, summota recessu,"}, {"st": "2.86", "t": "sentiri tamen, ut vitas ac fata ministrent 85"}, {"st": "2.87", "t": "gentibus ac proprios per singula corpora mores."}, {"st": "2.88", "t": "nec nimis est quaerenda fides: sic temperat arva"}, {"st": "2.89", "t": "caelum, sic varias fruges redditque rapitque,"}, {"st": "2.90", "t": "sic pontum movet ac terris immittit et aufert,"}, {"st": "2.91", "t": "atque haec seditio pelagus nunc sidere lunae 90"}, {"st": "2.92", "t": "mota tenet, nunc diverso stimulata recessu,"}, {"st": "2.93", "t": "nunc anni spatio Phoebum comitata volantem;"}, {"st": "2.94", "t": "sic summersa fretis, concharum et carcere clausa,"}, {"st": "2.95", "t": "ad lunae motum variant animalia corpus"}, {"st": "2.96", "t": "et tua damna, tuas imitantur, Delia, vires; 95"}, {"st": "2.97", "t": "tu quoque fraternis sic reddis curribus ora"}, {"st": "2.98", "t": "atque iterum ex isdem repetis, quantumque reliquit"}, {"st": "2.99", "t": "aut dedit ille, refers et sidus sidere constas;"}, {"st": "2.100", "t": "denique sic pecudes et muta animalia terris,"}, {"st": "2.101", "t": "cum maneant ignara sui legisque per aevum, 100"}, {"st": "2.102", "t": "natura tamen ad mundum revocante parentem"}, {"st": "2.103", "t": "attollunt animos caelumque et sidera servant"}, {"st": "2.104", "t": "corporaque ad lunae nascentis cornua lustrant"}, {"st": "2.105", "t": "venturasque vident hiemes, reditura serena."}, {"st": "2.106", "t": "quis dubitet post haec hominem coniungere caelo, 105"}, {"st": "2.107", "t": "&lt;cui, cupiens terras ad sidera surgere, munus&gt; 105a"}, {"st": "2.108", "t": "eximium natura dedit linguamque capaxque"}, {"st": "2.109", "t": "ingenium volucremque animum, quem denique in unum"}, {"st": "2.110", "t": "descendit deus atque habitat seque ipse requirit?"}, {"st": "2.111", "t": "mitte alias artes, quarum est permissa facultas"}, {"st": "2.112", "t": "invidiosa adeo, nec nostri munera census: 110"}, {"st": "2.113", "t": "[mitto quod aequali nihil est sub lege tributum,"}, {"st": "2.114", "t": "quo patet auctoris summam, non corporis, esse;"}, {"st": "2.115", "t": "mitto quod certum est et inevitabile fatum"}, {"st": "2.116", "t": "materiaeque datum est cogi sed cogere mundo]"}, {"st": "2.117", "t": "quis caelum posset nisi caeli munere nosse, 115"}, {"st": "2.118", "t": "et reperire deum, nisi qui pars ipse deorum est?"}, {"st": "2.119", "t": "quisve hanc convexi molem sine fine patentis"}, {"st": "2.120", "t": "signorumque choros ac mundi flammea tecta,"}, {"st": "2.121", "t": "aeternum et stellis adversus sidera bellum"}, {"st": "2.122", "t": "[ac terras caeloque fretum subiectaque utrisque] 120"}, {"st": "2.123", "t": "cernere et angusto sub pectore claudere posset,"}, {"st": "2.124", "t": "ni sanctos animis oculos natura dedisset"}, {"st": "2.125", "t": "cognatamque sibi mentem vertisset ad ipsam"}, {"st": "2.126", "t": "et tantum dictasset opus, caeloque veniret"}, {"st": "2.127", "t": "quod vocat in caelum sacra ad commercia rerum? 125"}, {"st": "2.128", "t": "quis neget esse nefas invitum prendere mundum 127"}, {"st": "2.129", "t": "et velut in semet captum deducere in orbem?"}, {"st": "2.130", "t": "sed, ne circuitu longo manifesta probentur,"}, {"st": "2.131", "t": "ipsa fides operi faciet pondusque fidemque; 130"}, {"st": "2.132", "t": "nam neque decipitur ratio nec decipit umquam."}, {"st": "2.133", "t": "rite sequenda via est ac veris credita causis,"}, {"st": "2.134", "t": "eventusque datur qualis praedicitur ante."}, {"st": "2.135", "t": "quod Fortuna ratum faciat, quis dicere falsum"}, {"st": "2.136", "t": "audeat et tantae suffragia vincere sortis? 135"}, {"st": "2.137", "t": "Haec ego divino cupiam cum ad sidera flatu"}, {"st": "2.138", "t": "ferre, nec in turba nec turbae carmina condam"}, {"st": "2.139", "t": "sed solus, vacuo veluti vectatus in orbe"}, {"st": "2.140", "t": "liber agam currus non occursantibus ullis"}, {"st": "2.141", "t": "nec per iter socios commune regentibus actus, 140"}, {"st": "2.142", "t": "sed caelo noscenda canam, mirantibus astris"}, {"st": "2.143", "t": "et gaudente sui mundo per carmina vatis,"}, {"st": "2.144", "t": "vel quibus illa sacros non invidere meatus"}, {"st": "2.145", "t": "notitiamque sui, minima est quae turba per orbem."}, {"st": "2.146", "t": "illa frequens, quae divitias, quae diligit aurum, 145"}, {"st": "2.147", "t": "imperia et fasces mollemque per otia luxum"}, {"st": "2.148", "t": "et blandis diversa sonis dulcemque per aures"}, {"st": "2.149", "t": "affectum, ut modico noscenda ad fata labore."}, {"st": "2.150", "t": "hoc quoque fatorum est, legem perdiscere fati."}, {"st": "2.151", "t": "Et primum astrorum varia est natura notanda 150"}, {"st": "2.152", "t": "carminibus per utrumque genus. nam mascula sex sunt,"}, {"st": "2.153", "t": "diversi totidem generis sub principe Tauro:"}, {"st": "2.154", "t": "cernis ut aversos redeundo surgat in artus."}, {"st": "2.155", "t": "alternant genus et vicibus variantur in orbem."}, {"st": "2.156", "t": "Humanas etiam species in parte videbis, 155"}, {"st": "2.157", "t": "nec mores distant: pecudum pars atque ferarum"}, {"st": "2.158", "t": "ingenium facient. quaedam signanda sagaci"}, {"st": "2.159", "t": "singula sunt animo, propria quae sorte feruntur:"}, {"st": "2.160", "t": "nunc binis insiste; dabunt geminata potentis"}, {"st": "2.161", "t": "per socium effectus. multum comes addit et aufert, 160"}, {"st": "2.162", "t": "ambiguisque valent, quis sunt collegia, fatis"}, {"st": "2.163", "t": "ad meritum noxamque. duos per sidera Pisces"}, {"st": "2.164", "t": "et totidem Geminos nudatis aspice membris."}, {"st": "2.165", "t": "his coniuncta manent alterno bracchia nexu,"}, {"st": "2.166", "t": "dissimile est illis iter in contraria versis. 165"}, {"st": "2.167", "t": "par numerus, sed enim dispar natura notanda est."}, {"st": "2.168", "t": "atque haec ex paribus toto gaudentia censu"}, {"st": "2.169", "t": "signa meant, nihil exterius mirantur in ipsis"}, {"st": "2.170", "t": "amissumve dolent, quaedam quod, parte recisa"}, {"st": "2.171", "t": "atque ex diverso commissis corpore membris, 170"}, {"st": "2.172", "t": "ut Capricornus et intentum qui derigit arcum"}, {"st": "2.173", "t": "iunctus equo: pars huic hominis, sed nulla priori."}, {"st": "2.174", "t": "[hoc quoque servandum est alta discrimen in arte,"}, {"st": "2.175", "t": "distat enim gemini duo sint duplane figura]"}, {"st": "2.176", "t": "quin etiam Erigone binis numeratur in astris, 175"}, {"st": "2.177", "t": "nec facies ratio duplex; nam desinit aestas,"}, {"st": "2.178", "t": "incipit autumnus media sub Virgine utrimque."}, {"st": "2.179", "t": "idcirco tropicis praecedunt omnibus astra"}, {"st": "2.180", "t": "bina, ut Lanigero, Chelis Cancroque Caproque,"}, {"st": "2.181", "t": "quod duplicis retinent conexo tempore vires. 180"}, {"st": "2.182", "t": "ut, quos subsequitur Cancer per sidera fratres,"}, {"st": "2.183", "t": "e geminis alter florentia tempora veris"}, {"st": "2.184", "t": "sufficit, aestatem sitientem provehit alter;"}, {"st": "2.185", "t": "nudus uterque tamen, sentit quia uterque calorem,"}, {"st": "2.186", "t": "ille senescentis veris, subeuntis at ille 185"}, {"st": "2.187", "t": "aestatis: par est primae sors ultima parti."}, {"st": "2.188", "t": "quin etiam Arcitenens, qui te, Capricorne, sub ipso"}, {"st": "2.189", "t": "promittit, duplici formatus imagine fertur:"}, {"st": "2.190", "t": "mitior autumnus mollis sibi vindicat artus"}, {"st": "2.191", "t": "materiamque hominis, fera tergo membra rigentem 190"}, {"st": "2.192", "t": "excipiunt hiemem mutantque in tempora signum."}, {"st": "2.193", "t": "quosque Aries prae se mittit, duo tempora Pisces"}, {"st": "2.194", "t": "bina dicant: hiemem hic claudit, ver incohat alter."}, {"st": "2.195", "t": "cum sol aequoreis revolans decurrit in astris,"}, {"st": "2.196", "t": "hiberni coeunt cum vernis roribus imbres. 195"}, {"st": "2.197", "t": "utraque sors umoris habet fluitantia signa."}, {"st": "2.198", "t": "Quin tria signa novem signis coniuncta repugnant"}, {"st": "2.199", "t": "et quasi seditio caelum tenet. aspice Taurum"}, {"st": "2.200", "t": "clunibus et Geminos pedibus, testudine Cancrum"}, {"st": "2.201", "t": "surgere, cum rectis oriantur cetera membris; 200"}, {"st": "2.202", "t": "ne mirere moras, cum sol aversa per astra"}, {"st": "2.203", "t": "aestivum tardis attollat mensibus annum."}, {"st": "2.204", "t": "Nec te praetereat nocturna diurnaque signa"}, {"st": "2.205", "t": "quae sint perspicere et propria deducere lege,"}, {"st": "2.206", "t": "non tenebris aut luce suam peragentia sortem 205"}, {"st": "2.207", "t": "(nam commune foret nullo discrimine nomen,"}, {"st": "2.208", "t": "omnia quod certis vicibus per tempora fulgent"}, {"st": "2.209", "t": "et nunc illa dies, nunc noctes illa sequuntur),"}, {"st": "2.210", "t": "sed quibus illa parens mundi natura sacratas"}, {"st": "2.211", "t": "temporis attribuit partes statione perenni. 210"}, {"st": "2.212", "t": "namque Sagittari signum rabidique Leonis"}, {"st": "2.213", "t": "et sua respiciens aurato vellere terga,"}, {"st": "2.214", "t": "tum Pisces &lt;et&gt; Cancer et acri Scorpios ictu,"}, {"st": "2.215", "t": "aut vicina loco, divisa aut partibus aequis,"}, {"st": "2.216", "t": "omnia dicuntur simili sub sorte diurna. 215"}, {"st": "2.217", "t": "cetera, vel numero consortia vel vice sedis,"}, {"st": "2.218", "t": "interiecta locis totidem, nocturna feruntur."}, {"st": "2.219", "t": "quidam etiam sex continuis dixere diurnas"}, {"st": "2.220", "t": "esse vices astris, quae sunt a principe signo"}, {"st": "2.221", "t": "Lanigeri, sex a Libra nocturna videri. 220"}, {"st": "2.222", "t": "sunt quibus esse diurna placet quae mascula surgunt,"}, {"st": "2.223", "t": "femineam sortem tutis gaudere tenebris."}, {"st": "2.224", "t": "Quin non nulla tibi nullo monstrante loquuntur"}, {"st": "2.225", "t": "Neptuno debere genus, scopulosus in undis"}, {"st": "2.226", "t": "Cancer et effuso gaudentes aequore Pisces. 225"}, {"st": "2.227", "t": "at, quae terrena censentur sidera sorte,"}, {"st": "2.228", "t": "princeps armenti Taurus regnoque superbus"}, {"st": "2.229", "t": "lanigeri gregis est Aries pestisque duorum"}, {"st": "2.230", "t": "praedatorque Leo &lt;et&gt; dumosis Scorpios arvis."}, {"st": "2.231", "t": "sunt etiam mediae legis communia signa, 230"}, {"st": "2.232", "t": "ambiguus tergo Capricornus, Aquarius undis,"}, {"st": "2.233", "t": "umida terrenis aequali foedere mixta. 233"}, {"st": "2.234", "t": "Non licet a minimis animum deflectere curis,"}, {"st": "2.235", "t": "nec quicquam rationis eget frustrave creatum."}, {"st": "2.236", "t": "fecundum est proprie Cancri genus, acer et ictu"}, {"st": "2.237", "t": "Scorpios, et partu complentes aequora Pisces."}, {"st": "2.238", "t": "sed sterilis Virgo est, simili coniuncta Leoni,"}, {"st": "2.239", "t": "nec capit, aut captos effundit, Aquarius ortus."}, {"st": "2.240", "t": "inter utrumque manet Capricornus corpore mixto 240"}, {"st": "2.241", "t": "et qui Cretaeo fulget Centaurus in arcu,"}, {"st": "2.242", "t": "communisque Aries aequantem tempora Libram"}, {"st": "2.243", "t": "et Geminos Taurumque pari sub sorte recenset."}, {"st": "2.244", "t": "Nec tu nulla putes in eo commenta locasse"}, {"st": "2.245", "t": "naturam rerum, quod sunt currentia quaedam, 245"}, {"st": "2.246", "t": "ut Leo et Arcitenens Ariesque in cornua tortus;"}, {"st": "2.247", "t": "aut quae recta suis librantur stantia membris,"}, {"st": "2.248", "t": "ut Virgo et Gemini, fundens et Aquarius undas;"}, {"st": "2.249", "t": "vel quae fessa sedent pigras referentia mentes,"}, {"st": "2.250", "t": "Taurus depositis collo sopitus aratris, 250"}, {"st": "2.251", "t": "Libra sub emerito considens orbe laborum,"}, {"st": "2.252", "t": "tuque tuos, Capricorne, gelu contractus in artus;"}, {"st": "2.253", "t": "quaeve iacent, Cancer patulam distentus in alvum,"}, {"st": "2.254", "t": "Scorpios incumbens plano sub pectore terrae,"}, {"st": "2.255", "t": "in latus obliqui Pisces semperque iacentes. 255"}, {"st": "2.256", "t": "Quod si sollerti circumspicis omnia cura,"}, {"st": "2.257", "t": "fraudata invenies amissis sidera membris."}, {"st": "2.258", "t": "Scorpios in Libra consumit bracchia, Taurus"}, {"st": "2.259", "t": "succidit incurvo claudus pede, lumina Cancro"}, {"st": "2.260", "t": "desunt, Centauro superest et quaeritur unum. 260"}, {"st": "2.261", "t": "sic nostros casus solatur mundus in astris"}, {"st": "2.262", "t": "exemploque docet patienter damna subire,"}, {"st": "2.263", "t": "omnis cum caelo fortunae pendeat ordo"}, {"st": "2.264", "t": "ipsaque debilibus formentur sidera membris."}, {"st": "2.265", "t": "Temporibus quoque sunt propriis pollentia signa: 265"}, {"st": "2.266", "t": "aestas a Geminis, autumnus Virgine surgit,"}, {"st": "2.267", "t": "bruma Sagittifero, ver Piscibus incipit esse."}, {"st": "2.268", "t": "quattuor in partes scribuntur sidera terna;"}, {"st": "2.269", "t": "hiberna aestivis, autumni verna repugnant."}, {"st": "2.270", "t": "Nec satis est proprias signorum noscere formas 270"}, {"st": "2.271", "t": "et privas quas dant leges nascentibus astra; 126"}, {"st": "2.272", "t": "consensu quoque fata movent et foedere gaudent 271"}, {"st": "2.273", "t": "atque aliis alia succedunt sorte locoque."}, {"st": "2.274", "t": "circulus ut dextro signorum clauditur orbe,"}, {"st": "2.275", "t": "in tris aequalis discurrit linea ductus"}, {"st": "2.276", "t": "inque vicem extremis iungit se finibus ipsa, 275"}, {"st": "2.277", "t": "et, quaecumque ferit, dicuntur signa trigona,"}, {"st": "2.278", "t": "in tria partitus quod ter cadit angulus astra"}, {"st": "2.279", "t": "quae divisa manent ternis distantia signis."}, {"st": "2.280", "t": "Laniger ex paribus spatiis duo signa, Leonis"}, {"st": "2.281", "t": "atque Sagittari, diverso conspicit ortu; 280"}, {"st": "2.282", "t": "Virginis et Tauri Capricorno consonat astrum;"}, {"st": "2.283", "t": "cetera sunt simili ratione triangula signa"}, {"st": "2.284", "t": "per totidem sortes, desunt quae, condita mundo:"}, {"st": "2.285", "t": "[sed discrimen erit dextris laevisque: sinistra"}, {"st": "2.286", "t": "quae subeunt, quae praecedunt dextra esse feruntur; 285"}, {"st": "2.287", "t": "dexter erit Tauro Capricornus, Virgo sinistra]"}, {"st": "2.288", "t": "hoc satis exemplo est. at, quae divisa quaternis"}, {"st": "2.289", "t": "partibus aequali laterum sunt condita ductu"}, {"st": "2.290", "t": "quorum designat normalis virgula sedes,"}, {"st": "2.291", "t": "haec quadrata ferunt. Libram Capricornus et illum 290"}, {"st": "2.292", "t": "conspicit ante Aries atque ipsum a partibus aequis"}, {"st": "2.293", "t": "Cancer et hunc laeva subeuntis sidera Librae."}, {"st": "2.294", "t": "semper enim &lt;in&gt; dextris censentur signa priora."}, {"st": "2.295", "t": "sic licet in totidem partes diducere cuncta"}, {"st": "2.296", "t": "ternaque bis senis quadrata effingere signis, 295"}, {"st": "2.297", "t": "quorum proposito reddentur in ordine vires."}, {"st": "2.298", "t": "Sed siquis contentus erit numerasse quadrata,"}, {"st": "2.299", "t": "divisum &lt;ut&gt; signis mundum putet esse quaternis,"}, {"st": "2.300", "t": "aut tribus ac binis signis ornare trigonum,"}, {"st": "2.301", "t": "ut socias vires et amicos exigat ortus 300"}, {"st": "2.302", "t": "foederaque inveniat mundi cognata per astra,"}, {"st": "2.303", "t": "falsus erit. nam, quina licet sint undique signa,"}, {"st": "2.304", "t": "qui tamen e trinis, quae quinto quoque feruntur"}, {"st": "2.305", "t": "astra loco, fuerint nati, sentire trigoni"}, {"st": "2.306", "t": "non poterunt vires: licet illud nomine servent, 305"}, {"st": "2.307", "t": "amisere loco dotes numerisque repugnant."}, {"st": "2.308", "t": "nam, cum sint partes orbis per signa trecentae"}, {"st": "2.309", "t": "et ter vicenae, quas Phoebi circuit ardor,"}, {"st": "2.310", "t": "tertia pars eius numeri latus efficit unum"}, {"st": "2.311", "t": "in tris perducti partes per signa trigoni. 310"}, {"st": "2.312", "t": "hanc autem numeri non reddit linea summam,"}, {"st": "2.313", "t": "si signum signo, non pars a parte notetur,"}, {"st": "2.314", "t": "quod, quamvis duo sunt ternis dirimentibus astra,"}, {"st": "2.315", "t": "si tamen extremam laevi primamque prioris"}, {"st": "2.316", "t": "inter se conferre voles numerumque notare, 315"}, {"st": "2.317", "t": "ter quinquagenas implebunt ordine partes;"}, {"st": "2.318", "t": "transibit numerus formam finesque sequentis"}, {"st": "2.319", "t": "consumet ductus. licet ergo signa trigona"}, {"st": "2.320", "t": "dicantur, partes non servant illa trigonas."}, {"st": "2.321", "t": "haec eadem species fallet per signa quadrata 320"}, {"st": "2.322", "t": "(quod, cum totius numeri, qui construit orbem,"}, {"st": "2.323", "t": "ter denae quadrum partes per sidera reddant,"}, {"st": "2.324", "t": "evenit ut, prima signi de parte prioris"}, {"st": "2.325", "t": "si partem ad summam ducatur virga sequentis,"}, {"st": "2.326", "t": "bis sexagenas faciat; sin summa prioris 325"}, {"st": "2.327", "t": "et pars confertur subeuntis prima, duorum"}, {"st": "2.328", "t": "signorum in medio numerum transique referque,"}, {"st": "2.329", "t": "triginta duplicat partes, pars tertia derit);"}, {"st": "2.330", "t": "et, quamvis quartum a quarto quis computet astrum,"}, {"st": "2.331", "t": "naufragium facient partes unius in ipsis. 330"}, {"st": "2.332", "t": "non igitur satis est signis numerasse trigona"}, {"st": "2.333", "t": "quadrative fidem quaeri per signa quaterna."}, {"st": "2.334", "t": "quadrati si forte voles effingere formam,"}, {"st": "2.335", "t": "aut trinis paribus facies cum membra trigoni,"}, {"st": "2.336", "t": "hic poscit quintam partem centesima summa, 335"}, {"st": "2.337", "t": "illic amittit decimam. sic convenit ordo."}, {"st": "2.338", "t": "et, quiscumque quater iunctis favet angulus usque,"}, {"st": "2.339", "t": "quaeque loca in triplici signarit linea ductu"}, {"st": "2.340", "t": "cum sinuata viae linquet dispendia recta,"}, {"st": "2.341", "t": "his natura dedit communi foedera lege 340"}, {"st": "2.342", "t": "inque vicem affectus et mutua iura favoris."}, {"st": "2.343", "t": "quocirca non omnis habet genitura trigonis"}, {"st": "2.344", "t": "consensum signis, nec, cum sunt forte quadrata, 345"}, {"st": "2.345", "t": "continuo inter se servant commercia rerum."}, {"st": "2.346", "t": "distat enim, partes consumat linea iustas"}, {"st": "2.347", "t": "detrectetne modum numeri, quem circulus ambit,"}, {"st": "2.348", "t": "nunc tris efficiens, nunc quattuor undique ductus,"}, {"st": "2.349", "t": "quos in plura iubet ratio procedere signa 350"}, {"st": "2.350", "t": "interdum, quam sunt numeris memorata per orbem."}, {"st": "2.351", "t": "Sed longe maior vis est per signa trigoni"}, {"st": "2.352", "t": "quam quibus est titulus sub quarto quoque quadratis."}, {"st": "2.353", "t": "altior est horum summoto linea templo,"}, {"st": "2.354", "t": "illa magis vicina meat caeloque recedit 355"}, {"st": "2.355", "t": "et propius terras accedit visus eorum"}, {"st": "2.356", "t": "aeraque infectum nostras demittit ad auras."}, {"st": "2.357", "t": "Debilia alternis data sunt commercia signis,"}, {"st": "2.358", "t": "mutua nec magno consensu foedera servant,"}, {"st": "2.359", "t": "invita angusto quod linea flectitur orbe. 360"}, {"st": "2.360", "t": "nam, cum praeteriens formatur singula limes"}, {"st": "2.361", "t": "sidera et alterno devertitur angulus astro"}, {"st": "2.362", "t": "sexque per anfractus curvatur virgula in orbem,"}, {"st": "2.363", "t": "a Tauro venit in Cancrum, tum Virgine tacta"}, {"st": "2.364", "t": "Scorpion ingreditur, tum te, Capricorne, rigentem 365"}, {"st": "2.365", "t": "et geminos a te Pisces aversaque Tauri"}, {"st": "2.366", "t": "sidera contingens finit, qua coeperat, orbem."}, {"st": "2.367", "t": "alterius ductus locus est per transita signa,"}, {"st": "2.368", "t": "utque ea praetereas quae sunt mihi singula dicta,"}, {"st": "2.369", "t": "flexibus et totidem similis sit circulus illi. 370"}, {"st": "2.370", "t": "tertia convexo conduntur signa recessu; 374"}, {"st": "2.371", "t": "transversos igitur fugiunt subeuntia visus, 371"}, {"st": "2.372", "t": "quod nimis inclinata iacent limisque videntur"}, {"st": "2.373", "t": "vicinoque latent: ex recto certior ictus."}, {"st": "2.374", "t": "et, quia succedit convexo linea caelo, 375"}, {"st": "2.375", "t": "singula circuitu quae tantum transeat astra,"}, {"st": "2.376", "t": "visus eis procul est altoque vagatur Olympo"}, {"st": "2.377", "t": "et tenuis vires ex longo mittit in orbem."}, {"st": "2.378", "t": "sed tamen est illis foedus sub lege propinqua,"}, {"st": "2.379", "t": "quod non diversum genus est coeuntibus astris, 380"}, {"st": "2.380", "t": "mascula sed maribus respondent, cetera sexus"}, {"st": "2.381", "t": "feminei secum iungunt commercia mundi."}, {"st": "2.382", "t": "sic, quamquam alternis, par est natura figuris,"}, {"st": "2.383", "t": "et cognata iacent generis sub legibus astra."}, {"st": "2.384", "t": "Iam vero nulla est haerentibus addita signis 385"}, {"st": "2.385", "t": "gratia; nam consensus hebet, quia visus ademptus."}, {"st": "2.386", "t": "in seducta ferunt animos, quae cernere possunt."}, {"st": "2.387", "t": "sunt etiam adversi generis conexa per orbem"}, {"st": "2.388", "t": "mascula femineis semperque obsessa vicissim."}, {"st": "2.389", "t": "[disparibus non ulla datur concordia signis] 390"}, {"st": "2.390", "t": "Sexta quoque in nullas numerantur commoda vires,"}, {"st": "2.391", "t": "virgula per totum quod par non ducitur orbem"}, {"st": "2.392", "t": "sed duo signa ferit mediis summota quaternis,"}, {"st": "2.393", "t": "tertius absumpto ductus non sufficit orbe."}, {"st": "2.394", "t": "At, quae diversis e partibus astra refulgent 395"}, {"st": "2.395", "t": "per medium adverso mundum pendentia vultu"}, {"st": "2.396", "t": "et toto divisa manent contraria caelo"}, {"st": "2.397", "t": "septima quaeque, loco quamvis summota feruntur,"}, {"st": "2.398", "t": "ex longo tamen illa valent viresque ministrant"}, {"st": "2.399", "t": "vel bello vel pace suas, ut tempora poscunt, 400"}, {"st": "2.400", "t": "nunc foedus stellis, nunc et dictantibus iras."}, {"st": "2.401", "t": "quod si forte libet, quae sunt contraria, signa"}, {"st": "2.402", "t": "per titulos celebrare suos sedesque, memento"}, {"st": "2.403", "t": "solstitium brumae, Capricornum opponere Cancro,"}, {"st": "2.404", "t": "Lanigerum Librae (par nox in utroque diesque est), 405"}, {"st": "2.405", "t": "Piscibus Erigonen, iuvenique urnaeque Leonem;"}, {"st": "2.406", "t": "Scorpios e summo cum fulget, Taurus in imo est,"}, {"st": "2.407", "t": "et cadit Arcitenens Geminis orientibus orbi."}, {"st": "2.408", "t": "[hos servant inter sese contraria cursus]"}, {"st": "2.409", "t": "sed, quamquam adversis fulgent contraria signis, 410"}, {"st": "2.410", "t": "natura tamen interdum sociata feruntur,"}, {"st": "2.411", "t": "et genere amplexis concordia mutua surgit:"}, {"st": "2.412", "t": "mascula se paribus vel sic, diversa suorum"}, {"st": "2.413", "t": "respondent generi. Pisces et Virginis artus"}, {"st": "2.414", "t": "adversi volitant, sed amant communia iura, 415"}, {"st": "2.415", "t": "et vincit natura locum; sed vincitur ipsa"}, {"st": "2.416", "t": "temporibus, Cancerque tibi, Capricorne, repugnat"}, {"st": "2.417", "t": "femina femineo, quia brumae dissidet aestas."}, {"st": "2.418", "t": "hinc rigor et glacies nivibusque albentia rura,"}, {"st": "2.419", "t": "hinc sitis et sudor nudusque in collibus orbis, 420"}, {"st": "2.420", "t": "aestivosque dies aequat nox frigida brumae."}, {"st": "2.421", "t": "sic bellum natura gerit, discordat et annus,"}, {"st": "2.422", "t": "ne mirere in ea pugnantia sidera parte."}, {"st": "2.423", "t": "at non Lanigeri signum Libraeque repugnant"}, {"st": "2.424", "t": "in totum, quia ver autumno tempore differt 425"}, {"st": "2.425", "t": "(fructibus hoc implet maturis, floribus illud)"}, {"st": "2.426", "t": "sed ratione pari est, aequatis nocte diebus,"}, {"st": "2.427", "t": "temporaque efficiunt simili concordia textu"}, {"st": "2.428", "t": "permixtosque dies mediis hiemem inter et aestum"}, {"st": "2.429", "t": "articulis uno servantia utrimque tenore 430"}, {"st": "2.430", "t": "quo minus infesto decertent sidera bello."}, {"st": "2.431", "t": "talis erit ratio diversis addita signis."}, {"st": "2.432", "t": "His animadversis rebus quae proxima cura?"}, {"st": "2.433", "t": "noscere tutelas adiectaque numina signis"}, {"st": "2.434", "t": "et quae cuique deo rerum natura dicavit, 435"}, {"st": "2.435", "t": "cum divina dedit magnis virtutibus ora,"}, {"st": "2.436", "t": "condidit et varias sacro sub nomine vires,"}, {"st": "2.437", "t": "pondus uti rebus persona imponere posset."}, {"st": "2.438", "t": "Lanigerum Pallas, Taurum Cytherea tuetur,"}, {"st": "2.439", "t": "formosos Phoebus Geminos; Cyllenie, Cancrum, 440"}, {"st": "2.440", "t": "Iuppiter, et cum matre deum regis ipse Leonem;"}, {"st": "2.441", "t": "spicifera est Virgo Cereris fabricataque Libra"}, {"st": "2.442", "t": "Vulcani; pugnax Mavorti Scorpios haeret;"}, {"st": "2.443", "t": "venantem Diana virum, sed partis equinae,"}, {"st": "2.444", "t": "atque angusta fovet Capricorni sidera Vesta; 445"}, {"st": "2.445", "t": "e Iovis adverso Iunonis Aquarius astrum est"}, {"st": "2.446", "t": "agnoscitque suos Neptunus in aethere Pisces."}, {"st": "2.447", "t": "hinc quoque magna tibi venient momenta futuri,"}, {"st": "2.448", "t": "cum ratio tua per stellas et sidera curret"}, {"st": "2.449", "t": "argumenta petens omni de parte viasque 450"}, {"st": "2.450", "t": "artis, ut ingenio divina potentia surgat"}, {"st": "2.451", "t": "exaequentque fidem caelo mortalia corda."}, {"st": "2.452", "t": "Accipe divisas hominis per sidera partes"}, {"st": "2.453", "t": "singulaque imperiis propriis parentia membra,"}, {"st": "2.454", "t": "in quis praecipuas toto de corpore vires 455"}, {"st": "2.455", "t": "exercent. Aries caput est ante omnia princeps"}, {"st": "2.456", "t": "sortitus censusque sui pulcherrima colla"}, {"st": "2.457", "t": "Taurus, et in Geminis aequali bracchia sorte"}, {"st": "2.458", "t": "scribuntur conexa umeris, pectusque locatum"}, {"st": "2.459", "t": "sub Cancro est, laterum regnum scapulaeque Leonis, 460"}, {"st": "2.460", "t": "Virginis in propriam descendunt ilia sortem,"}, {"st": "2.461", "t": "Libra regit clunes, et Scorpios inguine gaudet,"}, {"st": "2.462", "t": "Centauro femina accedunt, Capricornus utrisque"}, {"st": "2.463", "t": "imperitat genibus, crurum fundentis Aquari"}, {"st": "2.464", "t": "arbitrium est, Piscesque pedum sibi iura reposcunt. 465"}, {"st": "2.465", "t": "Quin etiam propriis inter se legibus astra"}, {"st": "2.466", "t": "conveniunt, ut certa gerant commercia rerum,"}, {"st": "2.467", "t": "inque vicem praestant visus atque auribus haerent"}, {"st": "2.468", "t": "aut odium foedusve gerunt, conversaque quaedam"}, {"st": "2.469", "t": "in semet proprio ducuntur prona favore. 470"}, {"st": "2.470", "t": "idcirco adversis non numquam &lt;est&gt; gratia signis,"}, {"st": "2.471", "t": "et bellum sociata gerunt; alienaque sede"}, {"st": "2.472", "t": "inter se generant coniunctos omne per aevum,"}, {"st": "2.473", "t": "a triquetrisque orti pugnant fugiuntque vicissim;"}, {"st": "2.474", "t": "quod deus, in leges mundum cum conderet omnem, 475"}, {"st": "2.475", "t": "affectus quoque divisit variantibus astris,"}, {"st": "2.476", "t": "atque aliorum oculos, aliorum contulit aures,"}, {"st": "2.477", "t": "iunxit amicitias horum sub foedere certo,"}, {"st": "2.478", "t": "&lt;illis perpetuas statuit discordibus iras,&gt; 478a"}, {"st": "2.479", "t": "cernere ut inter se possent audireque quaedam,"}, {"st": "2.480", "t": "diligerent alia et noxas bellumque moverent,"}, {"st": "2.481", "t": "his etiam propriae foret indulgentia sortis,"}, {"st": "2.482", "t": "ut se diligerent semper sibique ipsa placerent;"}, {"st": "2.483", "t": "sicut naturas hominum plerasque videmus"}, {"st": "2.484", "t": "qui genus ex signis ducunt formantibus ortus."}, {"st": "2.485", "t": "Consilium ipse suum est Aries, ut principe dignum est, 485"}, {"st": "2.486", "t": "audit se Libramque videt, frustratur amando"}, {"st": "2.487", "t": "Taurum; Lanigero qui fraudem nectit et ultra"}, {"st": "2.488", "t": "fulgentis geminos audit per sidera Pisces,"}, {"st": "2.489", "t": "Virgine mens capitur visa. sic vexerat ante"}, {"st": "2.490", "t": "Europam dorso retinentem cornua laeva 490"}, {"st": "2.491", "t": "indutusque Iovi. Geminorum ducitur auris"}, {"st": "2.492", "t": "ad iuvenem aeternas fundentem Piscibus undas"}, {"st": "2.493", "t": "inque ipsos animus Pisces oculique Leonem."}, {"st": "2.494", "t": "Cancer et adverso Capricornus conditus astro"}, {"st": "2.495", "t": "in semet vertunt oculos, in mutua tendunt 495"}, {"st": "2.496", "t": "auribus, et Cancri captatur Aquarius astu."}, {"st": "2.497", "t": "at Leo cum Geminis aciem coniungit et aurem"}, {"st": "2.498", "t": "Centauro ferus et Capricorni diligit astrum."}, {"st": "2.499", "t": "Erigone Taurum spectat sed Scorpion audit"}, {"st": "2.500", "t": "atque Sagittifero conatur nectere fraudem. 500"}, {"st": "2.501", "t": "Libra suos sequitur sensus solumque videndo"}, {"st": "2.502", "t": "Lanigerum atque animo complexa est Scorpion infra."}, {"st": "2.503", "t": "ille videt Pisces, audit quae proxima Librae."}, {"st": "2.504", "t": "nec non Arcitenens magno parere Leoni"}, {"st": "2.505", "t": "auribus atque oculis sinum fundentis Aquari 505"}, {"st": "2.506", "t": "conspicere assuevit solamque ex omnibus astris"}, {"st": "2.507", "t": "diligit Erigonen. contra Capricornus in ipsum"}, {"st": "2.508", "t": "convertit visus (quid enim mirabitur ille"}, {"st": "2.509", "t": "maius, in Augusti felix cum fulserit ortum?)"}, {"st": "2.510", "t": "auribus et summi captat fastigia Cancri. 510"}, {"st": "2.511", "t": "at nudus Geminis intendit Aquarius aurem"}, {"st": "2.512", "t": "sublimemque colit Cancrum spectatque reducta"}, {"st": "2.513", "t": "tela Sagittiferi. Pisces ad Scorpion acrem"}, {"st": "2.514", "t": "derexere aciem cupiuntque attendere Taurum."}, {"st": "2.515", "t": "has natura vices tribuit, cum sidera fixit. 515"}, {"st": "2.516", "t": "his orti similis referunt per mutua sensus,"}, {"st": "2.517", "t": "audire ut cupiant alios aliosque videre,"}, {"st": "2.518", "t": "[horum odio nunc horum idem ducuntur amore]"}, {"st": "2.519", "t": "illis insidias tendant, captentur ab illis."}, {"st": "2.520", "t": "Quin adversa meant alterna trigona trigonis, 520"}, {"st": "2.521", "t": "alteraque in bellum diverso limite ducit"}, {"st": "2.522", "t": "linea. sic veri per totum consonat ordo."}, {"st": "2.523", "t": "namque Aries, Leo et Arcitenens, sociata trigona"}, {"st": "2.524", "t": "signa, negant Chelis foedus totique trigono"}, {"st": "2.525", "t": "quod Gemini excipiunt fundens et Aquarius undas. 525"}, {"st": "2.526", "t": "idque duplex ratio cogit verum esse fateri,"}, {"st": "2.527", "t": "quod tria signa tribus signis contraria fulgent,"}, {"st": "2.528", "t": "quodque aeterna manent hominum bella atque ferarum."}, {"st": "2.529", "t": "[humana est facies Librae, diversa Leonis]"}, {"st": "2.530", "t": "idcirco et cedunt pecudes, quod viribus amplis 530"}, {"st": "2.531", "t": "consilium est maius. victus Leo fulget in astris,"}, {"st": "2.532", "t": "aurea Lanigero concessit sidera pellis,"}, {"st": "2.533", "t": "ipse suae parti Centaurus tergore cedit,"}, {"st": "2.534", "t": "usque adeo est hominis virtus. quid mirer ab illis"}, {"st": "2.535", "t": "nascentis Librae superari posse trigono? 535"}, {"st": "2.536", "t": "Nec sola est ratio quae dat nascentibus arma 570"}, {"st": "2.537", "t": "inque odium generat partus et mutua bella;"}, {"st": "2.538", "t": "sed plerumque manent inimica tertia quaeque"}, {"st": "2.539", "t": "lege, in transversum vultu defixa maligno,"}, {"st": "2.540", "t": "quodque, manent quaecumque loco contraria signa"}, {"st": "2.541", "t": "adversosque gerunt inter se septima visus, 575"}, {"st": "2.542", "t": "tertia quaeque illis utriusque trigona feruntur;"}, {"st": "2.543", "t": "ne sit mirandum si foedus non datur astris"}, {"st": "2.544", "t": "quae sunt adversis signis cognata trigona."}, {"st": "2.545", "t": "quin etiam brevior ratio est per signa sequenda; 536"}, {"st": "2.546", "t": "nam, quaecumque nitent humana condita forma"}, {"st": "2.547", "t": "astra, manent illis inimica et victa ferarum."}, {"st": "2.548", "t": "sed tamen in proprias secedunt singula mentes"}, {"st": "2.549", "t": "et privata gerunt secretis hostibus arma. 540"}, {"st": "2.550", "t": "Lanigero genitis bellum est cum Virgine natis"}, {"st": "2.551", "t": "et Libra Geminisque et eis quos protulit Urna."}, {"st": "2.552", "t": "in partus Tauri sub Cancro nata feruntur"}, {"st": "2.553", "t": "pectora et in Chelis et quae dant Scorpios acer"}, {"st": "2.554", "t": "et Pisces. at, quos Geminorum sidera formant, 545"}, {"st": "2.555", "t": "his cum Lanigero bellum est eiusque trigono."}, {"st": "2.556", "t": "in Cancro genitos Capricorni semina laedunt"}, {"st": "2.557", "t": "et Librae partus et quos dat Virginis astrum"}, {"st": "2.558", "t": "quique sub aversi numerantur sidere Tauri."}, {"st": "2.559", "t": "Lanigeri communis erit rabidique Leonis 550"}, {"st": "2.560", "t": "hostis, et a totidem bellum subscribitur astris."}, {"st": "2.561", "t": "Erigone Cancrumque timet geminique sub arcu"}, {"st": "2.562", "t": "Centauri et Pisces et te, Capricorne, rigentem."}, {"st": "2.563", "t": "maxima turba petit Libram, Capricornus et illi"}, {"st": "2.564", "t": "adversus Cancer, Iuvenis quod utrimque quadratum est, 555"}, {"st": "2.565", "t": "quaeque in Lanigeri numerantur signa trigonum."}, {"st": "2.566", "t": "Scorpios in totidem fecundus creditur hostes;"}, {"st": "2.567", "t": "aequoreum iuvenem, Geminos, Taurum atque Leonem,"}, {"st": "2.568", "t": "Erigonen Libramque fugit metuendus et ipse,"}, {"st": "2.569", "t": "quique Sagittari veniunt de sidere partus. 560"}, {"st": "2.570", "t": "hos Geminis nati Libraque et Virgine et Urna"}, {"st": "2.571", "t": "depressisse volent. naturae lege iubente"}, {"st": "2.572", "t": "haec eadem, Capricorne, tuis inimica feruntur."}, {"st": "2.573", "t": "at quos aeternis perfundit Aquarius undis,"}, {"st": "2.574", "t": "in pugnam Nemeaeus agit totumque trigonum, 565"}, {"st": "2.575", "t": "turba sub unius fugiens virtute ferarum."}, {"st": "2.576", "t": "Piscibus exortos vicinus Aquarius urget"}, {"st": "2.577", "t": "et gemini fratres et quos dat Virginis astrum"}, {"st": "2.578", "t": "quique Sagittari descendunt sidera nati."}, {"st": "2.579", "t": "Per tot signorum species contraria surgent 579"}, {"st": "2.580", "t": "corpora totque modis totiens inimica creantur."}, {"st": "2.581", "t": "idcirco nihil ex semet natura creavit"}, {"st": "2.582", "t": "foedere amicitiae maius nec rarius umquam;"}, {"st": "2.583", "t": "perque tot aetates hominum, tot tempora et annos, 589"}, {"st": "2.584", "t": "tot bella et varios etiam sub pace labores,"}, {"st": "2.585", "t": "cum Fortuna fidem quaerat, vix invenit usquam."}, {"st": "2.586", "t": "unus erat Pylades, unus qui mallet Orestes 583"}, {"st": "2.587", "t": "ipse mori; lis una fuit per saecula mortis,"}, {"st": "2.588", "t": "alter quod raperet fatum, non cederet alter."}, {"st": "2.589", "t": "[et duo, qui potuere sequi: vix noxia poenis,"}, {"st": "2.590", "t": "optavitque reum sponsor non posse reverti,"}, {"st": "2.591", "t": "sponsoremque reus timuit, ne solveret ipsum]"}, {"st": "2.592", "t": "at quanta est scelerum moles per saecula cuncta, 592"}, {"st": "2.593", "t": "quamque onus invidiae non excusabile terris!"}, {"st": "2.594", "t": "venales ad fata patres matrumque sepulcra"}, {"st": "2.595", "t": "&lt;non posuere modum sceleri, sed fraude nefanda 594a"}, {"st": "2.596", "t": "ipse deus Caesar cecidit, qua territus orbi&gt; 594b"}, {"st": "2.597", "t": "imposuit Phoebus noctem terrasque reliquit."}, {"st": "2.598", "t": "quid loquar eversas urbes et prodita templa"}, {"st": "2.599", "t": "et varias pacis clades et mixta venena"}, {"st": "2.600", "t": "insidiasque fori, caedes in moenibus ipsis"}, {"st": "2.601", "t": "et sub amicitiae grassantem nomine turbam?"}, {"st": "2.602", "t": "in populo scelus est et abundant cuncta furoris. 600"}, {"st": "2.603", "t": "et fas atque nefas mixtum, legesque per ipsas"}, {"st": "2.604", "t": "saevit nequities; poenas iam noxia vincit."}, {"st": "2.605", "t": "scilicet, in multis quoniam discordia signis"}, {"st": "2.606", "t": "corpora nascuntur, pax est sublata per orbem,"}, {"st": "2.607", "t": "et fidei rarum foedus paucisque tributum, 605"}, {"st": "2.608", "t": "utque sibi caelum sic tellus dissidet ipsa"}, {"st": "2.609", "t": "atque hominum gentes inimica sorte feruntur."}, {"st": "2.610", "t": "Si tamen et cognata cupis dinoscere signa,"}, {"st": "2.611", "t": "quae iungant animos et amica sorte ferantur,"}, {"st": "2.612", "t": "Lanigeri partus cum toto iunge trigono. 610"}, {"st": "2.613", "t": "simplicior tamen est Aries, meliusque Leone"}, {"st": "2.614", "t": "prosequitur genitos et te, Centaure, creatos"}, {"st": "2.615", "t": "quam colitur. namque est natura mitius astrum"}, {"st": "2.616", "t": "expositumque suae noxae, nec fraudibus ullis,"}, {"st": "2.617", "t": "nec minus ingenio molli quam corpore constans: 615"}, {"st": "2.618", "t": "illis est feritas signis praedaeque cupido,"}, {"st": "2.619", "t": "venalisque animus non umquam excedere cogit"}, {"st": "2.620", "t": "commoditate fidem, nec longa est gratia facti;"}, {"st": "2.621", "t": "plus tamen in duplici numerandum est roboris esse, 622"}, {"st": "2.622", "t": "cui commixtus homo est, quam te, Nemeaee, sub uno."}, {"st": "2.623", "t": "at, cum Lanigeri partus sub utroque &lt;laborant 619"}, {"st": "2.624", "t": "vique urgente dolent amborum astuque,&gt; trigono 619a"}, {"st": "2.625", "t": "non parcit; sed rara gerit pro tempore bella,"}, {"st": "2.626", "t": "quae feritas utriusque magis prorumpere cogit."}, {"st": "2.627", "t": "idcirco et pax est signis et mixta querella. 624"}, {"st": "2.628", "t": "quin etiam Tauri Capricorno iungitur astrum,"}, {"st": "2.629", "t": "nec magis illorum coeunt ad foedera mentes;"}, {"st": "2.630", "t": "Virgineos etiam partus, quicumque creantur"}, {"st": "2.631", "t": "Tauro, complecti cupiunt, sed saepe queruntur."}, {"st": "2.632", "t": "quos Geminique dabunt Chelaeque et Aquarius ortus"}, {"st": "2.633", "t": "unum pectus habent fideique immobile vinclum, 630"}, {"st": "2.634", "t": "magnus et in multos veniet successus amicos. 632"}, {"st": "2.635", "t": "Scorpios et Cancer fraterna in nomina ducunt"}, {"st": "2.636", "t": "ex semet genitos, nec non et Piscibus orti"}, {"st": "2.637", "t": "concordant illis. saepe est et subdolus actus: 635"}, {"st": "2.638", "t": "Scorpios aspergit noxas sub nomine amici;"}, {"st": "2.639", "t": "at, quibus in lucem Pisces venientibus adsunt,"}, {"st": "2.640", "t": "his non una manet semper sententia cordi,"}, {"st": "2.641", "t": "commutant animos interdum et foedera rumpunt"}, {"st": "2.642", "t": "ac repetunt, tectaeque lues sub fronte vagantur. 640"}, {"st": "2.643", "t": "sic erit ex signis odium tibi paxque notanda."}, {"st": "2.644", "t": "Nec satis hoc, tantum solis insistere signis: 643"}, {"st": "2.645", "t": "contemplare locum caeli sedemque vagarum."}, {"st": "2.646", "t": "parte genus variant et vires linea mutat."}, {"st": "2.647", "t": "nam sua quadratis veniunt, sua iura trigonis"}, {"st": "2.648", "t": "et quae per senos decurrit virgula tractus"}, {"st": "2.649", "t": "quaeque secat medium transverso limite caelum;"}, {"st": "2.650", "t": "distat enim surgatne eadem subeatne cadatne. 651"}, {"st": "2.651", "t": "hinc modo dat mundus vires, modo deterit idem, 649"}, {"st": "2.652", "t": "quaeque illic sumunt iras, huc acta reponunt."}, {"st": "2.653", "t": "crebrius adversis odium est, cognata quadratis 652"}, {"st": "2.654", "t": "corpora censentur signis et amica trigonis."}, {"st": "2.655", "t": "nec ratio obscura est; nam quartum quodque locavit"}, {"st": "2.656", "t": "eiusdem generis signum natura per orbem. 655"}, {"st": "2.657", "t": "quattuor aequali caelum discrimine signant"}, {"st": "2.658", "t": "in quibus articulos anni deus ipse creavit,"}, {"st": "2.659", "t": "ver Aries, Cererem Cancer Bacchumque ministrans"}, {"st": "2.660", "t": "Libra, caper brumam genitusque ad frigora piscis."}, {"st": "2.661", "t": "nec non et duplici quae sunt conexa figura 660"}, {"st": "2.662", "t": "quartum quemque locum retinent; duo cernere Pisces"}, {"st": "2.663", "t": "et geminos iuvenes duplicemque in Virgine formam"}, {"st": "2.664", "t": "et duo Centauri licet uno corpora textu."}, {"st": "2.665", "t": "sic et simplicibus signis stat forma quadrata;"}, {"st": "2.666", "t": "nam neque Taurus habet comitem, nec iungitur ulli 665"}, {"st": "2.667", "t": "horrendus Leo, nec metuit sine compare quemquam"}, {"st": "2.668", "t": "Scorpios, atque uno censetur Aquarius astro."}, {"st": "2.669", "t": "sic quaecumque manent quadrato condita templo"}, {"st": "2.670", "t": "signa parem referunt numeris aut tempore sortem"}, {"st": "2.671", "t": "ac veluti cognata manent sub foedere tali. 670"}, {"st": "2.672", "t": "idcirco affines signant gradibusque propinquis"}, {"st": "2.673", "t": "accedunt unaque tenent sub imagine natos,"}, {"st": "2.674", "t": "quotquot cardinibus, &lt;prona vertigine mundi 683"}, {"st": "2.675", "t": "naturae vires&gt; propriae variante, moventur; 683a"}, {"st": "2.676", "t": "quae, quamquam in partes divisi quattuor orbis"}, {"st": "2.677", "t": "sidera quadrata efficiunt, non lege quadrati"}, {"st": "2.678", "t": "censentur: minor est numeri quam cardinis usus."}, {"st": "2.679", "t": "longior in spatium porrecta est linea maius 673"}, {"st": "2.680", "t": "quae tribus emensis signis facit astra trigona."}, {"st": "2.681", "t": "haec ad amicitias imitantis iura gradumque"}, {"st": "2.682", "t": "sanguinis atque animis haerentia foedera ducunt,"}, {"st": "2.683", "t": "utque ipsa ex longo coeunt summota recessu,"}, {"st": "2.684", "t": "sic nos coniungunt maioribus intervallis."}, {"st": "2.685", "t": "haec meliora putant, mentes quae iungere possunt,"}, {"st": "2.686", "t": "quam quae non numquam foedus sub sanguine fallunt. 680"}, {"st": "2.687", "t": "proxima vicinis subscribunt, tertia quaeque"}, {"st": "2.688", "t": "hospitibus. sic astrorum servabitur ordo."}, {"st": "2.689", "t": "adde suas partes signis, sua partibus astra; 687"}, {"st": "2.690", "t": "nam nihil in totum servit sibi: mixta feruntur,"}, {"st": "2.691", "t": "ipsis dant in se partes capiuntque vicissim."}, {"st": "2.692", "t": "quae mihi mox certo digesta sub ordine surgent. 690"}, {"st": "2.693", "t": "omnibus ex istis ratio est repetenda per artem,"}, {"st": "2.694", "t": "pacata infestis signa ut discernere possis."}, {"st": "2.695", "t": "Perspice nunc tenuem visu rem, pondere magnam"}, {"st": "2.696", "t": "et tantum Graio signari nomine passam,"}, {"st": "2.697", "t": "dodecatemoria, in titulo signantia causas. 695"}, {"st": "2.698", "t": "nam, cum tricenas per partes sidera constent,"}, {"st": "2.699", "t": "rursus bis senis numerus diducitur omnis;"}, {"st": "2.700", "t": "ipsa igitur ratio binas in partibus esse"}, {"st": "2.701", "t": "dimidiasque docet partes. his finibus ecce"}, {"st": "2.702", "t": "dodecatemorium constans, bis senaque tanta 700"}, {"st": "2.703", "t": "omnibus in signis; quae mundi conditor ille"}, {"st": "2.704", "t": "attribuit totidem numero fulgentibus astris,"}, {"st": "2.705", "t": "ut sociata forent alterna sidera sorte,"}, {"st": "2.706", "t": "et similis sibi mundus, et omnia in omnibus astra,"}, {"st": "2.707", "t": "quorum mixturis regeret concordia corpus 705"}, {"st": "2.708", "t": "et tutela foret communi mutua causa."}, {"st": "2.709", "t": "in terris geniti tali sub lege creantur; 642"}, {"st": "2.710", "t": "idcirco, quamquam signis nascantur eisdem, 707"}, {"st": "2.711", "t": "diversos referunt mores inimicaque vota;"}, {"st": "2.712", "t": "et saepe in peius derrat natura, maremque"}, {"st": "2.713", "t": "femina subsequitur: miscentur sidere partus, 710"}, {"st": "2.714", "t": "singula divisis variant quod partibus astra,"}, {"st": "2.715", "t": "dodecatemoriis proprias mutantia vires."}, {"st": "2.716", "t": "Nunc, quod sit cuiusque, canam, quove ordine constent,"}, {"st": "2.717", "t": "ne vagus ignotis signorum partibus erres."}, {"st": "2.718", "t": "ipsa suo retinent primas in corpore partes 715"}, {"st": "2.719", "t": "sidera, vicinae subeuntibus attribuuntur,"}, {"st": "2.720", "t": "cetera pro numero ducunt ex ordine partes,"}, {"st": "2.721", "t": "ultima et extremis ratio conceditur astris."}, {"st": "2.722", "t": "singula sic retinent binas in sidere quoque"}, {"st": "2.723", "t": "dimidiasque eius partes, et summa repletur 720"}, {"st": "2.724", "t": "sortibus exactis triginta sidere in omni."}, {"st": "2.725", "t": "Nec genus est unum, ratio nec prodita simplex,"}, {"st": "2.726", "t": "pluribus inque modis verum natura locavit"}, {"st": "2.727", "t": "diduxitque vias voluitque per omnia quaeri."}, {"st": "2.728", "t": "haec quoque comperta est ratio sub nomine eodem. 725"}, {"st": "2.729", "t": "quacumque in parti nascentum tempore Luna"}, {"st": "2.730", "t": "constiterit, numeris hanc ter dispone quaternis,"}, {"st": "2.731", "t": "sublimi totidem quia fulgent sidera mundo."}, {"st": "2.732", "t": "inde suas illi signo, quo Luna refulsit,"}, {"st": "2.733", "t": "quaeque hinc defuerant partes numerare memento. 730"}, {"st": "2.734", "t": "proxima tricenas pariterque sequentia ducunt."}, {"st": "2.735", "t": "[hic ubi deficiet numerus, tunc summa relicta"}, {"st": "2.736", "t": "in binas sortes adiecta parte locetur"}, {"st": "2.737", "t": "dimidia, reliquis tribuantur ut ordine signis]"}, {"st": "2.738", "t": "in quo destituent, eius tum Luna tenebit 735"}, {"st": "2.739", "t": "dodecatemorium signi; post cetera ducet"}, {"st": "2.740", "t": "ordine quodque suo, sicut stant astra locata."}, {"st": "2.741", "t": "Haec quoque te ratio ne fallat, percipe paucis"}, {"st": "2.742", "t": "(maior in effectu minor est) de partibus ipsis"}, {"st": "2.743", "t": "dodecatemorii quota sit quod dicitur esse 740"}, {"st": "2.744", "t": "dodecatemorium. namque id per quinque notatur"}, {"st": "2.745", "t": "partes; nam totidem praefulgent sidera caelo"}, {"st": "2.746", "t": "quae vaga dicuntur, ducunt et singula sortes"}, {"st": "2.747", "t": "dimidias, viresque in eis et iura capessunt."}, {"st": "2.748", "t": "in quo quaeque igitur stellae quandoque locatae 745"}, {"st": "2.749", "t": "dodecatemorio fuerint spectare decebit;"}, {"st": "2.750", "t": "cuius enim stella in fines in sidere quoque"}, {"st": "2.751", "t": "inciderit, dabit effectus in viribus eius."}, {"st": "2.752", "t": "undique miscenda est ratio per quam omnia constant."}, {"st": "2.753", "t": "verum haec posterius proprio cuncta ordine reddam; 750"}, {"st": "2.754", "t": "nunc satis est docuisse suos ignota per usus,"}, {"st": "2.755", "t": "ut, cum perceptis steterit fiducia membris,"}, {"st": "2.756", "t": "sic totum corpus facili ratione notetur"}, {"st": "2.757", "t": "et bene de summa veniat post singula carmen."}, {"st": "2.758", "t": "ut rudibus pueris monstratur littera primum 755"}, {"st": "2.759", "t": "per faciem nomenque suum, tum ponitur usus,"}, {"st": "2.760", "t": "tum coniuncta suis formatur syllaba nodis,"}, {"st": "2.761", "t": "hinc verbi structura venit per membra legendi,"}, {"st": "2.762", "t": "tunc rerum vires atque artis traditur usus"}, {"st": "2.763", "t": "perque pedes proprios nascentia carmina surgunt, 760"}, {"st": "2.764", "t": "singulaque in summam prodest didicisse priora"}, {"st": "2.765", "t": "(quae nisi constiterint primis fundata elementis,"}, {"st": "2.766", "t": "effluat in vanum rerum praeposterus ordo 764"}, {"st": "2.767", "t": "versaque quae propere dederint praecepta magistri), 763"}, {"st": "2.768", "t": "sic mihi per totum volitanti carmine mundum 765"}, {"st": "2.769", "t": "erutaque abstrusa penitus caligine fata,"}, {"st": "2.770", "t": "Pieridum numeris etiam modulata, canenti"}, {"st": "2.771", "t": "quoque deus regnat revocanti numen in artem,"}, {"st": "2.772", "t": "per partes ducenda fides et singula rerum"}, {"st": "2.773", "t": "sunt gradibus tradenda suis, ut, cum omnia certa 770"}, {"st": "2.774", "t": "notitia steterint, proprios revocentur ad usus."}, {"st": "2.775", "t": "ac, velut, in nudis cum surgunt montibus urbes,"}, {"st": "2.776", "t": "conditor et vacuos muris circumdare colles"}, {"st": "2.777", "t": "destinat, ante manus quam temptet scindere fossas,"}, {"st": "2.778", "t": "fervit opus (ruit ecce nemus, saltusque vetusti 775"}, {"st": "2.779", "t": "procumbunt solemque novum, nova sidera cernunt,"}, {"st": "2.780", "t": "pellitur omne loco volucrum genus atque ferarum,"}, {"st": "2.781", "t": "antiquasque domos et nota cubilia linquunt,"}, {"st": "2.782", "t": "ast alii silicem in muros et marmora templis"}, {"st": "2.783", "t": "rimantur, ferrique rigor per pignora nota 780"}, {"st": "2.784", "t": "quaeritur, hinc artes, hinc omnis convenit usus),"}, {"st": "2.785", "t": "tum demum consurgit opus, cum cuncta supersunt,"}, {"st": "2.786", "t": "ne medios rumpat cursus praepostera cura,"}, {"st": "2.787", "t": "sic mihi conanti tantae succedere moli"}, {"st": "2.788", "t": "materies primum rerum, ratione remota, 785"}, {"st": "2.789", "t": "tradenda est, ratio sit ne post irrita neve"}, {"st": "2.790", "t": "argumenta novis stupeant nascentia rebus."}, {"st": "2.791", "t": "Ergo age noscendis animum compone sagacem"}, {"st": "2.792", "t": "cardinibus, qui per mundum sunt quattuor omnes"}, {"st": "2.793", "t": "dispositi semper mutantque volantia signa: 790"}, {"st": "2.794", "t": "unus ab exortu caeli nascentis in orbem,"}, {"st": "2.795", "t": "qua primum terras aequali limite cernit,"}, {"st": "2.796", "t": "alter ab adversa respondens aetheris ora,"}, {"st": "2.797", "t": "unde fugit mundus praecepsque in Tartara tendit;"}, {"st": "2.798", "t": "tertius excelsi signat fastigia caeli, 795"}, {"st": "2.799", "t": "quo defessus equis Phoebus subsistit anhelis"}, {"st": "2.800", "t": "reclinatque diem mediasque examinat umbras;"}, {"st": "2.801", "t": "ima tenet quartus fundato nobilis orbe,"}, {"st": "2.802", "t": "in quo principium est reditus finisque cadendi"}, {"st": "2.803", "t": "sideribus, pariterque occasus cernit et ortus. 800"}, {"st": "2.804", "t": "haec loca praecipuas vires summosque per artem"}, {"st": "2.805", "t": "fatorum effectus referunt, quod totus in illis"}, {"st": "2.806", "t": "nititur aeternis veluti compagibus orbis;"}, {"st": "2.807", "t": "quae nisi perpetuis alterna sorte volantem"}, {"st": "2.808", "t": "cursibus excipiant nectantque in vincula, bina 805"}, {"st": "2.809", "t": "per latera atque imum templi summumque cacumen,"}, {"st": "2.810", "t": "dissociata fluat resoluto machina mundo."}, {"st": "2.811", "t": "Sed diversa tamen vis est in cardine quoque,"}, {"st": "2.812", "t": "et pro sorte loci variant atque ordine distant."}, {"st": "2.813", "t": "primus erit, summi qui regnat culmine caeli 810"}, {"st": "2.814", "t": "et medium tenui partitur limite mundum;"}, {"st": "2.815", "t": "quem capit excelsa sublimem Gloria sede"}, {"st": "2.816", "t": "(scilicet haec tutela decet fastigia summa),"}, {"st": "2.817", "t": "quidquid ut emineat sibi vindicet et decus omne"}, {"st": "2.818", "t": "asserat et varios tribuendo regnet honores. 815"}, {"st": "2.819", "t": "hinc favor et species atque omnis gratia vulgi,"}, {"st": "2.820", "t": "reddere iura foro, componere legibus orbem"}, {"st": "2.821", "t": "foederibusque suis externas iungere gentes"}, {"st": "2.822", "t": "et pro sorte sua cuiusque extollere nomen."}, {"st": "2.823", "t": "proximus, est ima quamquam statione locatus, 820"}, {"st": "2.824", "t": "sustinet aeternis nixum radicibus orbem,"}, {"st": "2.825", "t": "effectu minor in specie sed maior in usu."}, {"st": "2.826", "t": "fundamenta tenet rerum censusque gubernat,"}, {"st": "2.827", "t": "quam rata sint fossis, scrutatur, vota metallis"}, {"st": "2.828", "t": "atque ex occulto quantum contingere possit. 825"}, {"st": "2.829", "t": "tertius, aequali terris in parte nitentem"}, {"st": "2.830", "t": "qui tenet exortum, qua primum sidera surgunt,"}, {"st": "2.831", "t": "unde dies redit et tempus describit in horas,"}, {"st": "2.832", "t": "hinc inter Graias horoscopos editur urbes,"}, {"st": "2.833", "t": "nec capit externum, proprio quia nomine gaudet. 830"}, {"st": "2.834", "t": "hunc penes arbitrium vitae est, hic regula morum,"}, {"st": "2.835", "t": "fortunamque dabit rebus, ducetque per artes,"}, {"st": "2.836", "t": "qualiaque excipiant nascentis tempora prima,"}, {"st": "2.837", "t": "quos capiant cultus, quali sint sede creati,"}, {"st": "2.838", "t": "utcumque admixtis subscribent viribus astra. 835"}, {"st": "2.839", "t": "ultimus, emenso qui condit sidera mundo"}, {"st": "2.840", "t": "occasumque tenens summersum despicit orbem,"}, {"st": "2.841", "t": "pertinet ad rerum summas finemque laborum,"}, {"st": "2.842", "t": "coniugia atque epulas extremaque tempora vitae"}, {"st": "2.843", "t": "otiaque et coetus hominum cultusque deorum. 840"}, {"st": "2.844", "t": "Nec contentus eris percepto cardine quoque:"}, {"st": "2.845", "t": "intervalla etiam memori sunt mente notanda"}, {"st": "2.846", "t": "per maius dimensa suas reddentia vires."}, {"st": "2.847", "t": "quidquid ab exortu summum curvatur in orbem,"}, {"st": "2.848", "t": "aetatem primam nascentisque asserit annos. 845"}, {"st": "2.849", "t": "quod summo premitur devexum culmine mundi"}, {"st": "2.850", "t": "donec ad occasus veniat, puerilibus annis"}, {"st": "2.851", "t": "succedit teneramque regit sub sede iuventam."}, {"st": "2.852", "t": "quae pars occasus aufert imumque sub orbem"}, {"st": "2.853", "t": "descendit, regit haec maturae tempora vitae 850"}, {"st": "2.854", "t": "perpetua serie varioque exercita cursu."}, {"st": "2.855", "t": "at, qua perficitur cursus redeunte sub ortum,"}, {"st": "2.856", "t": "tarda supinatum lassatis viribus arcum"}, {"st": "2.857", "t": "ascendens, seros demum complectitur annos"}, {"st": "2.858", "t": "labentemque diem vitae tremulamque senectam. 855"}, {"st": "2.859", "t": "Omne quidem signum sub qualicumque figura"}, {"st": "2.860", "t": "partibus inficitur mundi; locus imperat astris"}, {"st": "2.861", "t": "et dotes noxamque facit; vertuntur in orbem"}, {"st": "2.862", "t": "singula et accipiunt vires caeloque remittunt."}, {"st": "2.863", "t": "vincit enim natura loci legesque ministrat 860"}, {"st": "2.864", "t": "finibus in propriis et praetereuntia cogit"}, {"st": "2.865", "t": "esse sui moris, vario nunc ditia honore,"}, {"st": "2.866", "t": "nunc sterilis poenam referentia sidera sedis."}, {"st": "2.867", "t": "quae super exortum est a summo tertia caelo,"}, {"st": "2.868", "t": "infelix regio rebusque inimica futuris 865"}, {"st": "2.869", "t": "et vitio fecunda nimis; nec sola, sed illi"}, {"st": "2.870", "t": "par erit, adverso quae fulget sidere sedes"}, {"st": "2.871", "t": "iuncta sub occasu. neu praestet, cardine mundi"}, {"st": "2.872", "t": "utraque praetenta fertur deiecta ruina."}, {"st": "2.873", "t": "porta laboris erit: scandendum est atque cadendum. 870"}, {"st": "2.874", "t": "nec melior super occasus contraque sub ortu"}, {"st": "2.875", "t": "sors agitur mundi: praeceps haec, illa supina"}, {"st": "2.876", "t": "pendens aut metuit vicino cardine finem"}, {"st": "2.877", "t": "aut fraudata cadet. merito Typhonis habentur"}, {"st": "2.878", "t": "horrendae sedes, quem Tellus saeva profudit, 875"}, {"st": "2.879", "t": "cum bellum caelo peperit nec matre minores"}, {"st": "2.880", "t": "exstiterunt partus. sed fulmine rursus in alvum"}, {"st": "2.881", "t": "compulsi, montesque super rediere cadentes,"}, {"st": "2.882", "t": "cessit et in tumulum belli vitaeque Typhoeus."}, {"st": "2.883", "t": "ipsa tremit mater flagrantem monte sub Aetna. 880"}, {"st": "2.884", "t": "at, quae fulgentis sequitur fastigia caeli"}, {"st": "2.885", "t": "proxima, neve ipsi cedat, cui iungitur, astro"}, {"st": "2.886", "t": "spe melior, palmamque petens victrixque priorum"}, {"st": "2.887", "t": "altius insurgit: summae comes addita finis,"}, {"st": "2.888", "t": "in peiusque manent cursus nec vota supersunt. 885"}, {"st": "2.889", "t": "quocirca minime mirum, si proxima summo"}, {"st": "2.890", "t": "atque eadem integrior Fortunae sorte dicatur"}, {"st": "2.891", "t": "cui titulus Felix. censum sic proxima Graiae"}, {"st": "2.892", "t": "nostra subit linguae vertitque a nomine nomen."}, {"st": "2.893", "t": "Iuppiter hac habitat: venerandam crede regenti. 890"}, {"st": "2.894", "t": "huic in perversum similis deiecta sub orbe"}, {"st": "2.895", "t": "imaque summersi contingens culmina mundi,"}, {"st": "2.896", "t": "adversa quae parte nitet, defessa peracta"}, {"st": "2.897", "t": "militia rursusque novo devota labori"}, {"st": "2.898", "t": "cardinis et subitura iugum sortemque potentem 895"}, {"st": "2.899", "t": "nondum sentit onus mundi, iam sperat honorem."}, {"st": "2.900", "t": "Daemonien memorant Grai, Romana per ora"}, {"st": "2.901", "t": "quaeritur inversus titulus. sub corde sagaci"}, {"st": "2.902", "t": "conde locum numenque loci nomenque potentis,"}, {"st": "2.903", "t": "quae tibi posterius magnos revocentur ad usus. 900"}, {"st": "2.904", "t": "hic momenta manent nostrae plerumque salutis"}, {"st": "2.905", "t": "bellaque morborum caecis pugnantia telis,"}, {"st": "2.906", "t": "viribus ambiguam geminis casusque deique"}, {"st": "2.907", "t": "nunc huc nunc illuc sortem mutantis utraque."}, {"st": "2.908", "t": "sed medium post astra diem curvataque primum 905"}, {"st": "2.909", "t": "culmina nutantis summo de vertice mundi"}, {"st": "2.910", "t": "aethra Phoebus alit; sub quo quae corpora nostra"}, {"st": "2.911", "t": "concipiunt vitia et fortunam, ex viribus eius"}, {"st": "2.912", "t": "decernunt. Deus ille locus sub nomine Graio"}, {"st": "2.913", "t": "dicitur. huic adversa nitens, quae prima resurgit 910"}, {"st": "2.914", "t": "sedibus ex imis iterumque reducit Olympum,"}, {"st": "2.915", "t": "pars mundi fratrumque vices mortesque gubernat;"}, {"st": "2.916", "t": "et dominam agnoscit Phoeben, fraterna videntem"}, {"st": "2.917", "t": "regna per adversas caeli fulgentia partes"}, {"st": "2.918", "t": "fataque damnosis imitantem finibus oris. 915"}, {"st": "2.919", "t": "huic parti Dea nomen erit Romana per ora,"}, {"st": "2.920", "t": "Graecia voce sua titulum designat eundem."}, {"st": "2.921", "t": "arce sed in caeli, qua summa acclivia finem"}, {"st": "2.922", "t": "inveniunt, qua principium declivia sumunt,"}, {"st": "2.923", "t": "culminaque insurgunt occasus inter et ortus 920"}, {"st": "2.924", "t": "suspenduntque suo libratum examine mundum,"}, {"st": "2.925", "t": "asserit hanc Cytherea sibi per sidera sedem"}, {"st": "2.926", "t": "et velut in facie mundi sua collocat ora,"}, {"st": "2.927", "t": "per quae humana regit. propria est haec reddita parti"}, {"st": "2.928", "t": "vis, ut conubia et thalamos taedasque gubernet: 925"}, {"st": "2.929", "t": "haec tutela decet Venerem, sua tela movere."}, {"st": "2.930", "t": "nomen erit Fortuna loco, quod percipe mente,"}, {"st": "2.931", "t": "ut brevia in longo compendia carmine praestem."}, {"st": "2.932", "t": "at, qua subsidit converso cardine mundus"}, {"st": "2.933", "t": "fundamenta tenens, aversum et suspicit orbem 930"}, {"st": "2.934", "t": "ac media sub nocte iacet, Saturnus in illa"}, {"st": "2.935", "t": "parte suas agitat vires, deiectus et ipse"}, {"st": "2.936", "t": "imperio quondam mundi solioque deorum,"}, {"st": "2.937", "t": "et pater in patrios exercet numina casus"}, {"st": "2.938", "t": "fortunamque senum. 935a"}, {"st": "2.939", "t": "titulus, quem Graecia fecit, 937b"}, {"st": "2.940", "t": "Daemonium signat dignas pro nomine vires."}, {"st": "2.941", "t": "nunc age surgentem primo de cardine mundum"}, {"st": "2.942", "t": "respice, qua solitos nascentia signa recursus 940"}, {"st": "2.943", "t": "incipiunt, viridis gelidis et Phoebus ab undis"}, {"st": "2.944", "t": "enatat et fulvo paulatim accenditur igni"}, {"st": "2.945", "t": "asperum iter temptans, 937a"}, {"st": "2.946", "t": "Aries qua ducit Olympum. 945b"}, {"st": "2.947", "t": "haec tua templa ferunt, Maia Cyllenie nate, 943"}, {"st": "2.948", "t": "pro facie signata nota, quod nomen et ipsi"}, {"st": "2.949", "t": "auctores tibi dant. 945a"}, {"st": "2.950", "t": "una est tutela duorum: 935b"}, {"st": "2.951", "t": "[nascentum atque patrum. quae tali condita parte est]"}, {"st": "2.952", "t": "in qua fortunam natorum condidit omnem 946"}, {"st": "2.953", "t": "natura, ex illa suspendit vota parentum."}, {"st": "2.954", "t": "unus in occasu locus est super. ille ruentem"}, {"st": "2.955", "t": "praecipitat mundum terris et sidera mergit,"}, {"st": "2.956", "t": "tergaque prospectat Phoebi, qui viderat ora; 950"}, {"st": "2.957", "t": "ne mirere, nigri si Ditis ianua fertur"}, {"st": "2.958", "t": "et finem vitae retinet&lt;que repagula mortis.&gt;"}, {"st": "2.959", "t": "hic etiam ipse dies moritur, tellusque per orbem"}, {"st": "2.960", "t": "surripit et noctis captum sub carcere claudit."}, {"st": "2.961", "t": "nec non et fidei tutelam vindicat ipsi 955"}, {"st": "2.962", "t": "pectoris et pondus. tanta est in sede potestas"}, {"st": "2.963", "t": "quae vocat et condit Phoebum recipitque refertque,"}, {"st": "2.964", "t": "consummatque diem. tali sub sorte notandae"}, {"st": "2.965", "t": "templorum tibi sunt vires: quae pervolat omnis"}, {"st": "2.966", "t": "astrorum series ducitque et commodat illis 960"}, {"st": "2.967", "t": "ipsa suas leges, stellaeque ex ordine certo,"}, {"st": "2.968", "t": "ut natura sinit, lustrant, variasque locorum"}, {"st": "2.969", "t": "efficiunt vires, utcumque aliena capessunt"}, {"st": "2.970", "t": "regna et in externis subsidunt hospita castris."}, {"st": "2.971", "t": "haec mihi sub certa stellarum parte canentur; 965"}, {"st": "2.972", "t": "nunc satis est caeli partes titulosque notasse"}, {"st": "2.973", "t": "effectusque loci per se cuiusque deosque."}, {"st": "2.974", "t": "[cui parti nomen posuit, qui condidit artem,"}, {"st": "2.975", "t": "octotropos; per quod stellae diversa volantes"}, {"st": "2.976", "t": "quos reddant motus, proprio venit ordine rerum]."}, {"sp": "HDR", "t": "Liber III"}, {"st": "3.1", "t": "In nova surgentem maioraque viribus ausum"}, {"st": "3.2", "t": "nec per inaccessos metuentem vadere saltus"}, {"st": "3.3", "t": "ducite, Pierides. vestros extendere fines"}, {"st": "3.4", "t": "conor et ignotos in carmina ducere census."}, {"st": "3.5", "t": "non ego in excidium caeli nascentia bella, 5"}, {"st": "3.6", "t": "fulminis et flammis partus in matre sepultos,"}, {"st": "3.7", "t": "non coniuratos reges Troiaque cadente"}, {"st": "3.8", "t": "Hectora venalem cineri Priamumque ferentem,"}, {"st": "3.9", "t": "Colchida nec referam vendentem regna parentis"}, {"st": "3.10", "t": "et lacerum fratrem stupro, segetesque virorum 10"}, {"st": "3.11", "t": "taurorumque trucis flammas vigilemque draconem"}, {"st": "3.12", "t": "et reduces annos auroque incendia facta"}, {"st": "3.13", "t": "et male conceptos partus peiusque necatos;"}, {"st": "3.14", "t": "non annosa canam Messenes bella nocentis,"}, {"st": "3.15", "t": "septenosve duces ereptaque fulmine flammis 15"}, {"st": "3.16", "t": "moenia Thebarum et victam quia vicerat urbem,"}, {"st": "3.17", "t": "germanosve patris referam matrisque nepotes,"}, {"st": "3.18", "t": "natorumve epulas conversaque sidera retro"}, {"st": "3.19", "t": "ereptumque diem, nec Persica bella profundo"}, {"st": "3.20", "t": "indicta et magna pontum sub classe latentem 20"}, {"st": "3.21", "t": "immissumque fretum terris, iter aequoris undis;"}, {"st": "3.22", "t": "non regis magni spatio maiore canenda"}, {"st": "3.23", "t": "quam sunt acta loquar. Romanae gentis origo,"}, {"st": "3.24", "t": "quotque duces urbis tot bella atque otia, et omnis"}, {"st": "3.25", "t": "in populi unius leges ut cesserit orbis, 25"}, {"st": "3.26", "t": "differtur. facile est ventis dare vela secundis"}, {"st": "3.27", "t": "fecundumque solum varias agitare per artes"}, {"st": "3.28", "t": "auroque atque ebori decus addere, cum rudis ipsa"}, {"st": "3.29", "t": "materies niteat. speciosis condere rebus"}, {"st": "3.30", "t": "carmina vulgatum est, opus et componere simplex. 30"}, {"st": "3.31", "t": "at mihi per numeros ignotaque nomina rerum"}, {"st": "3.32", "t": "temporaque et varios casus momentaque mundi"}, {"st": "3.33", "t": "signorumque vices partesque in partibus ipsis"}, {"st": "3.34", "t": "luctandum est. quae nosse nimis, quid, dicere quantum est?"}, {"st": "3.35", "t": "carmine quid proprio? pedibus quid iungere certis? 35"}, {"st": "3.36", "t": "huc ades, o quicumque meis advertere coeptis"}, {"st": "3.37", "t": "aurem oculosque potes, veras et percipe voces."}, {"st": "3.38", "t": "impendas animum; nec dulcia carmina quaeras:"}, {"st": "3.39", "t": "ornari res ipsa negat contenta doceri."}, {"st": "3.40", "t": "et, siqua externa referentur nomina lingua, 40"}, {"st": "3.41", "t": "hoc operis, non vatis erit: non omnia flecti"}, {"st": "3.42", "t": "possunt, et propria melius sub voce notantur."}, {"st": "3.43", "t": "Nunc age subtili rem summam perspice cura,"}, {"st": "3.44", "t": "quae tibi praecipuos usus monstrata ministret"}, {"st": "3.45", "t": "et certas det in arte vias ad fata videnda, 45"}, {"st": "3.46", "t": "si bene constiterit vigilanti condita sensu."}, {"st": "3.47", "t": "principium rerum et custos natura latentum"}, {"st": "3.48", "t": "(cum tantas strueret moles per moenia mundi"}, {"st": "3.49", "t": "et circum fusis orbem concluderet astris"}, {"st": "3.50", "t": "undique pendentem in medium, diversaque membra 50"}, {"st": "3.51", "t": "ordinibus certis sociaret corpus in unum,"}, {"st": "3.52", "t": "aeraque et terras flammamque undamque natantem"}, {"st": "3.53", "t": "mutua in alternum praebere alimenta iuberet,"}, {"st": "3.54", "t": "ut tot pugnantis regeret concordia causas"}, {"st": "3.55", "t": "staretque alterno religatus foedere mundus), 55"}, {"st": "3.56", "t": "exceptum a summa nequid ratione maneret"}, {"st": "3.57", "t": "et quod erat mundi mundo regeretur ab ipso,"}, {"st": "3.58", "t": "fata quoque et vitas hominum suspendit ab astris,"}, {"st": "3.59", "t": "quae summas operum partes, quae lucis honorem,"}, {"st": "3.60", "t": "quae famam assererent, quae numquam fessa volarent. 60"}, {"st": "3.61", "t": "quae, quasi, per mediam, mundi praecordia, partem"}, {"st": "3.62", "t": "disposita, obtineant, Phoebum lunamque vagasque"}, {"st": "3.63", "t": "evincunt stellas nec non vincuntur et ipsa,"}, {"st": "3.64", "t": "his regimen natura dedit, propriasque sacravit"}, {"st": "3.65", "t": "unicuique vices sanxitque per omnia summam, 65"}, {"st": "3.66", "t": "undique uti fati ratio traheretur in unum."}, {"st": "3.67", "t": "nam, quodcumque genus rerum, quotcumque labores"}, {"st": "3.68", "t": "quaeque opera atque artes, quicumque per omnia casus"}, {"st": "3.69", "t": "humana in vita poterant contingere, sorte"}, {"st": "3.70", "t": "complexa est, tot et in partes, quot et astra locarat, 70"}, {"st": "3.71", "t": "disposuit, certasque vices, sua munera cuique"}, {"st": "3.72", "t": "attribuit, totumque hominis per sidera censum"}, {"st": "3.73", "t": "ordine sub certo duxit, pars semper ut eidem"}, {"st": "3.74", "t": "confinis parti vicinis staret in astris."}, {"st": "3.75", "t": "horum operum sortes ad singula signa locavit, 75"}, {"st": "3.76", "t": "non ut in aeterna caeli statione manerent"}, {"st": "3.77", "t": "et cunctos hominum pariter traherentur in ortus"}, {"st": "3.78", "t": "ex isdem repetita locis, sed tempore sedes"}, {"st": "3.79", "t": "nascentum acciperent proprias signisque migrarent"}, {"st": "3.80", "t": "atque alias &lt;alii&gt; sors quaeque accederet astro, 80"}, {"st": "3.81", "t": "ut caperet genitura novam per sidera formam"}, {"st": "3.82", "t": "nec tamen incerto confunderet omnia motu."}, {"st": "3.83", "t": "sed, cum pars operum quae prima condita sorte est"}, {"st": "3.84", "t": "accepit propriam nascentis tempore sedem,"}, {"st": "3.85", "t": "cetera succedunt signisque sequentibus haerent. 85"}, {"st": "3.86", "t": "ordo ducem sequitur donec venit orbis in orbem."}, {"st": "3.87", "t": "has autem facies rerum per signa locatas,"}, {"st": "3.88", "t": "in quibus omnis erit fortunae condita summa,"}, {"st": "3.89", "t": "ut cursu stellae septem laeduntve iuvantve"}, {"st": "3.90", "t": "cardinibusve movet divina potentia mundum, 90"}, {"st": "3.91", "t": "sic felix aut triste venit per singula fatum,"}, {"st": "3.92", "t": "talis et illius sors est speranda negoti."}, {"st": "3.93", "t": "haec mihi sollemni sunt ordine cuncta canenda"}, {"st": "3.94", "t": "et titulis signanda suis rerumque figuris,"}, {"st": "3.95", "t": "ut pateat positura operum nomenque genusque. 95"}, {"st": "3.96", "t": "Fortunae sors prima data est. hoc illa per artem"}, {"st": "3.97", "t": "censetur titulo, quia proxima continet in se"}, {"st": "3.98", "t": "fundamenta domus domuique haerentia cuncta:"}, {"st": "3.99", "t": "qui modus in servis, qui sit concessus in arvis"}, {"st": "3.100", "t": "quamque datum magnas operum componere moles, 100"}, {"st": "3.101", "t": "ut vaga fulgentis concordant sidera caeli."}, {"st": "3.102", "t": "post hinc militiae locus est, qua quidquid in armis"}, {"st": "3.103", "t": "quodque peregrinas inter versantibus urbes"}, {"st": "3.104", "t": "accidere assuevit titulo comprenditur uno."}, {"st": "3.105", "t": "tertia ad urbanos statio est numeranda labores 105"}, {"st": "3.106", "t": "(hoc quoque militiae genus est, civilibus actis"}, {"st": "3.107", "t": "compositum) fideique tenet parentia vincla;"}, {"st": "3.108", "t": "format amicitias et saepe cadentia frustra"}, {"st": "3.109", "t": "officia, et cultus contingant praemia quanta"}, {"st": "3.110", "t": "edocet, appositis cum mundus consonat astris. 110"}, {"st": "3.111", "t": "iudiciorum opus in quarto natura locavit"}, {"st": "3.112", "t": "fortunamque fori: fundentem verba patronum"}, {"st": "3.113", "t": "pendentemque reum lingua labrisque loquentis"}, {"st": "3.114", "t": "impositum, et populo nudantem condita iura"}, {"st": "3.115", "t": "atque expensa sua solventem iurgia fronte, 115"}, {"st": "3.116", "t": "cum iudex veri nihil amplius advocat ipso."}, {"st": "3.117", "t": "quidquid propositas inter facundia leges"}, {"st": "3.118", "t": "efficit, hoc totum partem concessit in unam"}, {"st": "3.119", "t": "atque, utcumque regunt dominantia sidera, paret."}, {"st": "3.120", "t": "quintus coniugio gradus est per signa dicatus 120"}, {"st": "3.121", "t": "et socios tenet, et committens hospita iura"}, {"st": "3.122", "t": "iungitur et similis coniungens foedus amicos."}, {"st": "3.123", "t": "in sexta dives numeratur copia sede"}, {"st": "3.124", "t": "atque adiuncta salus rerum, quarum altera quanti"}, {"st": "3.125", "t": "contingant usus monet, altera quam diuturni, 125"}, {"st": "3.126", "t": "sidera ut inclinant vires et templa gubernant."}, {"st": "3.127", "t": "septima censetur saevis horrenda periclis,"}, {"st": "3.128", "t": "si male subscribunt stellae per signa locatae."}, {"st": "3.129", "t": "nobilitas tenet octavam, qua constat honoris"}, {"st": "3.130", "t": "condicio et famae modus et genus et specioso 130"}, {"st": "3.131", "t": "gratia praetexto. nonus locus occupat omnem"}, {"st": "3.132", "t": "natorum sortem dubiam patriosque timores"}, {"st": "3.133", "t": "omniaque infantum mixta nutricia turba."}, {"st": "3.134", "t": "huic vicinus erit, vitae qui continet actum,"}, {"st": "3.135", "t": "in quo sortimur mores, et qualibus omnis 135"}, {"st": "3.136", "t": "formetur domus exemplis, quamque ordine certo"}, {"st": "3.137", "t": "ad sua compositi discedant munera servi."}, {"st": "3.138", "t": "praecipua undecima pars est in sorte locata,"}, {"st": "3.139", "t": "quae summam nostri semper viresque gubernat,"}, {"st": "3.140", "t": "quaque valetudo constat, nunc libera morbis, 140"}, {"st": "3.141", "t": "nunc oppressa, movent ut mundum sidera cumque."}, {"st": "3.142", "t": "non alia est sedes, tempusve genusve medendi"}, {"st": "3.143", "t": "quae sibi deposcat vel cuius tempore praestet"}, {"st": "3.144", "t": "auxilium et vitae sucos miscere salubris."}, {"st": "3.145", "t": "ultimus et totam concludens ordine summam 145"}, {"st": "3.146", "t": "rebus apiscendis labor est, qui continet omnis"}, {"st": "3.147", "t": "votorum effectus, et, quae sibi quisque suisque"}, {"st": "3.148", "t": "proponit studia atque artes, haec irrita ne sint."}, {"st": "3.149", "t": "seu ferat officium nutus blanditus in omnis,"}, {"st": "3.150", "t": "aspera sive foro per litem iurgia temptet, 150"}, {"st": "3.151", "t": "fortunamve petat pelago ventisque sequatur,"}, {"st": "3.152", "t": "seu Cererem plena vincentem credita messe"}, {"st": "3.153", "t": "aut repetat Bacchum per pinguia musta fluentem,"}, {"st": "3.154", "t": "hac in parte dies atque hac momenta dabuntur,"}, {"st": "3.155", "t": "si bene convenient stellae per signa sequentes; 155"}, {"st": "3.156", "t": "quarum ego posterius vires in utrumque valentis"}, {"st": "3.157", "t": "ordine sub serto reddam, cum pandere earum"}, {"st": "3.158", "t": "incipiam effectus. nunc, ne permixta legentem"}, {"st": "3.159", "t": "confundant, nudis satis est insistere membris."}, {"st": "3.160", "t": "Et, quoniam certo digestos orbe labores 160"}, {"st": "3.161", "t": "nominaque in numerum viresque exegimus omnis"}, {"st": "3.162", "t": "(athla vocant Grai, quae cuncta negotia rerum"}, {"st": "3.163", "t": "in genera et partes bis sex divisa coercent),"}, {"st": "3.164", "t": "nunc, quibus accedant signis quandoque, canendum est."}, {"st": "3.165", "t": "perpetuas neque enim sedes eademve per omnis 165"}, {"st": "3.166", "t": "sidera nascentis retinent, sed tempore mutant,"}, {"st": "3.167", "t": "nunc huc nunc illuc signorum mota per orbem,"}, {"st": "3.168", "t": "incolumis tamen ut maneat qui conditus ordo est."}, {"st": "3.169", "t": "ergo age, ne falsa variet genitura figura,"}, {"st": "3.170", "t": "si sua quemque voles revocare ad signa laborem, 170"}, {"st": "3.171", "t": "Fortunae conquire locum per sidera cuncta,"}, {"st": "3.172", "t": "quae primum est aerumnosis pars dicta sub athlis."}, {"st": "3.173", "t": "qui tibi cum fuerit certa ratione repertus,"}, {"st": "3.174", "t": "cetera praedicto subeuntibus ordine signis"}, {"st": "3.175", "t": "coniunges, teneant proprias ut singula sedes. 175"}, {"st": "3.176", "t": "et, ne forte vagus Fortunae quaerere sedem"}, {"st": "3.177", "t": "incipias, duplici certam ratione capesse."}, {"st": "3.178", "t": "cum tibi, nascentis percepto tempore, forma"}, {"st": "3.179", "t": "constiterit caeli, stellis ad signa locatis,"}, {"st": "3.180", "t": "transverso Phoebus si cardine celsior ibit 180"}, {"st": "3.181", "t": "qui tenet exortum vel qui demergit in undas,"}, {"st": "3.182", "t": "per tempus licet affirmes natum esse diei."}, {"st": "3.183", "t": "at, si subiectis senis fulgebit in astris"}, {"st": "3.184", "t": "inferior dextra laevaque tenentibus orbem"}, {"st": "3.185", "t": "cardinibus, noctis fuerit per tempora natus. 185"}, {"st": "3.186", "t": "haec tibi cum fuerint certo discrimine nota,"}, {"st": "3.187", "t": "tunc, si forte dies nascentem exceperit alma,"}, {"st": "3.188", "t": "a sole ad lunam numerabis in ordine partes"}, {"st": "3.189", "t": "signorum, ortivo totidem de cardine duces,"}, {"st": "3.190", "t": "quem bene partitis memorant horoscopon astris. 190"}, {"st": "3.191", "t": "in quodcumque igitur numerus pervenerit astrum"}, {"st": "3.192", "t": "hoc da Fortunae. iunges tum cetera signis"}, {"st": "3.193", "t": "athla suis, certo subeuntibus ordine cunctis."}, {"st": "3.194", "t": "at, cum obducta nigris nox orbem texerit alis,"}, {"st": "3.195", "t": "siquis erit qui tum materna excesserit alvo, 195"}, {"st": "3.196", "t": "verte vias, sicut naturae vertitur ordo."}, {"st": "3.197", "t": "consule tum Phoeben imitantem lumina fratris"}, {"st": "3.198", "t": "semper et in proprio regnantem tempore noctis;"}, {"st": "3.199", "t": "quotque ab ea Phoebus partes et signa recedit"}, {"st": "3.200", "t": "tot numerare iubet fulgens horoscopos a se. 200"}, {"st": "3.201", "t": "hunc Fortuna locum teneat subeuntibus athlis,"}, {"st": "3.202", "t": "ordine naturae sicut sunt cuncta locata."}, {"st": "3.203", "t": "Forsitan et quaeras, agili rem corde notandam,"}, {"st": "3.204", "t": "qua ratione queas, natalis tempore, nati"}, {"st": "3.205", "t": "exprimere immerso surgentem horoscopon orbe. 205"}, {"st": "3.206", "t": "quod nisi subtili visum ratione tenetur,"}, {"st": "3.207", "t": "fundamenta ruunt artis nec consonat ordo;"}, {"st": "3.208", "t": "cardinibus quoniam falsis, qui cuncta gubernant,"}, {"st": "3.209", "t": "mentitur faciem mundus nec constat origo"}, {"st": "3.210", "t": "flexaque momento variantur sidera templi. 210"}, {"st": "3.211", "t": "sed, quanta effectu, res est tam plena laboris"}, {"st": "3.212", "t": "cursibus aeternis mundum per signa volantem,"}, {"st": "3.213", "t": "ut totum lustret curvatis arcubus orbem,"}, {"st": "3.214", "t": "exprimere et vultus eius componere certos"}, {"st": "3.215", "t": "ac tantae molis minimum deprendere punctum: 215"}, {"st": "3.216", "t": "quae pars exortum vel quae fastigia mundi"}, {"st": "3.217", "t": "&lt;obtineat summi demersosve aequoris undis&gt; 216a"}, {"st": "3.218", "t": "auferat occasus aut imo sederit orbe."}, {"st": "3.219", "t": "Nec me vulgatae rationis praeterit ordo,"}, {"st": "3.220", "t": "quae binas tribuit signis surgentibus horas"}, {"st": "3.221", "t": "et paribus spatiis aequalia digerit astra, 220"}, {"st": "3.222", "t": "ut parte ex illa, qua Phoebi coeperit orbis,"}, {"st": "3.223", "t": "discedat numerus summamque accommodet astris,"}, {"st": "3.224", "t": "donec perveniat nascentis tempus ad ipsum,"}, {"st": "3.225", "t": "atque, ubi substiterit, signum dicatur oriri."}, {"st": "3.226", "t": "sed iacet obliquo signorum circulus orbe, 225"}, {"st": "3.227", "t": "atque alia inflexis oriuntur sidera membris,"}, {"st": "3.228", "t": "ast illis magis est rectus surgentibus ordo,"}, {"st": "3.229", "t": "ut propius nodis aliquod vel longius astrum est."}, {"st": "3.230", "t": "vix finit luces Cancer, vix bruma reducit,"}, {"st": "3.231", "t": "quam brevis ille iacet, tam longus circulus hic est; 230"}, {"st": "3.232", "t": "Libra Ariesque parem reddunt noctemque diemque."}, {"st": "3.233", "t": "sic media extremis pugnant extremaque summis."}, {"st": "3.234", "t": "nec nocturna minus variant quam tempora lucis,"}, {"st": "3.235", "t": "sed tantum adversis idem stat mensibus ordo."}, {"st": "3.236", "t": "in tam dissimili spatio variisque dierum 235"}, {"st": "3.237", "t": "umbrarumque modis quis credere possit in auras"}, {"st": "3.238", "t": "omnia signa pari mundi sub lege meare?"}, {"st": "3.239", "t": "adde quod incerta est horae mensura neque ullam"}, {"st": "3.240", "t": "altera par sequitur, sed, sicut summa dierum"}, {"st": "3.241", "t": "vertitur, et partes surgunt rursusque recedunt; 240"}, {"st": "3.242", "t": "cum tamen, in quocumque dies deducitur astro,"}, {"st": "3.243", "t": "sex habeat supra terras, sex signa sub illis."}, {"st": "3.244", "t": "quo fit ut in binas non possint omnia nasci,"}, {"st": "3.245", "t": "cum spatium non sit sibi par pugnantibus horis,"}, {"st": "3.246", "t": "si modo bis senae servantur luce sub omni, 245"}, {"st": "3.247", "t": "quem numerum debet ratio sed non capit usus."}, {"st": "3.248", "t": "Nec tibi constabunt aliter vestigia veri,"}, {"st": "3.249", "t": "ni, lucem noctemque paris dimensus in horas,"}, {"st": "3.250", "t": "in quantum vario pateant sub tempore noris,"}, {"st": "3.251", "t": "regulaque exacta primum formetur in hora 250"}, {"st": "3.252", "t": "quae surgens sidensque diem perpendat et umbras."}, {"st": "3.253", "t": "haec erit, in Libra cum lucem vincere noctes"}, {"st": "3.254", "t": "incipiunt vel cum medio concedere vere."}, {"st": "3.255", "t": "tunc etenim solum bis senas tempora in horas"}, {"st": "3.256", "t": "aequa patent, medio quod currit Phoebus Olympo. 255"}, {"st": "3.257", "t": "is cum per gelidas hiemes summotus in austros"}, {"st": "3.258", "t": "fulget in octava Capricorni parte biformis,"}, {"st": "3.259", "t": "tunc angusta dies vernalis fertur in horas"}, {"st": "3.260", "t": "dimidiam atque novem, sed nox oblita diei"}, {"st": "3.261", "t": "bis septem apposita, numerus ne claudicet, hora 260"}, {"st": "3.262", "t": "dimidia. sic in duodenas exit utrimque"}, {"st": "3.263", "t": "et redit in solidum natura condita summa."}, {"st": "3.264", "t": "inde cadunt noctes surguntque in tempora luces,"}, {"st": "3.265", "t": "nunc huc nunc illuc gradibus per sidera certis 268"}, {"st": "3.266", "t": "impulsae, quorum ratio manifesta per artem"}, {"st": "3.267", "t": "collecta est venietque suo per carmina textu,"}, {"st": "3.268", "t": "donec ad ardentis pugnarunt sidera Cancri; 264"}, {"st": "3.269", "t": "atque ibi conversis vicibus mutantur in horas"}, {"st": "3.270", "t": "brumalis, noctemque dies lucemque tenebrae"}, {"st": "3.271", "t": "hibernam referunt, alternaque tempora vincunt."}, {"st": "3.272", "t": "atque haec est illas demum mensura per oras 271"}, {"st": "3.273", "t": "quas rigat aestivis gravidus torrentibus amnis"}, {"st": "3.274", "t": "Nilus et erumpens imitatur sidera mundi"}, {"st": "3.275", "t": "per septem fauces atque ora fugantia pontum."}, {"st": "3.276", "t": "Nunc age, quot stadiis et quanto tempore surgant 275"}, {"st": "3.277", "t": "sidera, quotque cadant, animo cognosce sagaci,"}, {"st": "3.278", "t": "ne magna in brevibus lateant compendia dictis."}, {"st": "3.279", "t": "nobile Lanigeri sidus, quod cuncta sequuntur,"}, {"st": "3.280", "t": "dena quater stadia exoriens duplicataque ducit"}, {"st": "3.281", "t": "cum cadit, atque horam surgens eiusque trientem 280"}, {"st": "3.282", "t": "occupat, occiduus geminat. tum cetera signa"}, {"st": "3.283", "t": "octonis crescunt stadiis orientia in orbem"}, {"st": "3.284", "t": "et totidem amittunt gelidas vergentia in umbras."}, {"st": "3.285", "t": "hora novo crescit per singula signa quadrante"}, {"st": "3.286", "t": "tertiaque e quinta pars parte inducitur eius. 285"}, {"st": "3.287", "t": "haec sunt ad Librae sidus surgentibus astris"}, {"st": "3.288", "t": "incrementa: pari momento damna trahuntur"}, {"st": "3.289", "t": "cum subeunt orbem. rursusque a sidere Librae"}, {"st": "3.290", "t": "ordine mutato paribus per tempora versa"}, {"st": "3.291", "t": "momentis redeunt. nam, per quot creverat astrum 290"}, {"st": "3.292", "t": "Lanigeri stadia aut horas, tot Libra recedit;"}, {"st": "3.293", "t": "occiduusque Aries spatium tempusque cadendi"}, {"st": "3.294", "t": "quod tenet, in tantum Chelae consurgere perstant."}, {"st": "3.295", "t": "excipiunt vicibus se signa sequentia versis."}, {"st": "3.296", "t": "haec ubi constiterint vigilanti condita mente 295"}, {"st": "3.297", "t": "iam facile est tibi, quod quandoque horoscopet astrum,"}, {"st": "3.298", "t": "noscere, cum liceat certis surgentia signa"}, {"st": "3.299", "t": "ducere temporibus propriasque ascribere in horas,"}, {"st": "3.300", "t": "partibus ut ratio signo ducatur ab illo,"}, {"st": "3.301", "t": "in quo Phoebus erit, quarum mihi reddita summa est. 300"}, {"st": "3.302", "t": "Sed neque per terras omnis mensura dierum"}, {"st": "3.303", "t": "umbrarumque eadem est, simili nec tempora summa"}, {"st": "3.304", "t": "mutantur: modus est varius ratione sub una."}, {"st": "3.305", "t": "nam, qua Phrixei ducuntur vellera signi"}, {"st": "3.306", "t": "Chelarumque fides iustaeque examina Librae, 305"}, {"st": "3.307", "t": "omnia consurgunt binas ibi signa per horas,"}, {"st": "3.308", "t": "quod medius recto praeciditur ordine mundus"}, {"st": "3.309", "t": "aequalisque super transversum vertitur axem."}, {"st": "3.310", "t": "illic perpetua iunguntur pace diebus"}, {"st": "3.311", "t": "obscurae noctes; aequo stat foedere tempus; 310"}, {"st": "3.312", "t": "nec manifesta patet falsi fallacia mundi,"}, {"st": "3.313", "t": "sed similis simili toto nox redditur aevo;"}, {"st": "3.314", "t": "omnibus autumnus signis, ver omnibus unum,"}, {"st": "3.315", "t": "una quod aequali lustratur linea Phoebo."}, {"st": "3.316", "t": "nec refert illic quo sol decurrat in astro, 315"}, {"st": "3.317", "t": "litoreumne coquat Cancrum contrane feratur,"}, {"st": "3.318", "t": "[sideribus mediis an quae sint quattuor inter]"}, {"st": "3.319", "t": "quod, quamquam per tris signorum circulus arcus"}, {"st": "3.320", "t": "obliquus iaceat, recto tamen ordine zonae"}, {"st": "3.321", "t": "consurgunt supra caput in terrasque feruntur 320"}, {"st": "3.322", "t": "et paribus spatiis per singula lustra resurgunt,"}, {"st": "3.323", "t": "ac bene diviso mundus latet orbe patetque."}, {"st": "3.324", "t": "at, simul ex illa terrarum parte recedas,"}, {"st": "3.325", "t": "quidquid ad extremos temet provexerit axes"}, {"st": "3.326", "t": "per convexa gradus gressum fastigia terrae, 325"}, {"st": "3.327", "t": "quam tereti natura solo decircinat orbem"}, {"st": "3.328", "t": "in tumidum et mediam mundo suspendit ab omni,++"}, {"st": "3.329", "t": "ergo ubi conscendes orbem scandensque rotundum"}, {"st": "3.330", "t": "degrediere simul, fugiet pars altera terrae,"}, {"st": "3.331", "t": "altera reddetur. sed, quantum inflexeris orbem, 330"}, {"st": "3.332", "t": "tantum inclinabit caeli positura volantis,"}, {"st": "3.333", "t": "et modo quae fuerant surgentia limite recto"}, {"st": "3.334", "t": "sidera curvato ducentur in aethera tractu,"}, {"st": "3.335", "t": "atque erit obliquo signorum balteus orbe"}, {"st": "3.336", "t": "qui transversus erat, statio quando illius una est, 335"}, {"st": "3.337", "t": "nostrae mutantur sedes. ergo ipsa moveri"}, {"st": "3.338", "t": "tempora iam ratio cogit variosque referre"}, {"st": "3.339", "t": "sub tali regione dies, cum sidera flexo"}, {"st": "3.340", "t": "ordine conficiant cursus obliqua malignos,"}, {"st": "3.341", "t": "longius atque aliis aliud propiusve recumbat. 340"}, {"st": "3.342", "t": "pro spatio mora magna datur: quae proxima nobis"}, {"st": "3.343", "t": "consurgunt, longos caeli visuntur in orbes;"}, {"st": "3.344", "t": "ultima quae fulgent, celeris merguntur in umbras."}, {"st": "3.345", "t": "et, quanto ad gelidas propius quis venerit Arctos,"}, {"st": "3.346", "t": "tam magis effugiunt oculos brumalia signa, 345"}, {"st": "3.347", "t": "vixque ortis occasus erit. si longius inde"}, {"st": "3.348", "t": "procedat, totis condentur singula membris"}, {"st": "3.349", "t": "tricenasque trahent conexo tempore noctes"}, {"st": "3.350", "t": "et totidem luces adiment. sic parva dierum"}, {"st": "3.351", "t": "efficitur mora et attritis consumitur horis 350"}, {"st": "3.352", "t": "paulatimque perit, spatio fugientibus astris."}, {"st": "3.353", "t": "pluraque, per partes surrepto tempore, signa"}, {"st": "3.354", "t": "quaerentur medio terrae celata tumore"}, {"st": "3.355", "t": "abducentque simul Phoebum texentque tenebras,"}, {"st": "3.356", "t": "mensibus ereptis donec sit debilis annus. 355"}, {"st": "3.357", "t": "si vero natura sinat sub vertice caeli,"}, {"st": "3.358", "t": "quem gelidus rigidis fulcit compagibus axis,"}, {"st": "3.359", "t": "aeternas super ire nives orbemque rigentem"}, {"st": "3.360", "t": "prona Lycaoniae spectantem membra puellae,"}, {"st": "3.361", "t": "stantis erit caeli species, laterumque meatu 360"}, {"st": "3.362", "t": "turbinis in morem recta vertigine curret."}, {"st": "3.363", "t": "inde tibi obliquo sex tantum signa patebunt"}, {"st": "3.364", "t": "circuitu, nullos umquam fugientia visus"}, {"st": "3.365", "t": "sed teretem acclini mundum comitantia spira."}, {"st": "3.366", "t": "hic erit una dies per senos undique menses 365"}, {"st": "3.367", "t": "dimidiumque trahens contextis lucibus annum,"}, {"st": "3.368", "t": "numquam erit occiduus quod tanto tempore Phoebus,"}, {"st": "3.369", "t": "dum bis terna suis perlustrat cursibus astra,"}, {"st": "3.370", "t": "sed circum volitans recto versabitur orbe."}, {"st": "3.371", "t": "at, simul e medio praeceps descenderit orbe 370"}, {"st": "3.372", "t": "inferiora petens deiecto sidera curru"}, {"st": "3.373", "t": "et dabit in pronum laxas effusus habenas,"}, {"st": "3.374", "t": "per totidem menses iunget nox una tenebras"}, {"st": "3.375", "t": "vertice sub caeli. nam quisquis spectat ab axe,"}, {"st": "3.376", "t": "dimidium e toto mundi videt orbe rotundi, 375"}, {"st": "3.377", "t": "pars latet inferior; neque enim circumvenit illum"}, {"st": "3.378", "t": "recta acies, mediaque tenus distenditur alvo."}, {"st": "3.379", "t": "effugit ergo oculos summo spectantis ab orbe"}, {"st": "3.380", "t": "dum sex summersis vectatur Phoebus in astris,"}, {"st": "3.381", "t": "abducitque simul luces tenebrasque relinquit 380"}, {"st": "3.382", "t": "sideribus, donec totidem, quot mensibus actis"}, {"st": "3.383", "t": "cesserat, inde redit geminasque ascendit ad Arctos."}, {"st": "3.384", "t": "hic locus in binas annum noctesque diesque"}, {"st": "3.385", "t": "per duo partitae dirimit divortia terrae."}, {"st": "3.386", "t": "Et, quoniam quanto varientur tempora motu 385"}, {"st": "3.387", "t": "et quibus e causis dictum est, nunc accipe, signa"}, {"st": "3.388", "t": "quot surgant in quoque loco cedantque per horas,"}, {"st": "3.389", "t": "partibus ut prendi possint orientia certis,"}, {"st": "3.390", "t": "ne falsus dubia ratione horoscopos erret."}, {"st": "3.391", "t": "atque hoc in totum certa sub lege sequendum est, 390"}, {"st": "3.392", "t": "singula quod nequeunt, per tot distantia motus,"}, {"st": "3.393", "t": "temporibus numerisque suis exacta referri."}, {"st": "3.394", "t": "a me sumat iter positum, sibi quisque sequatur"}, {"st": "3.395", "t": "perque suos tendat gressus, mihi debeat artem."}, {"st": "3.396", "t": "quacumque hoc parti terrarum quisque requiret, 395"}, {"st": "3.397", "t": "deducat proprias noctemque diemque per horas"}, {"st": "3.398", "t": "maxima sub Cancro minimis quae cingitur umbris;"}, {"st": "3.399", "t": "et sextam summae, fuerit quae forte, diurnae"}, {"st": "3.400", "t": "vicino tribuat post Cancri templa Leoni;"}, {"st": "3.401", "t": "at quae nocturnis fuerit mensura tenebris 400"}, {"st": "3.402", "t": "in totidem partes simili ratione secanda est,"}, {"st": "3.403", "t": "ut, quantum una ferat, tantum tribuatur ad ortus"}, {"st": "3.404", "t": "temporis averso nascenti sidere Tauro."}, {"st": "3.405", "t": "has inter quasque accipiet Nemeaeus horas"}, {"st": "3.406", "t": "quod discrimen erit, per tris id divide partes, 405"}, {"st": "3.407", "t": "tertia ut accedat Geminis, qua tempora Tauri"}, {"st": "3.408", "t": "vincant, atque eadem Cancro similisque Leoni,"}, {"st": "3.409", "t": "sed certa sub lege, prioris semper ut astri 411"}, {"st": "3.410", "t": "incolumem servent summam crescantque novando."}, {"st": "3.411", "t": "sic erit ad summam ratio perducta priorem 408"}, {"st": "3.412", "t": "quam modo divisis Nemeaeus duxerit horis."}, {"st": "3.413", "t": "inde pari Virgo procedat temporis auctu."}, {"st": "3.414", "t": "his usque ad Chelas horarum partibus aucta 413"}, {"st": "3.415", "t": "per totidem e Libra decrescent sidera partes."}, {"st": "3.416", "t": "et, quantis in utrumque moris tollentur ad ortus,"}, {"st": "3.417", "t": "diversam in sortem tantis mergentur ad umbras."}, {"st": "3.418", "t": "haec erit horarum ratio ducenda per orbem"}, {"st": "3.419", "t": "&lt;signorum: nunc in noscenda pone laborem&gt; 417a"}, {"st": "3.420", "t": "illa, quot stadiis oriantur quaeque cadantque."}, {"st": "3.421", "t": "quae &lt;quater et&gt; cum ter centum vicenaque constent,"}, {"st": "3.422", "t": "detrahitur summae tota pars, quota demitur usque 420"}, {"st": "3.423", "t": "omnibus ex horis aestivae nomine noctis,"}, {"st": "3.424", "t": "solstitium summo peragit cum Phoebus Olympo."}, {"st": "3.425", "t": "quodque his exsuperat demptis id ducito in aequas"}, {"st": "3.426", "t": "sex partes, sextamque ardenti trade Leoni."}, {"st": "3.427", "t": "rursus qui steterit numerus sub nomine noctis 425"}, {"st": "3.428", "t": "eius erit signo Tauri pars illa dicanda."}, {"st": "3.429", "t": "quodque, haec, exsuperat, pars cum superatur ab illa,"}, {"st": "3.430", "t": "distinguitque duas medio discrimine summas,"}, {"st": "3.431", "t": "tertia pars eius, numero super addita Tauri,"}, {"st": "3.432", "t": "tradetur Geminis. simili tum cetera lucro 430"}, {"st": "3.433", "t": "procedent numeros semper tutata priores"}, {"st": "3.434", "t": "augebuntque novo vicinas munere summas,"}, {"st": "3.435", "t": "donec perveniant ad iustae sidera Librae:"}, {"st": "3.436", "t": "ex illa totidem per partes sic breviantur"}, {"st": "3.437", "t": "Lanigeri ad fines; conversaque omnia lege 435"}, {"st": "3.438", "t": "accipiunt perduntque paris cedentia sortes."}, {"st": "3.439", "t": "haec via monstrabit stadiorum ponere summas"}, {"st": "3.440", "t": "et numerare suos ortus per sidera cuncta."}, {"st": "3.441", "t": "quod bene cum propriis simul acceptaveris horis,"}, {"st": "3.442", "t": "in nulla fallet regione horoscopos umquam, 440"}, {"st": "3.443", "t": "cum poterunt certis numerari singula signa"}, {"st": "3.444", "t": "temporibus parte ex illa quam Phoebus habebit."}, {"st": "3.445", "t": "Nunc, quibus hiberni momentis surgere menses"}, {"st": "3.446", "t": "incipiant (neque enim paribus per sidera cuncta"}, {"st": "3.447", "t": "procedunt gradibus, nivei dum vellera signi 445"}, {"st": "3.448", "t": "contingant aequum luces cogentia et umbras"}, {"st": "3.449", "t": "ferre iugum), magna est ratio breviterque docenda."}, {"st": "3.450", "t": "principio capienda tibi est mensura diei"}, {"st": "3.451", "t": "quam minimam Capricornus agit, noctisque per horas"}, {"st": "3.452", "t": "quam summam; quodque a iusto superaverit umbris, 450"}, {"st": "3.453", "t": "perdiderint luces, eius pars tertia signo"}, {"st": "3.454", "t": "tradenda est medio semper, qua sorte retenta"}, {"st": "3.455", "t": "dimidio vincat primum, vincatur et ipsum"}, {"st": "3.456", "t": "extremo: totum in partes ita digere tempus."}, {"st": "3.457", "t": "his opibus tria signa valent; sed summa prioris 455"}, {"st": "3.458", "t": "ac medii numeri coniuncta sequentibus astris"}, {"st": "3.459", "t": "cesserit, ut, senis fuerit si longior horis"}, {"st": "3.460", "t": "brumali nox forte die, Capricornus in horam"}, {"st": "3.461", "t": "dimidiam attollat luces, et Aquarius horam"}, {"st": "3.462", "t": "ipse suam proprie ducat summaeque priori 460"}, {"st": "3.463", "t": "adiungat, Pisces tantum sibi temporis ipsi"}, {"st": "3.464", "t": "constituant, quantum accipiant de sorte prioris,"}, {"st": "3.465", "t": "et tribus expletis horis noctemque diemque"}, {"st": "3.466", "t": "Lanigero tradant aequandam tempore veris."}, {"st": "3.467", "t": "incipit a sexta tempus procedere parte 465"}, {"st": "3.468", "t": "dividuum; triplicant vires haerentia signa"}, {"st": "3.469", "t": "ultimaque acceptas duplicant. ita summa diebus"}, {"st": "3.470", "t": "redditur, aequatae solvuntur faenore noctes 473"}, {"st": "3.471", "t": "rursus et incipiunt propria de sorte diebus"}, {"st": "3.472", "t": "cedere diversa labentia tempora lege. 468"}, {"st": "3.473", "t": "namque Aries totidem deducit noctibus horas"}, {"st": "3.474", "t": "quot prius abstulerant proprio sub nomine Pisces,"}, {"st": "3.475", "t": "hora datur Tauro, cumuletque ut damna priora"}, {"st": "3.476", "t": "dimidiam adiungunt Gemini. sic ultima primis"}, {"st": "3.477", "t": "respondent, pariterque, illis quae proxima fulgent, 475"}, {"st": "3.478", "t": "et media aequatis censentur viribus astra."}, {"st": "3.479", "t": "[praecipuosque gerunt varianda ad tempora motus]"}, {"st": "3.480", "t": "hac vice descendunt noctes a sidere brumae"}, {"st": "3.481", "t": "tollunturque dies, annique invertitur orbis,"}, {"st": "3.482", "t": "solstitium tardi dum fit sub sidere Cancri; 480"}, {"st": "3.483", "t": "tumque diem brumae nox aequat, tempora noctis"}, {"st": "3.484", "t": "longa dies, similique redit, quam creverat, actu."}, {"st": "3.485", "t": "Illa etiam poterit nascens via ducere ad astrum"}, {"st": "3.486", "t": "quod quandoque vadis emissum redditur orbi."}, {"st": "3.487", "t": "nam quota sit lucis, si luce requiritur, hora 485"}, {"st": "3.488", "t": "aspicies, atque hunc numerum revocabis in ipsum"}, {"st": "3.489", "t": "multiplicans decies, adiectis insuper eidem"}, {"st": "3.490", "t": "quinque tamen summis, quia qualicumque sub hora"}, {"st": "3.491", "t": "ter quinas mundi se tollunt sidera partes."}, {"st": "3.492", "t": "hic ubi constiterit numerus, coniungere et illas, 490"}, {"st": "3.493", "t": "quae superent Phoebo partes per signa, memento."}, {"st": "3.494", "t": "ex hac tricenas summa per sidera partes"}, {"st": "3.495", "t": "distribues, primamque vicem, quo Phoebus in astro"}, {"st": "3.496", "t": "fulserit, inde aliis, solem quaecumque sequentur."}, {"st": "3.497", "t": "tum quo subsistet numerus consumptus in astro 495"}, {"st": "3.498", "t": "quave in parte suam summam nomenque relinquet"}, {"st": "3.499", "t": "haec erit exoriens et pars et forma per ignes."}, {"st": "3.500", "t": "* 497a"}, {"st": "3.501", "t": "contineat partes. ubi summam feceris unam,"}, {"st": "3.502", "t": "tricenas dabis ex illa per singula signa,"}, {"st": "3.503", "t": "donec deficiat numerus; quaque ille sub astri 500"}, {"st": "3.504", "t": "parte cadet, credas illam cum corpore natam"}, {"st": "3.505", "t": "esse hominis pariterque orbem vidisse per umbras."}, {"st": "3.506", "t": "sic erit ipse tibi rapidis quaerendus in astris"}, {"st": "3.507", "t": "natalis mundi certoque horoscopos ortu,"}, {"st": "3.508", "t": "ut, cum exacta fides steterit sub cardine primo, 505"}, {"st": "3.509", "t": "fallere non possint summi fastigia caeli,"}, {"st": "3.510", "t": "non celeres obitus, stent fundamenta sub imo,"}, {"st": "3.511", "t": "[stent veri stellarum obitus verique subortus]"}, {"st": "3.512", "t": "sideraque in proprias vires sortesque recedant."}, {"st": "3.513", "t": "Nunc sua reddentur generatim tempora signis, 510"}, {"st": "3.514", "t": "quae divisa etiam proprios ducuntur in annos"}, {"st": "3.515", "t": "et menses lucesque suas horasque dierum,"}, {"st": "3.516", "t": "per quae praecipuas ostendunt singula vires."}, {"st": "3.517", "t": "primus erit signi, quo Sol effulserit, annus,"}, {"st": "3.518", "t": "annua quod lustrans consumit tempora mundum; 515"}, {"st": "3.519", "t": "proximus atque alii subeuntia signa sequuntur."}, {"st": "3.520", "t": "Luna dabit menses, peragit quod menstrua cursum."}, {"st": "3.521", "t": "tutelaeque suae primas horoscopos horas"}, {"st": "3.522", "t": "asserit atque dies, traditque sequentibus astris."}, {"st": "3.523", "t": "sic annum mensesque suos natura diesque 520"}, {"st": "3.524", "t": "atque ipsas voluit numerari signa per horas,"}, {"st": "3.525", "t": "omnia ut omne foret divisum tempus in astra"}, {"st": "3.526", "t": "perque alterna suos variaret sidera motus,"}, {"st": "3.527", "t": "ut cuiusque vices ageret redeuntis in orbem."}, {"st": "3.528", "t": "idcirco tanta est rerum discordia in aevo 525"}, {"st": "3.529", "t": "et subtexta malis bona sunt lacrimaeque sequuntur"}, {"st": "3.530", "t": "vota nec inconstans servat fortuna tenorem;"}, {"st": "3.531", "t": "usque adeo permixta fluit nec permanet usquam,"}, {"st": "3.532", "t": "amisitque fidem variando cuncta per omnis."}, {"st": "3.533", "t": "non annis anni nec menses mensibus usquam 530"}, {"st": "3.534", "t": "conveniunt, seque ipsa dies alia usque requirit"}, {"st": "3.535", "t": "horaque non ulli similis producitur horae,"}, {"st": "3.536", "t": "tempora quod distant, propriis parentia signis,"}, {"st": "3.537", "t": "per numeros omnis aevi divisa volantis,"}, {"st": "3.538", "t": "talisque efficiunt vitas casusque animantum, 535"}, {"st": "3.539", "t": "qualia sunt, quorum vicibus tum vertimur, astra."}, {"st": "3.540", "t": "Sunt quibus et caeli placeat nascentis ab orae"}, {"st": "3.541", "t": "sidere, quem memorant horoscopon inventores,"}, {"st": "3.542", "t": "parte quod ex illa describitur hora diebus,"}, {"st": "3.543", "t": "omne genus rationis agi per tempora et astra 540"}, {"st": "3.544", "t": "et capite ex uno menses annosque diesque"}, {"st": "3.545", "t": "incipere atque horas tradique sequentibus astris;"}, {"st": "3.546", "t": "et, quamquam socia nascantur origine cuncta,"}, {"st": "3.547", "t": "diversas tamen esse vices, quod tardius illa,"}, {"st": "3.548", "t": "haec citius peragant orbem. semel omnia ad astra 545"}, {"st": "3.549", "t": "hora die, bis mense dies venit, unus in anno"}, {"st": "3.550", "t": "mensis et exactis bis sex iam solibus annus."}, {"st": "3.551", "t": "difficile est in idem tempus concurrere cuncta,"}, {"st": "3.552", "t": "unius ut signi pariter sit mensis et annus"}, {"st": "3.553", "t": "&lt;atque dies atque hora simul: sibi discrepat ordo. 549a"}, {"st": "3.554", "t": "saepe fit ut, mitis tulerint qui sideris annum,&gt; 549b"}, {"st": "3.555", "t": "asperioris agant mensem; si mensis in astrum"}, {"st": "3.556", "t": "laetius inciderit, signum sit triste diei;"}, {"st": "3.557", "t": "si fortuna diem foveat, sit durior hora."}, {"st": "3.558", "t": "idcirco nihil in totum sibi credere fas est,"}, {"st": "3.559", "t": "non annos signis, menses vertentibus annis,"}, {"st": "3.560", "t": "mensibus aut luces, aut omnis lucibus horas, 555"}, {"st": "3.561", "t": "quod nunc illa nimis properant, nunc illa morantur,"}, {"st": "3.562", "t": "et modo dest aliis, modo adest, vicibusque recedit"}, {"st": "3.563", "t": "aut redit atque alio mutatur tempore tempus"}, {"st": "3.564", "t": "interpellatum variata sorte dierum."}, {"st": "3.565", "t": "Et, quoniam docui, per singula tempora, vitae 560"}, {"st": "3.566", "t": "quod quandoque genus veniat, cuiusque sit astri"}, {"st": "3.567", "t": "quisque annus, cuius mensis, simul hora diesque,"}, {"st": "3.568", "t": "altera nunc ratio, quae summam continet aevi,"}, {"st": "3.569", "t": "reddenda est, quot quaeque annos dare signa ferantur."}, {"st": "3.570", "t": "quae tibi, cum finem vitae per sidera quaeris, 565"}, {"st": "3.571", "t": "respicienda manet ratio numerisque notanda."}, {"st": "3.572", "t": "bis quinos annos Aries unumque triente"}, {"st": "3.573", "t": "fraudatum dabit. appositis tu, Taure, duobus"}, {"st": "3.574", "t": "vincis, sed totidem Geminorum vinceris astro,"}, {"st": "3.575", "t": "tuque bis octonos, Cancer, binosque trientes, 570"}, {"st": "3.576", "t": "bisque novem, Nemeaee, dabis bessemque sub illis."}, {"st": "3.577", "t": "Erigone geminatque decem geminatque trientem,"}, {"st": "3.578", "t": "nec plures fuerint Librae quam Virginis anni."}, {"st": "3.579", "t": "Scorpios aequabit tribuentem dona Leonem."}, {"st": "3.580", "t": "Centauri fuerint eadem quae munera Cancri. 575"}, {"st": "3.581", "t": "ter quinos, Capricorne, dares, si quattuor essent"}, {"st": "3.582", "t": "appositi menses. triplicabit Aquarius annos"}, {"st": "3.583", "t": "quattuor et menses vitam producet in octo."}, {"st": "3.584", "t": "Piscibus est Aries et sorte et finibus haerens:"}, {"st": "3.585", "t": "lustra decem tribuent solis cum mensibus octo. 580"}, {"st": "3.586", "t": "Nec satis est annos signorum noscere certos,"}, {"st": "3.587", "t": "ne lateat ratio finem quaerentibus aevi:"}, {"st": "3.588", "t": "templa quoque et partes caeli sua munera norunt"}, {"st": "3.589", "t": "et proprias tribuunt certo discrimine summas,"}, {"st": "3.590", "t": "cum bene constiterit stellarum conditus ordo. 585"}, {"st": "3.591", "t": "sed mihi templorum tantum nunc iura canentur;"}, {"st": "3.592", "t": "mox veniet mixtura suis cum viribus omnis,"}, {"st": "3.593", "t": "cum bene materies steterit percognita rerum"}, {"st": "3.594", "t": "non interpositis turbatarum undique membris."}, {"st": "3.595", "t": "si bene constiterit primo sub cardine Luna, 590"}, {"st": "3.596", "t": "qua redit in terras mundus, nascensque tenebit"}, {"st": "3.597", "t": "exortum, octo tenor decies ducetur in annos"}, {"st": "3.598", "t": "si duo decedant. at, cum sub culmine summo"}, {"st": "3.599", "t": "consistet, tribus hic numerus fraudabitur annis."}, {"st": "3.600", "t": "bis quadragenos occasus dives in actus 595"}, {"st": "3.601", "t": "solis erat, numero nisi desset olympias una."}, {"st": "3.602", "t": "imaque tricenos bis fundamenta per annos"}, {"st": "3.603", "t": "censentur bis sex adiectis messibus aevo."}, {"st": "3.604", "t": "quodque prius natum fuerit dextrumque trigonum"}, {"st": "3.605", "t": "hoc sexagenos tribuit duplicatque quaternos. 600"}, {"st": "3.606", "t": "quod fuerit laevum praelataque signa sequetur"}, {"st": "3.607", "t": "tricenos annos duplicat, tris insuper addit."}, {"st": "3.608", "t": "quaeque super signum nascens a cardine primum"}, {"st": "3.609", "t": "tertia sors manet et summo iam proxima caelo"}, {"st": "3.610", "t": "haec ter vicenos geminat, tris abstrahit annos. 605"}, {"st": "3.611", "t": "quaeque infra veniet spatio divisa sub aequo"}, {"st": "3.612", "t": "per quinquagenas complet sua munera brumas."}, {"st": "3.613", "t": "quemque locum superat nascens horoscopos, ille"}, {"st": "3.614", "t": "dena quater revocat vertentis tempora solis"}, {"st": "3.615", "t": "accumulatque duos cursus iuvenemque relinquit. 610"}, {"st": "3.616", "t": "at qui praecedit surgentis cardinis oram"}, {"st": "3.617", "t": "vicenos ternosque dabit nascentibus annos"}, {"st": "3.618", "t": "vix degustatam rapiens sub flore iuventam."}, {"st": "3.619", "t": "quod super occasus templum est ter dena remittit"}, {"st": "3.620", "t": "annorum spatia et decimam tribus applicat auctis. 615"}, {"st": "3.621", "t": "inferius puerum interimet, bis sexque peracti"}, {"st": "3.622", "t": "immatura trahent natales corpora morti."}, {"st": "3.623", "t": "Sed tamen in primis memori sunt mente notanda"}, {"st": "3.624", "t": "partibus adversis quae surgunt condita signa"}, {"st": "3.625", "t": "divisumque tenent aequo discrimine caelum; 620"}, {"st": "3.626", "t": "quae tropica appellant, quod in illis quattuor anni"}, {"st": "3.627", "t": "tempora vertuntur signis nodosque resolvunt"}, {"st": "3.628", "t": "totumque emutant converso cardine mundum"}, {"st": "3.629", "t": "inducuntque novas operum rerumque figuras."}, {"st": "3.630", "t": "Cancer ad aestivae fulget fastigia zonae 625"}, {"st": "3.631", "t": "extenditque diem summum parvoque recessu"}, {"st": "3.632", "t": "destruit et, quanto fraudavit tempore luces,"}, {"st": "3.633", "t": "in tantum noctes auget: stat summa per omnis."}, {"st": "3.634", "t": "tum Cererem fragili properant destringere culmo,"}, {"st": "3.635", "t": "Campus et in varias destringit membra palaestras, 630"}, {"st": "3.636", "t": "et tepidas pelagus iactatum languet in undas."}, {"st": "3.637", "t": "tunc et bella fero tractantur Marte cruenta"}, {"st": "3.638", "t": "nec Scythiam defendit hiems; Germania sicca"}, {"st": "3.639", "t": "iam tellure fugit Nilusque tumescit in arva."}, {"st": "3.640", "t": "hic rerum status est, Cancri cum sidere Phoebus 635"}, {"st": "3.641", "t": "solstitium facit et summo versatur Olympo."}, {"st": "3.642", "t": "Parte ex adversa brumam Capricornus inertem"}, {"st": "3.643", "t": "per minimas cogit luces et maxima noctis"}, {"st": "3.644", "t": "tempora, producitque diem tenebrasque resolvit,"}, {"st": "3.645", "t": "inque vicem nunc damna regit, nunc tempora supplet. 640"}, {"st": "3.646", "t": "tunc riget omnis ager, clausum mare, condita castra,"}, {"st": "3.647", "t": "nec tolerant medias hiemes sudantia saxa,"}, {"st": "3.648", "t": "statque uno natura loco paulumque quiescit."}, {"st": "3.649", "t": "Proxima in effectum et similis referentia motus"}, {"st": "3.650", "t": "esse ferunt luces aequantia signa tenebris. 645"}, {"st": "3.651", "t": "namque Aries Phoebum repetentem sidera Cancri"}, {"st": "3.652", "t": "inter principium reditus finemque coercet"}, {"st": "3.653", "t": "tempora diviso iungens concordia mundo,"}, {"st": "3.654", "t": "convertitque vices victumque a sidere Librae"}, {"st": "3.655", "t": "exsuperare diem iubet et succumbere noctes, 650"}, {"st": "3.656", "t": "aestivi donec veniant ad sidera Cancri."}, {"st": "3.657", "t": "tum primum miti pelagus consternitur unda"}, {"st": "3.658", "t": "et varios audet flores emittere tellus;"}, {"st": "3.659", "t": "tum pecudum volucrumque genus per pabula laeta"}, {"st": "3.660", "t": "in Venerem partumque ruit, totumque canora 655"}, {"st": "3.661", "t": "voce nemus loquitur frondemque virescit in omnem."}, {"st": "3.662", "t": "viribus in tantum signi natura movetur."}, {"st": "3.663", "t": "Huic ex adverso simili cum sorte refulget"}, {"st": "3.664", "t": "Libra diem noctemque pari cum foedere ducens,"}, {"st": "3.665", "t": "tantum quod victas usque ad se vincere noctes 660"}, {"st": "3.666", "t": "ex ipsa iubet, ad brumae dum tempora surgant."}, {"st": "3.667", "t": "tum Liber gravida descendit plenus ab ulmo"}, {"st": "3.668", "t": "pinguiaque impressis despumant musta racemis;"}, {"st": "3.669", "t": "mandant et sulcis Cererem, dum terra tepore"}, {"st": "3.670", "t": "autumni resoluta patet, dum semina ducit. 665"}, {"st": "3.671", "t": "Quattuor haec et in arte valent, ut tempora vertunt"}, {"st": "3.672", "t": "sic hos aut illos rerum flectentia casus"}, {"st": "3.673", "t": "nec quicquam in prima patientia sede manere."}, {"st": "3.674", "t": "sed non per totas aequa est versura figuras,"}, {"st": "3.675", "t": "annua nec plenis flectuntur tempora signis. 670"}, {"st": "3.676", "t": "una dies sub utroque aequat sibi tempore noctem,"}, {"st": "3.677", "t": "dum Libra atque Aries autumnum verque figurant;"}, {"st": "3.678", "t": "una dies toto Cancri longissima signo,"}, {"st": "3.679", "t": "cui nox aequalis Capricorni sidere fertur:"}, {"st": "3.680", "t": "cetera nunc urgent vicibus, nunc tempora cedunt. 675"}, {"st": "3.681", "t": "una ergo in tropicis pars est cernenda figuris,"}, {"st": "3.682", "t": "quae moveat mundum, quae rerum tempora mutet,"}, {"st": "3.683", "t": "facta novet, consulta alios declinet in usus,"}, {"st": "3.684", "t": "omnia in aversum flectat contraque revolvat."}, {"st": "3.685", "t": "has quidam vires octava in parte reponunt; 680"}, {"st": "3.686", "t": "sunt quibus esse placet decimae; nec defuit auctor"}, {"st": "3.687", "t": "qui primae momenta daret frenosque dierum."}, {"sp": "HDR", "t": "Liber IV"}, {"st": "4.1", "t": "Quid tam sollicitis vitam consumimus annis"}, {"st": "4.2", "t": "torquemurque metu caecaque cupidine rerum"}, {"st": "4.3", "t": "aeternisque senes curis, dum quaerimus, aevum"}, {"st": "4.4", "t": "perdimus et nullo votorum fine beati"}, {"st": "4.5", "t": "victuros agimus semper nec vivimus umquam, 5"}, {"st": "4.6", "t": "pauperiorque bonis quisque est, quia plura requirit"}, {"st": "4.7", "t": "nec quod habet numerat, tantum quod non habet optat,"}, {"st": "4.8", "t": "cumque sibi parvos usus natura reposcat"}, {"st": "4.9", "t": "materiam struimus magnae per vota ruinae"}, {"st": "4.10", "t": "luxuriamque lucris emimus luxuque rapinas, 10"}, {"st": "4.11", "t": "et summum census pretium est effundere censum?"}, {"st": "4.12", "t": "solvite, mortales, animos curasque levate"}, {"st": "4.13", "t": "totque supervacuis vitam deplete querellis."}, {"st": "4.14", "t": "fata regunt orbem, certa stant omnia lege"}, {"st": "4.15", "t": "longaque per certos signantur tempora casus. 15"}, {"st": "4.16", "t": "nascentes morimur, finisque ab origine pendet."}, {"st": "4.17", "t": "hinc et opes et regna fluunt et, saepius orta,"}, {"st": "4.18", "t": "paupertas, artesque datae moresque creatis"}, {"st": "4.19", "t": "et vitia et laudes, damna et compendia rerum."}, {"st": "4.20", "t": "nemo carere dato poterit nec habere negatum 20"}, {"st": "4.21", "t": "fortunamve suis invitam prendere votis"}, {"st": "4.22", "t": "aut fugere instantem: sors est sua cuique ferenda."}, {"st": "4.23", "t": "an, nisi fata darent leges vitaeque necisque,"}, {"st": "4.24", "t": "fugissent ignes Aenean, Troia sub uno"}, {"st": "4.25", "t": "non eversa viro fatis vicisset in ipsis? 25"}, {"st": "4.26", "t": "aut lupa proiectos nutrisset Martia fratres,"}, {"st": "4.27", "t": "Roma casis enata foret, pecudumque magistri"}, {"st": "4.28", "t": "in Capitolinos duxissent fulmina montes,"}, {"st": "4.29", "t": "includive sua potuisset Iuppiter arce,"}, {"st": "4.30", "t": "captus et <a> captis orbis foret: igne sepulto 30"}, {"st": "4.31", "t": "vulneribus victor repetisset Mucius urbem,"}, {"st": "4.32", "t": "solus et oppositis clausisset Horatius armis"}, {"st": "4.33", "t": "pontem urbemque simul, rupisset foedera virgo,"}, {"st": "4.34", "t": "tresque sub unius fratres virtute iacerent?"}, {"st": "4.35", "t": "nulla acies tantum vicit: pendebat ab uno 35"}, {"st": "4.36", "t": "Roma viro regnumque orbis sortita iacebat."}, {"st": "4.37", "t": "quid referam Cannas admotaque moenibus arma"}, {"st": "4.38", "t": "Varronemque fuga magnum 38a"}, {"st": "4.39", "t": "Fabiumque morando 39b"}, {"st": "4.40", "t": "postque tuos, Trasimenne, lacus, 39a"}, {"st": "4.41", "t": "cum vincere posset, 38b"}, {"st": "4.42", "t": "accepisse iugum victae Carthaginis arces, 40"}, {"st": "4.43", "t": "seque ratum Hannibalem nostris cecidisse catenis"}, {"st": "4.44", "t": "exitium generis furtiva morte luisse?"}, {"st": "4.45", "t": "adde etiam Latias acies Romamque suismet"}, {"st": "4.46", "t": "pugnantem membris, adice et civilia bella"}, {"st": "4.47", "t": "et Cimbrum in Mario Mariumque in carcere victum. 45"}, {"st": "4.48", "t": "quod, consul totiens, exul, quod &lt;de&gt; exule consul"}, {"st": "4.49", "t": "adiacuit Libycis compar iactura ruinis"}, {"st": "4.50", "t": "eque crepidinibus cepit Carthaginis urbem,"}, {"st": "4.51", "t": "hoc, nisi fata darent, numquam fortuna tulisset."}, {"st": "4.52", "t": "quis te Niliaco periturum litore, Magne, 50"}, {"st": "4.53", "t": "post victas Mithridatis opes pelagusque receptum"}, {"st": "4.54", "t": "et tris emenso meritos ex orbe triumphos,"}, {"st": "4.55", "t": "cum te iam posses alium componere Magnum,"}, {"st": "4.56", "t": "crederet, ut corpus sepeliret naufragus ignis"}, {"st": "4.57", "t": "eiectaeque rogum facerent fragmenta carinae? 55"}, {"st": "4.58", "t": "quis tantum mutare potest sine numine fati?"}, {"st": "4.59", "t": "ille etiam caelo genitus caeloque receptus,"}, {"st": "4.60", "t": "cum bene compositis victor civilibus armis"}, {"st": "4.61", "t": "iura togae regeret, totiens praedicta cavere"}, {"st": "4.62", "t": "vulnera non potuit: toto spectante senatu, 60"}, {"st": "4.63", "t": "indicium dextra retinens nomenque, cruore"}, {"st": "4.64", "t": "delevit proprio, possent ut vincere fata."}, {"st": "4.65", "t": "quid numerem eversas urbes regumque ruinas,"}, {"st": "4.66", "t": "inque rogo Croesum Priamique in litore truncum,"}, {"st": "4.67", "t": "cui nec Troia rogus? quid Xerxen, maius et ipso 65"}, {"st": "4.68", "t": "naufragium pelago? quid capto sanguine regem"}, {"st": "4.69", "t": "Romanis positum, raptosque ex ignibus ignes"}, {"st": "4.70", "t": "cedentemque viro flammam quae templa ferebat?"}, {"st": "4.71", "t": "quot subitae veniunt validorum in corpora mortes"}, {"st": "4.72", "t": "seque ipsae rursus fugiunt errantque per ignes! 70"}, {"st": "4.73", "t": "ex ipsis quidam elati rediere sepulcris,"}, {"st": "4.74", "t": "atque his vita duplex, illis vix contigit una."}, {"st": "4.75", "t": "ecce levis perimit morbus graviorque remittit;"}, {"st": "4.76", "t": "succumbunt artes, rationis vincitur usus,"}, {"st": "4.77", "t": "cura nocet, cessare iuvat, mora saepe malorum 75"}, {"st": "4.78", "t": "dat pausas; laeduntque cibi parcuntque venena."}, {"st": "4.79", "t": "degenerant nati patribus vincuntque parentes"}, {"st": "4.80", "t": "ingeniumque suum retinent; transitque per illum,"}, {"st": "4.81", "t": "ex illo fortuna venit. furit alter amore"}, {"st": "4.82", "t": "et pontum tranare potest et vertere Troiam, 80"}, {"st": "4.83", "t": "alterius frons est scribendis legibus apta."}, {"st": "4.84", "t": "ecce patrem nati perimunt natosque parentes"}, {"st": "4.85", "t": "mutuaque armati coeunt in vulnera fratres."}, {"st": "4.86", "t": "non hominum hoc bellum est; coguntur tanta moveri"}, {"st": "4.87", "t": "inque suas ferri poenas lacerandaque membra. 85"}, {"st": "4.88", "t": "quod Decios non omne tulit, non omne Camillos"}, {"st": "4.89", "t": "tempus et invicta devictum mente Catonem,"}, {"st": "4.90", "t": "materies in rem superat sed lege repugnat."}, {"st": "4.91", "t": "et neque paupertas breviores excipit annos"}, {"st": "4.92", "t": "nec sunt immensis opibus venalia fata, 90"}, {"st": "4.93", "t": "sed rapit ex tecto funus Fortuna superbo"}, {"st": "4.94", "t": "indicitque rogum summis statuitque sepulcrum."}, {"st": "4.95", "t": "quantum est hoc regnum, quod regibus imperat ipsis!"}, {"st": "4.96", "t": "quin etiam infelix virtus et noxia felix,"}, {"st": "4.97", "t": "et male consultis pretium est, prudentia fallit; 95"}, {"st": "4.98", "t": "nec Fortuna probat causas, sequiturque merentis,"}, {"st": "4.99", "t": "sed vaga per cunctos nullo discrimine fertur."}, {"st": "4.100", "t": "scilicet est aliud, quod nos cogatque regatque,"}, {"st": "4.101", "t": "maius, et in proprias ducat mortalia leges"}, {"st": "4.102", "t": "attribuatque suos ex se nascentibus annos 100"}, {"st": "4.103", "t": "fortunaeque vices. permiscet saepe ferarum"}, {"st": "4.104", "t": "corpora cum membris hominum: non seminis ille"}, {"st": "4.105", "t": "partus erit; quid enim nobis commune ferisque,"}, {"st": "4.106", "t": "quisve in portenti noxam peccarit adulter?"}, {"st": "4.107", "t": "astra novant formas caelumque interserit ora. 105"}, {"st": "4.108", "t": "denique, si non est, fati cur traditur ordo,"}, {"st": "4.109", "t": "cunctaque temporibus certis ventura canuntur?"}, {"st": "4.110", "t": "nec tamen haec ratio facinus defendere pergit"}, {"st": "4.111", "t": "virtutemve suis fraudare in praemia donis."}, {"st": "4.112", "t": "nam neque mortiferas quisquam minus oderit herbas 110"}, {"st": "4.113", "t": "quod non arbitrio veniunt sed semine certo,"}, {"st": "4.114", "t": "gratia nec levior tribuetur dulcibus escis"}, {"st": "4.115", "t": "quod natura dedit fruges, non ulla voluntas."}, {"st": "4.116", "t": "sic hominum meritis tanto sit gloria maior"}, {"st": "4.117", "t": "quod caelo laudem debent, rursusque nocentis 115"}, {"st": "4.118", "t": "oderimus magis in culpam poenasque creatos."}, {"st": "4.119", "t": "nec refert scelus unde cadat, scelus esse fatendum."}, {"st": "4.120", "t": "hoc quoque fatale est, sic ipsum expendere fatum."}, {"st": "4.121", "t": "[quod quoniam docui, superest nunc ordine certo"}, {"st": "4.122", "t": "caelestis fabricare gradus, qui ducere flexo 120"}, {"st": "4.123", "t": "tramite pendentem valeant ad sidera vatem]"}, {"st": "4.124", "t": "Nunc tibi signorum mores summumque colorem"}, {"st": "4.125", "t": "et studia et varias artes ex ordine reddam."}, {"st": "4.126", "t": "Dives fecundis Aries in vellera lanis"}, {"st": "4.127", "t": "exutusque novis rursum spem semper habebit, 125"}, {"st": "4.128", "t": "naufragiumque inter subitum censusque beatos"}, {"st": "4.129", "t": "crescendo cadet et votis in damna feretur,"}, {"st": "4.130", "t": "in vulgumque dabit fructus et mille per artes"}, {"st": "4.131", "t": "vellera diversos ex se parientia quaestus:"}, {"st": "4.132", "t": "nunc glomerare rudis nunc rursus solvere lanas, 130"}, {"st": "4.133", "t": "nunc tenuare levi filo nunc ducere telas,"}, {"st": "4.134", "t": "nunc emere et varias in quaestum vendere vestes,"}, {"st": "4.135", "t": "quis sine non poterant ullae subsistere gentes"}, {"st": "4.136", "t": "vel sine luxuria. tantum est opus, ipsa suismet"}, {"st": "4.137", "t": "asseruit Pallas manibus dignumque putavit, 135"}, {"st": "4.138", "t": "seque in Arachnaeo magnam putat esse triumpho."}, {"st": "4.139", "t": "haec studia et similis dicet nascentibus artes,"}, {"st": "4.140", "t": "et dubia in trepido praecordia pectore finget"}, {"st": "4.141", "t": "seque sua semper cupientia vendere laude."}, {"st": "4.142", "t": "Taurus simplicibus dotabit rura colonis 140"}, {"st": "4.143", "t": "pacatisque labor veniet; nec praemia laudis"}, {"st": "4.144", "t": "sed terrae tribuet partus. summittit in astris"}, {"st": "4.145", "t": "colla iugumque suis poscit cervicibus ipse."}, {"st": "4.146", "t": "ille suis Phoebi portat cum cornibus orbem"}, {"st": "4.147", "t": "militiam indicit terris et segnia rura 145"}, {"st": "4.148", "t": "in veteres revocat cultus, dux ipse laboris,"}, {"st": "4.149", "t": "nec iacet in sulcis solvitque in pulvere pectus."}, {"st": "4.150", "t": "Serranos Curiosque tulit fascesque per arva"}, {"st": "4.151", "t": "tradidit, eque suo dictator venit aratro."}, {"st": "4.152", "t": "laudis amor tacitae; mentes et corpora tarda 150"}, {"st": "4.153", "t": "mole valent, habitatque puer sub fronte Cupido."}, {"st": "4.154", "t": "Mollius e Geminis studium est et mitior aetas"}, {"st": "4.155", "t": "per varios cantus modulataque vocibus ora"}, {"st": "4.156", "t": "et gracilis calamos et nervis insita verba"}, {"st": "4.157", "t": "ingenitumque sonum: labor est etiam ipse voluptas. 155"}, {"st": "4.158", "t": "arma procul lituosque volunt tristemque senectam,"}, {"st": "4.159", "t": "otia et aeternam peragunt in amore iuventam."}, {"st": "4.160", "t": "inveniunt et in astra vias numerisque modisque"}, {"st": "4.161", "t": "consummant orbem postque ipsos sidera linquunt:"}, {"st": "4.162", "t": "natura ingenio minor est perque omnia servit. 160"}, {"st": "4.163", "t": "in tot fecundi Gemini commenta feruntur."}, {"st": "4.164", "t": "Cancer ad ardentem fulgens in cardine metam,"}, {"st": "4.165", "t": "quam Phoebus summis revocatus cursibus ambit,"}, {"st": "4.166", "t": "articulum mundi retinet lucesque reflectit."}, {"st": "4.167", "t": "ille tenax animi nullosque effusus in usus 165"}, {"st": "4.168", "t": "attribuit varios quaestus artemque lucrorum:"}, {"st": "4.169", "t": "merce peregrina fortunam ferre per urbes"}, {"st": "4.170", "t": "et gravia annonae speculantem incendia ventis"}, {"st": "4.171", "t": "credere opes orbisque orbi bona vendere posse"}, {"st": "4.172", "t": "totque per ignotas commercia iungere terras 170"}, {"st": "4.173", "t": "atque alio sub sole novas exquirere praedas"}, {"st": "4.174", "t": "et rerum pretio subitos componere census."}, {"st": "4.175", "t": "ignava et, celeris optando sortibus annos,"}, {"st": "4.176", "t": "dulcibus usuris aequo Iove tempora vendit."}, {"st": "4.177", "t": "ingenium sollers suaque in compendia pugnax. 175"}, {"st": "4.178", "t": "Quis dubitet, vasti quae sit natura Leonis"}, {"st": "4.179", "t": "quasque suo dictet signo nascentibus artes?"}, {"st": "4.180", "t": "ille novas semper pugnas, nova bella ferarum"}, {"st": "4.181", "t": "apparat, et spolio vivit pecorumque rapinis;"}, {"st": "4.182", "t": "hos habet hoc studium, postes ornare superbos 180"}, {"st": "4.183", "t": "pellibus et captas domibus praefigere praedas"}, {"st": "4.184", "t": "et pacare metu silvas et vivere rapto."}, {"st": "4.185", "t": "sunt quorum similis animos nec moenia frenent,"}, {"st": "4.186", "t": "sed pecudum mandris media grassentur in urbe"}, {"st": "4.187", "t": "et laceros artus suspendant fronte tabernae 185"}, {"st": "4.188", "t": "luxuriaeque parent caedem mortesque lucrentur."}, {"st": "4.189", "t": "ingenium ad subitas iras facilisque recessus"}, {"st": "4.190", "t": "aequale et puro sententia pectore simplex."}, {"st": "4.191", "t": "At quibus Erigone dixit nascentibus aevum"}, {"st": "4.192", "t": "ad studium ducet mores et pectora doctis 191"}, {"st": "4.193", "t": "artibus instituet, nec tam compendia census"}, {"st": "4.194", "t": "quam causas viresque dabit perquirere rerum."}, {"st": "4.195", "t": "illa decus linguae faciet regnumque loquendi"}, {"st": "4.196", "t": "atque oculos mentis, qui possint cernere cuncta 195"}, {"st": "4.197", "t": "quamvis occultis naturae condita causis."}, {"st": "4.198", "t": "hinc et scriptor erit velox, cui littera verbum est"}, {"st": "4.199", "t": "quique notis linguam superet cursimque loquentis"}, {"st": "4.200", "t": "excipiat longas nova per compendia voces."}, {"st": "4.201", "t": "in vitio bona sunt: teneros pudor impedit annos, 200"}, {"st": "4.202", "t": "magnaque naturae cohibendo munera frenat"}, {"st": "4.203", "t": "ora magisterio nodisque coercita Virgo. 190"}, {"st": "4.204", "t": "nec fecundus erit (quid mirum in virgine?) partus. 202"}, {"st": "4.205", "t": "Librantes noctem Chelae cum tempore lucis"}, {"st": "4.206", "t": "per nova maturi post annum munera Bacchi"}, {"st": "4.207", "t": "mensurae tribuent usus ac pondera rerum 205"}, {"st": "4.208", "t": "et Palamedeis certantem viribus ortum,"}, {"st": "4.209", "t": "qui primus numeros rebus, qui nomina summis"}, {"st": "4.210", "t": "imposuit certumque modum propriasque figuras."}, {"st": "4.211", "t": "hic etiam legum tabulas et condita iura"}, {"st": "4.212", "t": "noverit atque notis levibus pendentia verba, 210"}, {"st": "4.213", "t": "et licitum sciet, et vetitum quae poena sequatur,"}, {"st": "4.214", "t": "perpetuus populi privato in limine praetor."}, {"st": "4.215", "t": "non alio potius genitus sit Servius astro,"}, {"st": "4.216", "t": "qui leges proprias posuit, cum iura retexit."}, {"st": "4.217", "t": "denique, in ambiguo fuerit quodcumque locatum 215"}, {"st": "4.218", "t": "et rectoris egens, diriment examina Librae."}, {"st": "4.219", "t": "Scorpios armata violenta cuspide cauda,"}, {"st": "4.220", "t": "qua, sua cum Phoebi currum per sidera ducit,"}, {"st": "4.221", "t": "rimatur terras et sulcis semina miscet,"}, {"st": "4.222", "t": "in bellum ardentis animos et Martia castra 220"}, {"st": "4.223", "t": "efficit et multo gaudentem sanguine mentem"}, {"st": "4.224", "t": "nec praeda quam caede magis. quin ipsa sub armis"}, {"st": "4.225", "t": "pax agitur: capiunt saltus silvasque peragrant,"}, {"st": "4.226", "t": "nunc hominum, nunc bella gerunt violenta ferarum,"}, {"st": "4.227", "t": "nunc caput in mortem vendunt et funus harenae, 225"}, {"st": "4.228", "t": "atque hostem sibi quisque parat, cum bella quiescunt."}, {"st": "4.229", "t": "sunt quibus et simulacra placent et ludus in armis"}, {"st": "4.230", "t": "(tantus amor pugnae), discuntque per otia bellum"}, {"st": "4.231", "t": "et quodcumque pari studium producitur arte."}, {"st": "4.232", "t": "At, quibus in bifero Centauri corpore sors est 230"}, {"st": "4.233", "t": "nascendi concessa, libet subiungere currus,"}, {"st": "4.234", "t": "ardentis et equos ad mollia ducere frena"}, {"st": "4.235", "t": "et totis armenta sequi pascentia campis,"}, {"st": "4.236", "t": "quadrupedum omne genus positis domitare magistris,"}, {"st": "4.237", "t": "exorare tigres rabiemque auferre leoni 235"}, {"st": "4.238", "t": "cumque elephante loqui tantamque aptare loquendo"}, {"st": "4.239", "t": "artibus humanis varia ad spectacula molem."}, {"st": "4.240", "t": "quippe ferae mixtum est hominis per sidera corpus"}, {"st": "4.241", "t": "impositumque manet, quocirca regnat in illas."}, {"st": "4.242", "t": "quodque intenta gerit curvato spicula cornu, 240"}, {"st": "4.243", "t": "et nervos tribuit membris et acumina cordi"}, {"st": "4.244", "t": "et celeris motus nec delassabile pectus."}, {"st": "4.245", "t": "Vesta tuos, Capricorne, fovet penetralibus ignes:"}, {"st": "4.246", "t": "hinc artes studiumque trahis. nam quidquid in usus"}, {"st": "4.247", "t": "ignis eget poscitque novas ad munera flammas 245"}, {"st": "4.248", "t": "sub te censendum est. scrutari caeca metalla,"}, {"st": "4.249", "t": "depositas et opes terrarum exurere venis,"}, {"st": "4.250", "t": "materiamque manu certa duplicare erit a te,"}, {"st": "4.251", "t": "quidquid et argento fabricetur, quidquid et auro."}, {"st": "4.252", "t": "quod ferrum calidi solvant atque aera camini 250"}, {"st": "4.253", "t": "consummentque foci Cererem, tua munera surgent."}, {"st": "4.254", "t": "addis et in vestes studium mercemque fugantem"}, {"st": "4.255", "t": "frigora, brumalem servans per saecula sortem,"}, {"st": "4.256", "t": "qua retrahis ductas summa ad fastigia noctes"}, {"st": "4.257", "t": "nascentemque facis revocatis lucibus annum. 255"}, {"st": "4.258", "t": "hinc et mobilitas rerum, mutataque saepe"}, {"st": "4.259", "t": "mens natat; et 257a"}, {"st": "4.260", "t": "Veneri mixto cum crimine servit 258b"}, {"st": "4.261", "t": "pars prior, at 258a"}, {"st": "4.262", "t": "melior iuncto sub pisce senecta est. 257b"}, {"st": "4.263", "t": "Ille quoque, inflexa fontem qui proicit urna, 259"}, {"st": "4.264", "t": "cognatas tribuit iuvenalis Aquarius artes:"}, {"st": "4.265", "t": "cernere sub terris undas, inducere terris,"}, {"st": "4.266", "t": "ipsaque conversis aspergere fluctibus astra"}, {"st": "4.267", "t": "litoribusque novis per luxum illudere ponto"}, {"st": "4.268", "t": "et varios fabricare lacus et flumina ficta"}, {"st": "4.269", "t": "et peregrinantis domibus suspendere rivos. 265"}, {"st": "4.270", "t": "mille sub hoc habitant artes, quas temperat unda."}, {"st": "4.271", "t": "quippe etiam mundi faciem sedesque movebit"}, {"st": "4.272", "t": "sidereas caelumque novum versabit in orbem."}, {"st": "4.273", "t": "&lt;tempore non ullo subolem taedebit Aquari,&gt; 268a"}, {"st": "4.274", "t": "quae per aquas veniunt, operum, fontesque sequuntur."}, {"st": "4.275", "t": "mite genus dulcesque fluunt a sidere partus,"}, {"st": "4.276", "t": "pectora nec sordent; faciles in damna feruntur;"}, {"st": "4.277", "t": "nec dest nec superest census. sic profluit urna."}, {"st": "4.278", "t": "Ultima quos gemini producunt sidera Pisces,"}, {"st": "4.279", "t": "his erit in pontum studium, vitamque profundo"}, {"st": "4.280", "t": "credent et puppes aut puppibus arma parabunt, 275"}, {"st": "4.281", "t": "quidquid et in proprios pelagus desiderat usus."}, {"st": "4.282", "t": "innumerae veniunt artes: vix nomina rebus"}, {"st": "4.283", "t": "sufficiunt, tot sunt parvae quoque membra carinae."}, {"st": "4.284", "t": "adde gubernandi studium, quod venit in astra"}, {"st": "4.285", "t": "et pontum caelo vincit. bene noverit orbem 280"}, {"st": "4.286", "t": "fluminaque et portus, mundum ventosque, necesse est"}, {"st": "4.287", "t": "iamque huc atque illuc agilem convertere clavum"}, {"st": "4.288", "t": "et frenare ratem fluctusque effundere rector,"}, {"st": "4.289", "t": "iam remis agere et lentas inflectere tonsas."}, {"st": "4.290", "t": "quin placidum ductis everrere retibus aequor 285"}, {"st": "4.291", "t": "litoribusque suis populos exponere captos"}, {"st": "4.292", "t": "aut uncos celare cibis aut carcere fraudem,"}, {"st": "4.293", "t": "navalis etiam pugnas, pendentia bella,"}, {"st": "4.294", "t": "attribuunt pelagique infectos sanguine fluctus."}, {"st": "4.295", "t": "fecundum genus est natis et amica voluntas 290"}, {"st": "4.296", "t": "et celeres motus mutataque cuncta per aevum."}, {"st": "4.297", "t": "Hos tribuunt mores atque has nascentibus artes"}, {"st": "4.298", "t": "bis sex materia propria pollentia signa."}, {"st": "4.299", "t": "Sed nihil in semet totum valet: omnia vires"}, {"st": "4.300", "t": "cum certis sociant signis sub partibus aequis 295"}, {"st": "4.301", "t": "et velut hospitio mundi commercia iungunt"}, {"st": "4.302", "t": "conceduntque suas partes retinentibus astris."}, {"st": "4.303", "t": "quam partem Graiae dixere decanica gentes."}, {"st": "4.304", "t": "a numero nomen positum est, quod partibus astra"}, {"st": "4.305", "t": "condita tricenis triplici sub sorte feruntur 300"}, {"st": "4.306", "t": "et tribuunt denas in se coeuntibus astris"}, {"st": "4.307", "t": "inque vicem ternis habitantur sidera signis."}, {"st": "4.308", "t": "sic altis natura manet consaepta tenebris"}, {"st": "4.309", "t": "et verum in caeco est multaque ambagine rerum;"}, {"st": "4.310", "t": "nec brevis est usus nec amat compendia caelum, 305"}, {"st": "4.311", "t": "verum aliis alia opposita est et fallit imago"}, {"st": "4.312", "t": "mentiturque suas vires et munera celat."}, {"st": "4.313", "t": "quae tibi non oculis, alta sed mente fuganda est"}, {"st": "4.314", "t": "caligo, penitusque deus, non fronte, notandus."}, {"st": "4.315", "t": "Nunc quae sint coniuncta quibus quove ordine reddam, 310"}, {"st": "4.316", "t": "ne lateant aliae vires aliena per astra."}, {"st": "4.317", "t": "namque Aries primam partem sibi vindicat ipsi,"}, {"st": "4.318", "t": "altera sors Tauro, Geminis pars tertia cedit."}, {"st": "4.319", "t": "sidera sic inter divisum dicitur astrum"}, {"st": "4.320", "t": "totque dabit vires dominos quotcumque recepit. 315"}, {"st": "4.321", "t": "diversa in Tauro ratio est, nec parte sub ulla"}, {"st": "4.322", "t": "censetur: Cancro primam mediamque Leoni,"}, {"st": "4.323", "t": "extremam Erigonae tribuit. natura per astrum"}, {"st": "4.324", "t": "stat tamen et proprias miscet per singula vires."}, {"st": "4.325", "t": "Libra decem partes Geminorum prima capessit, 320"}, {"st": "4.326", "t": "Scorpios adiunctas; Centauri tertia pars est,"}, {"st": "4.327", "t": "nec quicquam numero discernitur, ordine cedit."}, {"st": "4.328", "t": "Cancer in adversum Capricorni derigit astrum"}, {"st": "4.329", "t": "bis quinas primum partes, dignatus in illo"}, {"st": "4.330", "t": "temporis articulo sub quo censetur et ipse, 325"}, {"st": "4.331", "t": "quod facit aequalis luces brumalibus umbris"}, {"st": "4.332", "t": "cognatamque gerit diverso in cardine legem;"}, {"st": "4.333", "t": "alterius partis perfundit Aquarius ignes,"}, {"st": "4.334", "t": "quem subeunt Pisces extremo sidere Cancri."}, {"st": "4.335", "t": "at Leo consortis meminit sub lege trigoni 330"}, {"st": "4.336", "t": "Lanigerumque ducem recipit Taurumque quadrato"}, {"st": "4.337", "t": "coniunctum sibi; sub Geminis pars tertia fertur:"}, {"st": "4.338", "t": "hos quoque contingit per senos linea flexus."}, {"st": "4.339", "t": "praecipuum Erigone Cancro concedit honorem"}, {"st": "4.340", "t": "cui primam tribuit partem; vicina relicta est 335"}, {"st": "4.341", "t": "vicino, Nemeaee, tibi; pars ipsius una est"}, {"st": "4.342", "t": "quae fastidito concessa est iure potiri."}, {"st": "4.343", "t": "sed Libra exemplo gaudet, pariterque regentem"}, {"st": "4.344", "t": "noctes atque dies diverso in tempore secum"}, {"st": "4.345", "t": "Lanigerum sequitur: veris iuga temperat ille, 340"}, {"st": "4.346", "t": "haec autumnalis componit lucibus umbras:"}, {"st": "4.347", "t": "nulli concedit primam, traditque sequenti"}, {"st": "4.348", "t": "vicinam partem; Centauri tertia summa est."}, {"st": "4.349", "t": "Scorpios in prima Capricornum parte locavit,"}, {"st": "4.350", "t": "alterius dominum fecit cui nomen ab undis, 345"}, {"st": "4.351", "t": "extremas voluit partes sub Piscibus esse."}, {"st": "4.352", "t": "at qui contento minitatur spicula nervo"}, {"st": "4.353", "t": "Lanigero primas tradit sub iure trigoni"}, {"st": "4.354", "t": "et medias Tauro partes Geminisque supremas."}, {"st": "4.355", "t": "nec manet ingrati Capricornus crimine turpis 350"}, {"st": "4.356", "t": "sed munus reddit Cancro recipitque receptus"}, {"st": "4.357", "t": "principiumque sui donat; coniuncta Leonis"}, {"st": "4.358", "t": "regna ferunt, summas partes et Virginis esse."}, {"st": "4.359", "t": "fontibus aeternis gaudens urnaque fluenti"}, {"st": "4.360", "t": "iura sui Librae permittit prima regenda, 355"}, {"st": "4.361", "t": "haerentisque decem partes Nepa vindicat ipsi;"}, {"st": "4.362", "t": "summas Centaurus retinet iuvenale per astrum."}, {"st": "4.363", "t": "iam superant gemini Pisces, qui sidera claudunt."}, {"st": "4.364", "t": "Lanigero primos tradunt in finibus usus,"}, {"st": "4.365", "t": "perque decem medias partes tu, Taure, receptus; 360"}, {"st": "4.366", "t": "quod superest, ipsi sumunt, utque orbe feruntur"}, {"st": "4.367", "t": "extremo sic et sortis pars ultima cedit."}, {"st": "4.368", "t": "Haec ratio retegit latitantis robora mundi"}, {"st": "4.369", "t": "in plurisque modos repetitaque nomina caelum"}, {"st": "4.370", "t": "dividit et melius sociat, quo saepius, orbem. 365"}, {"st": "4.371", "t": "nec tua sub titulis fallantur pectora notis:"}, {"st": "4.372", "t": "dissimulant, non ostendunt mortalibus astra."}, {"st": "4.373", "t": "altius est acies animi mittenda sagacis"}, {"st": "4.374", "t": "inque alio quaerendum aliud iunctisque sequendum"}, {"st": "4.375", "t": "viribus; et, cuius signi quis parte creatur, 370"}, {"st": "4.376", "t": "eius habet mores atque illo nascitur astro."}, {"st": "4.377", "t": "talis per denas sortes natura feretur."}, {"st": "4.378", "t": "testis erit varius sub eodem sidere fetus,"}, {"st": "4.379", "t": "quodque in tam multis animantum milibus, uno"}, {"st": "4.380", "t": "quae veniunt signo, tot sunt, quot corpora, mores, 375"}, {"st": "4.381", "t": "et genus externum referunt aliena per astra,"}, {"st": "4.382", "t": "confusique fluunt partus hominum atque ferarum."}, {"st": "4.383", "t": "scilicet in partes iunguntur condita pluris"}, {"st": "4.384", "t": "diversasque ferunt proprio sub nomine leges."}, {"st": "4.385", "t": "nec tantum lanas Aries nec Taurus aratra 380"}, {"st": "4.386", "t": "nec Gemini Musas nec merces Cancer amabit,"}, {"st": "4.387", "t": "nec Leo venator veniet nec Virgo magistra,"}, {"st": "4.388", "t": "mensuris aut Libra potens aut Scorpios armis"}, {"st": "4.389", "t": "Centaurusque feris, igni Capricornus et undis"}, {"st": "4.390", "t": "ipse suis Iuvenis geminique per aequora Pisces; 385"}, {"st": "4.391", "t": "mixta sed in pluris sociantur sidera vires."}, {"st": "4.392", "t": "'Multum' inquis 'tenuemque iubes me ferre laborem,"}, {"st": "4.393", "t": "rursus et in magna mergis caligine mentem,"}, {"st": "4.394", "t": "cernere cum facili lucem ratione viderer.'"}, {"st": "4.395", "t": "quod quaeris, deus est: conaris scandere caelum 390"}, {"st": "4.396", "t": "fataque fatali genitus cognoscere lege"}, {"st": "4.397", "t": "et transire tuum pectus mundoque potiri."}, {"st": "4.398", "t": "pro pretio labor est nec sunt immunia tanta,"}, {"st": "4.399", "t": "ne mirere viae flexus rerumque catenas."}, {"st": "4.400", "t": "admitti potuisse sat est: sint cetera nostra. 395"}, {"st": "4.401", "t": "at nisi perfossis fugiet te montibus aurum,"}, {"st": "4.402", "t": "obstabitque suis opibus super addita tellus."}, {"st": "4.403", "t": "ut veniant gemmae, totus transibitur orbis,"}, {"st": "4.404", "t": "nec lapidum pretio pelagus cepisse pigebit."}, {"st": "4.405", "t": "annua solliciti consument vota coloni, 400"}, {"st": "4.406", "t": "et quantae mercedis erunt fallacia rura!"}, {"st": "4.407", "t": "quaeremus lucrum ventis Martemque sequemur"}, {"st": "4.408", "t": "in praedas. pudeat tanto bona velle caduca."}, {"st": "4.409", "t": "luxuriae quoque militia est, vigilatque ruinis"}, {"st": "4.410", "t": "venter, et, ut pereant, suspirant saepe nepotes. 405"}, {"st": "4.411", "t": "quid caelo dabimus? quantum est, quo veneat omne?"}, {"st": "4.412", "t": "impendendus homo est, deus esse ut possit in ipso."}, {"st": "4.413", "t": "Hac tibi nascentum mores sunt lege notandi."}, {"st": "4.414", "t": "nec satis est signis dominantia discere signa"}, {"st": "4.415", "t": "per denos numeros et quae sint insita cuique; 410"}, {"st": "4.416", "t": "sed proprias partes ipsas spectare memento"}, {"st": "4.417", "t": "vel glacie rigidas vel quas exusserit ignis,"}, {"st": "4.418", "t": "et sterilis &lt;sine&gt; utroque tamen, quas largior umor"}, {"st": "4.419", "t": "quasve minor iusto vitiat. namque omnia mixtis"}, {"st": "4.420", "t": "viribus et vario consurgunt sidera textu. 415"}, {"st": "4.421", "t": "est aequale nihil. terrenos aspice tractus"}, {"st": "4.422", "t": "et maris et variis fugientia flumina ripis:"}, {"st": "4.423", "t": "crimen ubique frequens et laudi noxia iuncta est."}, {"st": "4.424", "t": "sic sterilis tellus laetis intervenit arvis"}, {"st": "4.425", "t": "ac subito rumpit parvo discrimine foedus; 420"}, {"st": "4.426", "t": "et modo portus erat pelagi iam vasta charybdis,"}, {"st": "4.427", "t": "laudatique cadit post paulum gratia ponti;"}, {"st": "4.428", "t": "et nunc per scopulos, nunc campis labitur amnis,"}, {"st": "4.429", "t": "et, faciens iter aut quaerens, curritve reditve."}, {"st": "4.430", "t": "sic etiam caeli partes variantur in astris: 425"}, {"st": "4.431", "t": "ut signum signo, sic a se discrepat ipsum"}, {"st": "4.432", "t": "momentoque negat vires usumque salubrem,"}, {"st": "4.433", "t": "quodque per has geritur partes sine fruge creatur"}, {"st": "4.434", "t": "aut cadit aut multis sentit bona mixta querellis."}, {"st": "4.435", "t": "hae mihi signandae proprio sunt carmine partes. 430"}, {"st": "4.436", "t": "sed quis tot numeros totiens sub lege referre,"}, {"st": "4.437", "t": "tot partes iterare queat, tot dicere summas,"}, {"st": "4.438", "t": "perque paris causas faciem mutare loquendi?"}, {"st": "4.439", "t": "&lt;dum canimus verum, non aspera ponere, ut illis&gt; 433a"}, {"st": "4.440", "t": "incidimus, sic verba piget; sed gratia derit,"}, {"st": "4.441", "t": "in vanumque labor cedit quem despicit auris."}, {"st": "4.442", "t": "sed mihi per carmen fatalia iura ferenti"}, {"st": "4.443", "t": "et sacros caeli motus ad iussa loquendum est,"}, {"st": "4.444", "t": "nec fingenda datur, tantum monstranda figura."}, {"st": "4.445", "t": "ostendisse deum nimis est: dabit ipse sibimet"}, {"st": "4.446", "t": "pondera. nec fas est verbis splendescere mundum: 440"}, {"st": "4.447", "t": "rebus erit maior. nec parva est gratia nostri"}, {"st": "4.448", "t": "oris, si tantum poterit signare canenda."}, {"st": "4.449", "t": "accipe damnandae quae sint per sidera partes."}, {"st": "4.450", "t": "Lanigeri pars quarta nocet nec sexta salubris;"}, {"st": "4.451", "t": "septima par illi ac decima est decimaeque secunda 445"}, {"st": "4.452", "t": "quaeque duas duplicant summas septemque novemque;"}, {"st": "4.453", "t": "unaque viginti numeris pars addita laedit"}, {"st": "4.454", "t": "et quinta et duram consummans septima partem."}, {"st": "4.455", "t": "Tauri nona mala est, similis cui tertia pars est"}, {"st": "4.456", "t": "post decimam nec non decimae pars septima iuncta; 450"}, {"st": "4.457", "t": "bisque undena notans et bis duodena nocentes"}, {"st": "4.458", "t": "quaeque decem trisque ingeminat fraudatque duobus"}, {"st": "4.459", "t": "triginta numeros et tu, tricesima summa, es."}, {"st": "4.460", "t": "Pestifera in Geminis pars prima et tertia signi,"}, {"st": "4.461", "t": "septima non melior, ter quintae noxia par est, 455"}, {"st": "4.462", "t": "unaque bis denis brevior nocet unaque maior,"}, {"st": "4.463", "t": "et similis noxae veniet vicesima quinta"}, {"st": "4.464", "t": "cumque duae subeunt vel cum se quattuor addunt."}, {"st": "4.465", "t": "Nec Cancri prima immunis nec tertia pars est"}, {"st": "4.466", "t": "nec sexta; octava est similis, decimaque peracta 460"}, {"st": "4.467", "t": "prima rapit, nec ter quintae clementior usus;"}, {"st": "4.468", "t": "septima post decimam luctum et vicesima portat"}, {"st": "4.469", "t": "et quinta accedens et septima nonaque summa."}, {"st": "4.470", "t": "Tu quoque contactu primo, Nemeaee, timendus,"}, {"st": "4.471", "t": "et quarta sub parte premis; bis quinta salubri 465"}, {"st": "4.472", "t": "terque caret caelo, vicesima et altera laedit;"}, {"st": "4.473", "t": "e tribus appositis vitiat totidemque secutis"}, {"st": "4.474", "t": "ultima, nec prima melior tricesima pars est."}, {"st": "4.475", "t": "Erigones nec pars prima est nec sexta nec una"}, {"st": "4.476", "t": "ad decimam nec quarta nec octava utilis umquam; 470"}, {"st": "4.477", "t": "proxima viginti numeris et quarta timenda est,"}, {"st": "4.478", "t": "et quae ter decimam claudit sors ultima partem."}, {"st": "4.479", "t": "Et quinta in Chelis et septima inutilis astri,"}, {"st": "4.480", "t": "tertia et undecimae decimaeque est septima iuncta"}, {"st": "4.481", "t": "quartaque bis denis actis et septima et ambae 475"}, {"st": "4.482", "t": "quae numerum claudunt nona et tricesima partes."}, {"st": "4.483", "t": "Scorpios in prima reus est, cui tertia par est"}, {"st": "4.484", "t": "et sexta et decima et quae ter tibi quinta notatur,"}, {"st": "4.485", "t": "undecimam geminans et quae vicesima quinta est"}, {"st": "4.486", "t": "octavoque manet numero nonumque capessit. 480"}, {"st": "4.487", "t": "Si te fata sinant, quartam ne selige partem"}, {"st": "4.488", "t": "Centauri; fuge et octavam; sex bisve peractis"}, {"st": "4.489", "t": "octo, bis aut denis, metuendus dicitur aer,"}, {"st": "4.490", "t": "cumque iterum duodena refert aut terna decemque"}, {"st": "4.491", "t": "aut septena quater, vel cum ter dena figurat. 485"}, {"st": "4.492", "t": "Nec pars optanda est Capricorni septima; nona"}, {"st": "4.493", "t": "consentit decimamque sequens quam tertia signat"}, {"st": "4.494", "t": "et tribus aut una quae te, vicesima, fraudat"}, {"st": "4.495", "t": "quaeve auget quinto numero vel septima fertur."}, {"st": "4.496", "t": "Pars est prima nocens fundentis semper Aquari, 489a"}, {"st": "4.497", "t": "damnanda et decimae succedens prima peractae"}, {"st": "4.498", "t": "tertiaque et quinta et numero quae condita nono est"}, {"st": "4.499", "t": "et post viginti prima et vicesima quinta"}, {"st": "4.500", "t": "cumque illa quartam accumulans vicesima nona."}, {"st": "4.501", "t": "Tertia per geminos et quinta et septima Pisces,"}, {"st": "4.502", "t": "undecima et decimae metuenda est septima iuncta; 495"}, {"st": "4.503", "t": "et quinta in quinos numeros revocata duasque"}, {"st": "4.504", "t": "accipiens ultra summas metuenda feretur."}, {"st": "4.505", "t": "Hae partes sterilem ducunt et frigore et igni"}, {"st": "4.506", "t": "aera vel sicco vel quod superaverit umor,"}, {"st": "4.507", "t": "si rapidus Mavors ignes iaculatur in illum 500"}, {"st": "4.508", "t": "Saturnusve suam glaciem &lt;Phoebeve propinquis"}, {"st": "4.509", "t": "quem trahit a terris rorem&gt; Phoebusve calores. 501a"}, {"st": "4.510", "t": "Nec te perceptis signorum cura relinquat"}, {"st": "4.511", "t": "partibus: in tempus quaedam mutantur, et ortu"}, {"st": "4.512", "t": "accipiunt proprias vires ultraque remittunt."}, {"st": "4.513", "t": "Namque, ubi se summis Aries extollet ab undis 505"}, {"st": "4.514", "t": "et cervice prior flexa quam cornibus ibit,"}, {"st": "4.515", "t": "non contenta suo generabit pectora censu"}, {"st": "4.516", "t": "et dabit in praedas animos solvetque pudorem:"}, {"st": "4.517", "t": "tantum audere iuvat. sic ipse in cornua fertur"}, {"st": "4.518", "t": "ut ruat aut vincat. non illos sedibus isdem 510"}, {"st": "4.519", "t": "mollia per placidas delectant otia curas,"}, {"st": "4.520", "t": "sed iuvat ignotas semper transire per urbes"}, {"st": "4.521", "t": "scrutarique novum pelagus totius et esse"}, {"st": "4.522", "t": "orbis in hospitio. testis tibi Laniger ipse,"}, {"st": "4.523", "t": "cum vitreum findens auravit vellere pontum 515"}, {"st": "4.524", "t": "orbatumque sua Phrixum per fata sorore"}, {"st": "4.525", "t": "Phasidos ad ripas et Colchida tergore vexit."}, {"st": "4.526", "t": "At, quos prima creant nascentis sidera Tauri,"}, {"st": "4.527", "t": "feminei incedunt. nec longe causa petenda est,"}, {"st": "4.528", "t": "si modo per causas naturam quaerere fas est: 520"}, {"st": "4.529", "t": "aversus venit in caelum divesque puellis,"}, {"st": "4.530", "t": "Pleiadum parvo referens glomeramine sidus."}, {"st": "4.531", "t": "accedunt et ruris opes, propriaque iuvencum"}, {"st": "4.532", "t": "dote per inversos exornat vomere campos."}, {"st": "4.533", "t": "Sed, Geminos aequa cum profert unda tegitque 525"}, {"st": "4.534", "t": "parte, dabit studia et doctas producet ad artes."}, {"st": "4.535", "t": "nec triste ingenium sed dulci tincta lepore"}, {"st": "4.536", "t": "corda creat, vocisque bonis citharaeque sonantis"}, {"st": "4.537", "t": "instruit, et dotes cantus cum pectore iungit."}, {"st": "4.538", "t": "At, niger obscura Cancer cum nube feretur, 530"}, {"st": "4.539", "t": "qua velut exustus Phoebeis ignibus ignis"}, {"st": "4.540", "t": "deficit et multa fuscat caligine sidus,"}, {"st": "4.541", "t": "lumina deficient partus, geminamque creatis"}, {"st": "4.542", "t": "mortem fata dabunt: se quisque et vivit et effert."}, {"st": "4.543", "t": "Sicui per summas avidus produxerit undas 535"}, {"st": "4.544", "t": "ora Leo et scandat malis hiscentibus orbem,"}, {"st": "4.545", "t": "ille patri natisque reus, quas ceperit ipse,"}, {"st": "4.546", "t": "non legabit opes, censumque immerget in ipso."}, {"st": "4.547", "t": "tanta fames animumque cibi tam dira cupido"}, {"st": "4.548", "t": "corripit, ut capiat semet nec compleat umquam, 540"}, {"st": "4.549", "t": "inque epulas funus revocet pretiumque sepulcri."}, {"st": "4.550", "t": "Erigone surgens, quae rexit saecula prisca"}, {"st": "4.551", "t": "iustitia rursusque eadem labentia fugit,"}, {"st": "4.552", "t": "alta per imperium tribuit fastigia summum,"}, {"st": "4.553", "t": "rectoremque dabit legum iurisque sacrati 545"}, {"st": "4.554", "t": "sancta pudicitia divorum templa colentem."}, {"st": "4.555", "t": "Sed, cum autumnales coeperunt surgere Chelae,"}, {"st": "4.556", "t": "felix aequato genitus sub pondere Librae."}, {"st": "4.557", "t": "iudex examen sistet vitaeque necisque"}, {"st": "4.558", "t": "imponetque iugum terris legesque rogabit. 550"}, {"st": "4.559", "t": "illum urbes et regna trement nutuque regentur"}, {"st": "4.560", "t": "unius et caeli post terras iura manebunt."}, {"st": "4.561", "t": "Scorpios extremae cum tollet lumina caudae,"}, {"st": "4.562", "t": "siquis erit stellis tunc suffragantibus ortus,"}, {"st": "4.563", "t": "urbibus augebit terras iunctisque iuvencis 555"}, {"st": "4.564", "t": "moenia succinctus curvo describet aratro,"}, {"st": "4.565", "t": "aut sternet positas urbes inque arva reducet"}, {"st": "4.566", "t": "oppida et in domibus maturas reddet aristas."}, {"st": "4.567", "t": "tanta erit et virtus et cum virtute potestas."}, {"st": "4.568", "t": "Nec non Arcitenens, prima cum veste resurgit, 560"}, {"st": "4.569", "t": "pectora clara dabit bello, magnisque triumphis"}, {"st": "4.570", "t": "conspicuum patrias victorem ducet ad arces,"}, {"st": "4.571", "t": "altaque nunc statuet nunc idem moenia vertet."}, {"st": "4.572", "t": "sed nimium indulgens rebus Fortuna secundis"}, {"st": "4.573", "t": "invidet in facie saevitque asperrima fronti. 565"}, {"st": "4.574", "t": "horrendus bello Trebiam Cannasque lacumque"}, {"st": "4.575", "t": "ante fugam tali pensabat imagine victor."}, {"st": "4.576", "t": "Ultimus in caudae Capricornus acumine summo"}, {"st": "4.577", "t": "militiam in ponto dictat puppisque colendae"}, {"st": "4.578", "t": "dura ministeria et tenui discrimine mortis. 570"}, {"st": "4.579", "t": "Quod si quem sanctumque velis castumque probumque"}, {"st": "4.580", "t": "hic tibi nascetur cum primus Aquarius exit."}, {"st": "4.581", "t": "Ne velit et primos animus procedere Pisces,"}, {"st": "4.582", "t": "garrulitas odiosa datur linguaeque venenum"}, {"st": "4.583", "t": "verba maligna novas mutantis semper ad aures 575"}, {"st": "4.584", "t": "criminaque ad populum populi ferre ore bilingui."}, {"st": "4.585", "t": "nulla fides inerit natis, sed summa libido"}, {"st": "4.586", "t": "ardentem medios animum iubet ire per ignes."}, {"st": "4.587", "t": "scilicet in piscem sese Cytherea novavit,"}, {"st": "4.588", "t": "cum Babyloniacas summersa profugit in undas 580"}, {"st": "4.589", "t": "anguipedem alatos umeros Typhona ferentem,"}, {"st": "4.590", "t": "inseruitque suos squamosis Piscibus ignes."}, {"st": "4.591", "t": "nec solus fuerit geminis sub Piscibus ortus:"}, {"st": "4.592", "t": "frater erit dulcisve soror, materve duorum."}, {"st": "4.593", "t": "Nunc age diversis dominantia sidera terris 585"}, {"st": "4.594", "t": "percipe. sed summa est rerum referenda figura."}, {"st": "4.595", "t": "quattuor in partes caeli discribitur orbis,"}, {"st": "4.596", "t": "nascentem lapsumque diem mediosque calores"}, {"st": "4.597", "t": "teque, Helice. totidem venti de partibus isdem"}, {"st": "4.598", "t": "erumpunt secumque gerunt per inania bella. 590"}, {"st": "4.599", "t": "asper ab axe ruit Boreas, fugit Eurus ab ortu,"}, {"st": "4.600", "t": "Auster amat medium solem Zephyrusque profectum."}, {"st": "4.601", "t": "hos inter binae mediis e partibus aurae"}, {"st": "4.602", "t": "exspirant similis mutato nomine flatus."}, {"st": "4.603", "t": "ipsa natat tellus pelagi lustrata corona 595"}, {"st": "4.604", "t": "cingentis medium liquidis amplexibus orbem,"}, {"st": "4.605", "t": "inque sinus pontum recipit, qui vespere ab atro"}, {"st": "4.606", "t": "admissus dextra Numidas Libyamque calentem"}, {"st": "4.607", "t": "alluit et magnae quondam Carthaginis arces,"}, {"st": "4.608", "t": "litoraque in Syrtes revocans sinuata vadosas 600"}, {"st": "4.609", "t": "rursum usque ad Nilum derectis fluctibus exit."}, {"st": "4.610", "t": "laeva freti caedunt Hispanas aequora gentes"}, {"st": "4.611", "t": "teque in vicinis haerentem, Gallia, terris"}, {"st": "4.612", "t": "Italiaeque urbes dextram sinuantis in undam"}, {"st": "4.613", "t": "usque canes ad, Scylla, tuos avidamque Charybdin. 605"}, {"st": "4.614", "t": "hac ubi se primum porta mare fudit, &lt;aperto&gt;"}, {"st": "4.615", "t": "enatat Ionio laxasque vagatur in undas"}, {"st": "4.616", "t": "et, prius ut, laeva se fundens circuit omnem"}, {"st": "4.617", "t": "Italiam, Hadriaco mutatum nomina ponto,"}, {"st": "4.618", "t": "Eridanique bibit fluctus, vetat aequore bellum 610"}, {"st": "4.619", "t": "Illyricum, Epirumque lavat claramque Corinthum"}, {"st": "4.620", "t": "et Peloponnesi patulas circumvolat oras;"}, {"st": "4.621", "t": "rursus et in laevum refluit vastoque recessu"}, {"st": "4.622", "t": "Thessaliae fines et Achaica praeterit arva."}, {"st": "4.623", "t": "hinc penitus iuvenisque freto mersaeque puellae 615"}, {"st": "4.624", "t": "truditur invitum, faucesque Propontis aperto"}, {"st": "4.625", "t": "Euxino iniungit ponto Maeotis et undis,"}, {"st": "4.626", "t": "quae tergo coniuncta manet fontemque ministrat."}, {"st": "4.627", "t": "inde ubi in angustas revocatus navita fauces"}, {"st": "4.628", "t": "Hellespontiacis iterum se fluctibus effert, 620"}, {"st": "4.629", "t": "Icarium Aegaeumque secat laevaque nitentis"}, {"st": "4.630", "t": "miratur populos Asiae totidemque tropaea"}, {"st": "4.631", "t": "quot loca et innumeras gentes Taurumque minantem"}, {"st": "4.632", "t": "fluctibus et Cilicum populos Syriamque perustam"}, {"st": "4.633", "t": "ingentique sinu fugientis aequora terras, 625"}, {"st": "4.634", "t": "donec in Aegyptum redeunt curvata per undas"}, {"st": "4.635", "t": "litora Niliacis iterum morientia ripis."}, {"st": "4.636", "t": "haec medium terris circumdat linea pontum"}, {"st": "4.637", "t": "atque his undarum tractum constringit harenis."}, {"st": "4.638", "t": "mille iacent mediae diffusa per aequora terrae. 630"}, {"st": "4.639", "t": "Sardiniam in Libyco signant vestigia plantae,"}, {"st": "4.640", "t": "Trinacria Italia tantum praecisa recessit,"}, {"st": "4.641", "t": "adversa Euboicos miratur Graecia montes,"}, {"st": "4.642", "t": "Aegaeis Crete civem sortita Tonantem"}, {"st": "4.643", "t": "Aegyptique Cypros pulsatur fluctibus amnis. 635"}, {"st": "4.644", "t": "&lt;has praeter terras, celebrat quas maxima fama,&gt; 635a"}, {"st": "4.645", "t": "totque minore solo tamen emergentia ponto"}, {"st": "4.646", "t": "litora, inaequalis Cycladas Delonque Rhodonque"}, {"st": "4.647", "t": "Aulidaque et Tenedon vicinaque Corsica terris"}, {"st": "4.648", "t": "litora Sardiniae primumque intrantis in orbem"}, {"st": "4.649", "t": "Oceani victricem Ebusum et Balearica rura, 640"}, {"st": "4.650", "t": "innumeri surgunt scopuli montesque per altum."}, {"st": "4.651", "t": "Nec tantum ex una pontus sibi parte reclusit"}, {"st": "4.652", "t": "faucibus abruptis orbem; nam litora plura"}, {"st": "4.653", "t": "impulit oceano Phorcys, sed montibus altis"}, {"st": "4.654", "t": "est vetitus totam ne vinceret aequore terram. 645"}, {"st": "4.655", "t": "namque inter borean ortumque aestate nitentem"}, {"st": "4.656", "t": "in longum angusto penetrabilis aequore fluctus"}, {"st": "4.657", "t": "pervenit et patulis tum demum funditur arvis"}, {"st": "4.658", "t": "Caspiaque Euxini similis facit aequora ponti."}, {"st": "4.659", "t": "altera sub medium solem duo bella perinde 650"}, {"st": "4.660", "t": "intulit Oceanus terris. nam Persica fluctus"}, {"st": "4.661", "t": "arva tenet, titulum pelagi praedatus ab isdem"}, {"st": "4.662", "t": "quae rigat ipse locis, latoque infunditur orbe."}, {"st": "4.663", "t": "nec procul in mollis Arabas terramque ferentem"}, {"st": "4.664", "t": "delicias variaeque novos radicis odores 655"}, {"st": "4.665", "t": "leniter affundit gemmantia litora pontus,"}, {"st": "4.666", "t": "et terrae mare nomen habet. media illa duobus"}, {"st": "4.667", "t": "* 657a"}, {"st": "4.668", "t": "quondam Carthago regnum sortita sub armis,"}, {"st": "4.669", "t": "ignibus Alpinas cum contudit Hannibal arces,"}, {"st": "4.670", "t": "fecit et aeternum Trebiam Cannasque sepulcris 660"}, {"st": "4.671", "t": "obruit et Libyam Latias infudit in urbes."}, {"st": "4.672", "t": "huc varias pestes diversaque monstra ferarum"}, {"st": "4.673", "t": "congessit bellis natura infesta futuris."}, {"st": "4.674", "t": "horrendos angues habitataque membra veneno"}, {"st": "4.675", "t": "et mortis pastu viventia, crimina terrae, 665"}, {"st": "4.676", "t": "et vastos elephantas habet, saevosque leones"}, {"st": "4.677", "t": "in poenas fecunda suas parit horrida tellus"}, {"st": "4.678", "t": "et portentosos cercopum ludit in ortus"}, {"st": "4.679", "t": "ac sterili peior siccas infestat harenas,"}, {"st": "4.680", "t": "donec ad Aegypti ponat sua iura colonos. 670"}, {"st": "4.681", "t": "inde Asiae populi divesque per omnia tellus:"}, {"st": "4.682", "t": "auratique fluunt amnes gemmisque relucet"}, {"st": "4.683", "t": "pontus, odoratae spirant medicamina silvae:"}, {"st": "4.684", "t": "India notitia maior, Parthique vel orbis"}, {"st": "4.685", "t": "alter, et in caelum surgentis moenia Tauri 675"}, {"st": "4.686", "t": "totque illum circa diverso nomine gentes"}, {"st": "4.687", "t": "ad Tanain Scythicis dirimentem fluctibus orbes"}, {"st": "4.688", "t": "Maeotisque lacus Euxinique aspera ponti."}, {"st": "4.689", "t": "[aequora et extremum Propontidos Hellespontum]"}, {"st": "4.690", "t": "hanc Asiae metam posuit natura potentis. 680"}, {"st": "4.691", "t": "quod superest Europa tenet, quae prima natantem"}, {"st": "4.692", "t": "fluctibus excepitque Iovem taurumque resolvit,"}, {"st": "4.693", "t": "ponere passa suos ignes, onerique iugavit."}, {"st": "4.694", "t": "ille puellari donavit nomine litus"}, {"st": "4.695", "t": "et monumenta sui titulo sacravit amoris. 685"}, {"st": "4.696", "t": "maxima terra viris et fecundissima doctis"}, {"st": "4.697", "t": "artibus: in regnum florentes oris Athenae;"}, {"st": "4.698", "t": "Sparta manu, Thebae divis, et rege vel uno"}, {"st": "4.699", "t": "princeps Pella domus, Troiani gratia belli;"}, {"st": "4.700", "t": "Thessalia Epirosque potens vicinaque ripa 690"}, {"st": "4.701", "t": "Illyris, et Thrace Martem sortita colonum,"}, {"st": "4.702", "t": "et stupefacta suos inter Germania partus;"}, {"st": "4.703", "t": "Gallia per census, Hispania maxima bellis;"}, {"st": "4.704", "t": "Italia in summa, quam rerum maxima Roma"}, {"st": "4.705", "t": "imposuit terris caeloque adiungitur ipsa. 695"}, {"st": "4.706", "t": "Hos erit in fines orbis pontusque vocandus,"}, {"st": "4.707", "t": "quem deus in partes per singula dividit astra"}, {"st": "4.708", "t": "ac sua cuique dedit tutelae regna per orbem"}, {"st": "4.709", "t": "et proprias gentes atque urbes addidit altas,"}, {"st": "4.710", "t": "in quibus assererent praestantis sidera vires. 700"}, {"st": "4.711", "t": "ac, velut humana est signis discripta figura,"}, {"st": "4.712", "t": "et, quamquam communis eat tutela per omne"}, {"st": "4.713", "t": "corpus, et in proprium divisis artubus exit"}, {"st": "4.714", "t": "(namque Aries capiti, Taurus cervicibus haeret,"}, {"st": "4.715", "t": "bracchia sub Geminis censentur, pectora Cancro, 705"}, {"st": "4.716", "t": "te scapulae, Nemeaee, vocant teque ilia, Virgo,"}, {"st": "4.717", "t": "Libra colit clunes et Scorpios inguine regnat,"}, {"st": "4.718", "t": "et femina Arcitenens, genua et Capricornus amavit,"}, {"st": "4.719", "t": "cruraque defendit Iuvenis, vestigia Pisces),"}, {"st": "4.720", "t": "sic alias aliud terras sibi vindicat astrum. 710"}, {"st": "4.721", "t": "Idcirco in varias leges variasque figuras"}, {"st": "4.722", "t": "dispositum genus est hominum, proprioque colore"}, {"st": "4.723", "t": "formantur gentes, sociataque iura per artus"}, {"st": "4.724", "t": "materiamque parem privato foedere signant."}, {"st": "4.725", "t": "flava per ingentis surgit Germania partus, 715"}, {"st": "4.726", "t": "Gallia vicino minus est infecta rubore,"}, {"st": "4.727", "t": "asperior solidos Hispania contrahit artus."}, {"st": "4.728", "t": "Martia Romanis urbis pater induit ora"}, {"st": "4.729", "t": "Gradivumque Venus miscens bene temperat artus,"}, {"st": "4.730", "t": "perque coloratas subtilis Graecia gentes 720"}, {"st": "4.731", "t": "gymnasium praefert vultu fortisque palaestras,"}, {"st": "4.732", "t": "et Syriam produnt torti per tempora crines."}, {"st": "4.733", "t": "Aethiopes maculant orbem tenebrisque figurant"}, {"st": "4.734", "t": "perfusas hominum gentes; minus India tostos"}, {"st": "4.735", "t": "progenerat; 725a"}, {"st": "4.736", "t": "tellusque natans Aegyptia Nilo 726b"}, {"st": "4.737", "t": "lenius irriguis infuscat corpora campis"}, {"st": "4.738", "t": "iam propior 726a"}, {"st": "4.739", "t": "mediumque facit moderata tenorem. 725b"}, {"st": "4.740", "t": "Phoebus harenosis Afrorum pulvere terris 728"}, {"st": "4.741", "t": "exsiccat populos, et Mauretania nomen"}, {"st": "4.742", "t": "oris habet titulumque suo fert ipsa colore."}, {"st": "4.743", "t": "adde sonos totidem vocum, totidem insere linguas"}, {"st": "4.744", "t": "et mores pro sorte paris ritusque locorum;"}, {"st": "4.745", "t": "adde genus proprium simili sub semine frugum"}, {"st": "4.746", "t": "et Cererem varia redeuntem messe per urbes"}, {"st": "4.747", "t": "nec paribus siliquas referentem viribus omnis, 735"}, {"st": "4.748", "t": "nec te, Bacche, pari donantem munere terras"}, {"st": "4.749", "t": "atque alias aliis fundentem collibus uvas,"}, {"st": "4.750", "t": "cinnama nec totis passim nascentia campis;"}, {"st": "4.751", "t": "diversas pecudum facies propriasque ferarum"}, {"st": "4.752", "t": "et duplici clausos elephantas carcere terrae. 740"}, {"st": "4.753", "t": "quot partes orbis, totidem sub partibus orbes,"}, {"st": "4.754", "t": "ut certis discripta nitent regionibus astra"}, {"st": "4.755", "t": "perfunduntque suo subiectas aere gentes."}, {"st": "4.756", "t": "Laniger in medio sortitus sidera mundo,"}, {"st": "4.757", "t": "&lt;lance ubi sol aequa pensat noctemque diemque&gt; 744a"}, {"st": "4.758", "t": "Cancrum inter gelidumque &lt;Caprum&gt; per tempora veris,"}, {"st": "4.759", "t": "asserit in vires pontum quem vicerat ipse,"}, {"st": "4.760", "t": "virgine delapsa cum fratrem ad litora vexit"}, {"st": "4.761", "t": "et minui deflevit onus dorsumque levari."}, {"st": "4.762", "t": "illum etiam venerata colit vicina Propontis"}, {"st": "4.763", "t": "et Syriae gentes et laxo Persis amictu 750"}, {"st": "4.764", "t": "vestibus ipsa suis haerens Nilusque tumescens"}, {"st": "4.765", "t": "in Cancrum et tellus Aegypti iussa natare."}, {"st": "4.766", "t": "Taurus habet Scythiae montes Asiamque potentem"}, {"st": "4.767", "t": "et mollis Arabas, silvarum ditia regna."}, {"st": "4.768", "t": "Euxinus Scythicos pontus sinuatus in arcus 755"}, {"st": "4.769", "t": "sub Geminis te, Phoebe, colit; vos Thracia, fratres,"}, {"st": "4.770", "t": "ultimus et sola vos tranans colit Indica Ganges."}, {"st": "4.771", "t": "ardent Aethiopes Cancro, cui plurimus ignis:"}, {"st": "4.772", "t": "hoc color ipse docet. Phrygia, Nemeaee, potiris"}, {"st": "4.773", "t": "Idaeae matris famulus regnoque feroci 760"}, {"st": "4.774", "t": "Cappadocum Armeniaeque iugis; Bithynia dives"}, {"st": "4.775", "t": "te colit et Macetum tellus, quae vicerat orbem."}, {"st": "4.776", "t": "Virgine sub casta felix terraque marique"}, {"st": "4.777", "t": "est Rhodos, hospitium recturi principis orbem,"}, {"st": "4.778", "t": "tumque domus vere Solis, cui tota sacrata est, 765"}, {"st": "4.779", "t": "cum caperet lumen magni sub Caesare mundi;"}, {"st": "4.780", "t": "Ioniae quoque sunt urbes et Dorica rura,"}, {"st": "4.781", "t": "Arcades antiqui celebrataque Caria fama."}, {"st": "4.782", "t": "quod potius colat Italiam, si seligat, astrum"}, {"st": "4.783", "t": "quam quod cuncta regit, quod rerum pondera novit, 770"}, {"st": "4.784", "t": "designat summas et iniquum separat aequo,"}, {"st": "4.785", "t": "tempora quo pendent, coeunt quo noxque diesque?"}, {"st": "4.786", "t": "Hesperiam sua Libra tenet, qua condita Roma"}, {"st": "4.787", "t": "orbis et imperium retinet discrimina rerum,"}, {"st": "4.788", "t": "lancibus et positas gentes tollitque premitque, 775"}, {"st": "4.789", "t": "qua genitus Caesar melius nunc condidit urbem"}, {"st": "4.790", "t": "et propriis frenat pendentem nutibus orbem."}, {"st": "4.791", "t": "inferius victae sidus Carthaginis arces"}, {"st": "4.792", "t": "et Libyam Aegyptique latus donataque rura"}, {"st": "4.793", "t": "Cyrenes lacrimis radicis Scorpios acris 780"}, {"st": "4.794", "t": "eligit, Italiaeque tamen respectat ad undas"}, {"st": "4.795", "t": "Sardiniamque tenet fusasque per aequora terras."}, {"st": "4.796", "t": "Cnosia Centauro tellus circumdata ponto"}, {"st": "4.797", "t": "paret, et in geminum Minois filius astrum"}, {"st": "4.798", "t": "ipse venit geminus. celeris hinc Creta sagittas 785"}, {"st": "4.799", "t": "asserit intentosque imitatur sideris arcus."}, {"st": "4.800", "t": "insula Trinacriae fluitantem ad iura sororem"}, {"st": "4.801", "t": "subsequitur Triviae sub eodem condita signo,"}, {"st": "4.802", "t": "proximaque Italiae tenui divisa profundo"}, {"st": "4.803", "t": "ora paris sequitur leges nec sidere rupta est. 790"}, {"st": "4.804", "t": "tu, Capricorne, regis quidquid sub sole cadente"}, {"st": "4.805", "t": "est positum gelidamque Helicen quod tangit ab illo,"}, {"st": "4.806", "t": "Hispanas gentes et quot fert Gallia dives;"}, {"st": "4.807", "t": "teque feris dignam tantum, Germania, matrem"}, {"st": "4.808", "t": "asserit ambiguum sidus terraeque marisque 795"}, {"st": "4.809", "t": "aestibus assiduis pontum terrasque sequentem."}, {"st": "4.810", "t": "sed Iuvenis nudos formatus mollior artus"}, {"st": "4.811", "t": "Aegyptum ad tepidam Tyriasque recedit &lt;in arces&gt;"}, {"st": "4.812", "t": "et Cilicum gentes vicinaque Caribus arva."}, {"st": "4.813", "t": "Piscibus Euphrates datus est, ubi &lt;ab&gt; his ope sumpta 800"}, {"st": "4.814", "t": "cum fugeret Typhona Venus subsedit in undis,"}, {"st": "4.815", "t": "et Tigris et rubri radiantia litora ponti. 806"}, {"st": "4.816", "t": "magna iacet tellus magnis circumdata ripis 802"}, {"st": "4.817", "t": "Parthis et <a> Parthis domitae per saecula gentes,"}, {"st": "4.818", "t": "Bactraque &lt;et&gt; Aethiopes, Babylon et Susa Ninosque,"}, {"st": "4.819", "t": "nominaque innumeris vix complectenda figuris. 805"}, {"st": "4.820", "t": "Sic divisa manet tellus per sidera cuncta, 807"}, {"st": "4.821", "t": "e quibus in proprias partes sunt iura trahenda;"}, {"st": "4.822", "t": "namque eadem, quae sunt signis, commercia servant,"}, {"st": "4.823", "t": "utque illa inter se coeunt odioque repugnant, 810"}, {"st": "4.824", "t": "nunc adversa polo, nunc et coniuncta trigono,"}, {"st": "4.825", "t": "quaeque alia in varios affectus causa gubernat,"}, {"st": "4.826", "t": "sic terrae terris respondent, urbibus urbes,"}, {"st": "4.827", "t": "litora litoribus, regnis contraria regna;"}, {"st": "4.828", "t": "sic erit et sedes fugienda petendaque cuique, 815"}, {"st": "4.829", "t": "sic speranda fides, sic et metuenda pericla,"}, {"st": "4.830", "t": "ut genus in terram caelo descendit ab alto."}, {"st": "4.831", "t": "Percipe nunc etiam quae sint ecliptica Graio"}, {"st": "4.832", "t": "nomine, quod certos quasi delassata per annos"}, {"st": "4.833", "t": "non numquam cessant sterili torpentia motu. 820"}, {"st": "4.834", "t": "scilicet immenso nihil est aequale sub aevo"}, {"st": "4.835", "t": "perpetuosque tenet flores unumque tenorem,"}, {"st": "4.836", "t": "mutantur sed cuncta die variantque per annos;"}, {"st": "4.837", "t": "et fecunda suis absistunt frugibus arva"}, {"st": "4.838", "t": "continuosque negant partus effeta creando, 825"}, {"st": "4.839", "t": "rursus quae fuerant steriles ad semina terrae"}, {"st": "4.840", "t": "post nova sufficiunt nullo mandante tributa."}, {"st": "4.841", "t": "concutitur tellus validis compagibus haerens"}, {"st": "4.842", "t": "subducitque solum pedibus; natat orbis in ipso"}, {"st": "4.843", "t": "et vomit Oceanus pontum sitiensque resorbet 830"}, {"st": "4.844", "t": "nec sese ipse capit. sic quondam merserat urbes,"}, {"st": "4.845", "t": "humani generis cum solus constitit heres"}, {"st": "4.846", "t": "Deucalion scopuloque orbem possedit in uno."}, {"st": "4.847", "t": "nec non, cum patrias Phaethon temptavit habenas,"}, {"st": "4.848", "t": "arserunt gentes timuitque incendia caelum 835"}, {"st": "4.849", "t": "fugeruntque novas ardentia sidera flammas"}, {"st": "4.850", "t": "atque uno metuit condi natura sepulcro."}, {"st": "4.851", "t": "in tantum longo mutantur tempore cuncta"}, {"st": "4.852", "t": "atque iterum in semet redeunt. sic tempore certo"}, {"st": "4.853", "t": "signa quoque amittunt vires sumuntque receptas. 840"}, {"st": "4.854", "t": "causa patet, quod, Luna quibus defecit in astris"}, {"st": "4.855", "t": "orba sui fratris noctisque immersa tenebris,"}, {"st": "4.856", "t": "cum medius Phoebi radios intercipit orbis"}, {"st": "4.857", "t": "nec trahit assuetum quo fulget Delia lumen,"}, {"st": "4.858", "t": "haec quoque signa suo pariter cum sidere languent 845"}, {"st": "4.859", "t": "incurvata simul solitoque exempta vigori"}, {"st": "4.860", "t": "et velut elatam Phoeben in funere lugent."}, {"st": "4.861", "t": "ipsa docet titulo se causa: ecliptica signa"}, {"st": "4.862", "t": "dixere antiqui. pariter sed bina laborant,"}, {"st": "4.863", "t": "nec vicina loco sed quae contraria fulgent, 850"}, {"st": "4.864", "t": "sicut Luna suo tum tantum deficit orbe"}, {"st": "4.865", "t": "cum Phoebum adversis currentem non videt astris."}, {"st": "4.866", "t": "nec tamen aequali languescunt tempore cuncta,"}, {"st": "4.867", "t": "sed modo in affectus totus producitur annus,"}, {"st": "4.868", "t": "nunc brevius lassata manent, nunc longius astra 855"}, {"st": "4.869", "t": "exceduntque suo Phoebeia tempora casu."}, {"st": "4.870", "t": "atque, ubi perfectum est spatium quod cuique dicatur"}, {"st": "4.871", "t": "impleruntque suos certa statione labores"}, {"st": "4.872", "t": "bina per adversum caelum fulgentia signa,"}, {"st": "4.873", "t": "tum vice bina labant ipsis haerentia casus, 860"}, {"st": "4.874", "t": "quae prius in terras veniunt terrasque relinquunt,"}, {"st": "4.875", "t": "sidereo non ut pugnet contrarius orbi"}, {"st": "4.876", "t": "sed, qua mundus agit cursus, inclinet et ipse,"}, {"st": "4.877", "t": "amissasque negant vires, nec munera tanta"}, {"st": "4.878", "t": "nec similis reddunt noxas. locus omnia vertit. 865"}, {"st": "4.879", "t": "Sed quid tam tenui prodest ratione nitentem"}, {"st": "4.880", "t": "scrutari mundum, si mens sua cuique repugnat"}, {"st": "4.881", "t": "spemque timor tollit prohibetque a limine caeli?"}, {"st": "4.882", "t": "'conditur en' inquit 'vasto natura recessu"}, {"st": "4.883", "t": "mortalisque fugit visus et pectora nostra, 870"}, {"st": "4.884", "t": "nec prodesse potest quod fatis cuncta reguntur,"}, {"st": "4.885", "t": "cum fatum nulla possit ratione videri.'"}, {"st": "4.886", "t": "quid iuvat in semet sua per convicia ferri"}, {"st": "4.887", "t": "et fraudare bonis, quae nec deus invidet ipse,"}, {"st": "4.888", "t": "quosque dedit natura oculos deponere mentis? 875"}, {"st": "4.889", "t": "perspicimus caelum, cur non et munera caeli?"}, {"st": "4.890", "t": "&lt;mens humana potest propria discedere sede&gt; 876a"}, {"st": "4.891", "t": "inque ipsos penitus mundi descendere census"}, {"st": "4.892", "t": "seminibusque suis tantam componere molem"}, {"st": "4.893", "t": "et partum caeli sua per nutricia ferre"}, {"st": "4.894", "t": "extremumque sequi pontum terraeque subire 880"}, {"st": "4.895", "t": "pendentis tractus et toto vivere in orbe."}, {"st": "4.896", "t": "[quanta et pars superet rationem discere noctis]"}, {"st": "4.897", "t": "iam nusquam natura latet; pervidimus omnem"}, {"st": "4.898", "t": "et capto potimur mundo nostrumque parentem"}, {"st": "4.899", "t": "pars sua perspicimus genitique accedimus astris. 885"}, {"st": "4.900", "t": "an dubium est habitare deum sub pectore nostro"}, {"st": "4.901", "t": "in caelumque redire animas caeloque venire,"}, {"st": "4.902", "t": "utque sit ex omni constructus corpore mundus"}, {"st": "4.903", "t": "aeris atque ignis summi terraeque marisque"}, {"st": "4.904", "t": "hospitium menti totum quae infusa gubernet, 890"}, {"st": "4.905", "t": "sic esse in nobis terrenae corpora sortis"}, {"st": "4.906", "t": "sanguineasque animas animo, qui cuncta gubernat"}, {"st": "4.907", "t": "dispensatque hominem? quid mirum, noscere mundum"}, {"st": "4.908", "t": "si possunt homines, quibus est et mundus in ipsis"}, {"st": "4.909", "t": "exemplumque dei quisque est in imagine parva? 895"}, {"st": "4.910", "t": "an cuiquam genitos, nisi caelo, credere fas est"}, {"st": "4.911", "t": "esse homines? proiecta iacent animalia cuncta"}, {"st": "4.912", "t": "in terra vel mersa vadis, vel in aere pendent,"}, {"st": "4.913", "t": "omnibus una quies venter&lt;que Venusque voluptas,"}, {"st": "4.914", "t": "mole valens sola corpus&gt; censumque per artus, 899a"}, {"st": "4.915", "t": "et, quia consilium non est, et lingua remissa."}, {"st": "4.916", "t": "unus &lt;in&gt; inspectus rerum viresque loquendi"}, {"st": "4.917", "t": "ingeniumque capax variasque educitur artes"}, {"st": "4.918", "t": "hic partus, qui cuncta regit: secessit in urbes,"}, {"st": "4.919", "t": "edomuit terram ad fruges, animalia cepit"}, {"st": "4.920", "t": "imposuitque viam ponto, stetit unus in arcem 905"}, {"st": "4.921", "t": "erectus capitis victorque ad sidera mittit"}, {"st": "4.922", "t": "sidereos oculos propiusque aspectat Olympum"}, {"st": "4.923", "t": "inquiritque Iovem; nec sola fronte deorum"}, {"st": "4.924", "t": "contentus manet, et caelum scrutatur in alvo"}, {"st": "4.925", "t": "cognatumque sequens corpus se quaerit in astris. 910"}, {"st": "4.926", "t": "huic in tanta fidem petimus, quam saepe volucres"}, {"st": "4.927", "t": "accipiunt trepidaeque suo sub pectore fibrae."}, {"st": "4.928", "t": "an minus est sacris rationem ducere signis"}, {"st": "4.929", "t": "quam pecudum mortes aviumque attendere cantus?"}, {"st": "4.930", "t": "atque ideo faciem caeli non invidet orbi 915"}, {"st": "4.931", "t": "ipse deus vultusque suos corpusque recludit"}, {"st": "4.932", "t": "volvendo semper seque ipsum inculcat et offert,"}, {"st": "4.933", "t": "ut bene cognosci possit doceatque videntis,"}, {"st": "4.934", "t": "qualis eat, cogatque suas attendere leges."}, {"st": "4.935", "t": "ipse vocat nostros animos ad sidera mundus 920"}, {"st": "4.936", "t": "nec patitur, quia non condit, sua iura latere."}, {"st": "4.937", "t": "quis putet esse nefas nosci, quod cernere fas est?"}, {"st": "4.938", "t": "nec contemne tuas quasi parvo in pectore vires:"}, {"st": "4.939", "t": "quod valet, immensum est. sic auri pondera parvi"}, {"st": "4.940", "t": "exsuperant pretio numerosos aeris acervos; 925"}, {"st": "4.941", "t": "sic adamas, punctum lapidis, pretiosior auro est;"}, {"st": "4.942", "t": "parvula sic totum pervisit pupula caelum,"}, {"st": "4.943", "t": "quoque vident oculi minimum est, cum maxima cernant;"}, {"st": "4.944", "t": "sic animi sedes tenui sub corde locata"}, {"st": "4.945", "t": "per totum angusto regnat de limite corpus. 930"}, {"st": "4.946", "t": "materiae ne quaere modum, sed perspice vires,"}, {"st": "4.947", "t": "quas ratio, non pondus, habet: ratio omnia vincit."}, {"st": "4.948", "t": "ne dubites homini divinos credere visus,"}, {"st": "4.949", "t": "iam facit ipse deos mittitque ad sidera numen,"}, {"st": "4.950", "t": "maius et Augusto crescet sub principe caelum."}, {"sp": "HDR", "t": "Liber V"}, {"st": "5.1", "t": "Hic alius finisset iter signisque relatis"}, {"st": "5.2", "t": "quis adversa meant stellarum numina quinque"}, {"st": "5.3", "t": "quadriiugis et Phoebus equis et Delia bigis"}, {"st": "5.4", "t": "non ultra struxisset opus, caeloque rediret"}, {"st": "5.5", "t": "ac per descensum medios percurreret ignes"}, {"st": "5.6", "t": "Saturni, Iovis et Martis Solisque, sub illis"}, {"st": "5.7", "t": "post Venerem et Maia natum te, Luna, vagantem."}, {"st": "5.8", "t": "me properare etiam mundus iubet omnia circum"}, {"st": "5.9", "t": "sidera vectatum toto decurrere caelo,"}, {"st": "5.10", "t": "cum semel aetherios ausus conscendere currus"}, {"st": "5.11", "t": "summum contigerim sua per fastigia culmen."}, {"st": "5.12", "t": "hinc vocat Orion, magni pars maxima caeli,"}, {"st": "5.13", "t": "et ratis heroum, quae nunc quoque navigat astris,"}, {"st": "5.14", "t": "Fluminaque errantis late sinuantia flexus"}, {"st": "5.15", "t": "et biferum Cetos squamis atque ore tremendo"}, {"st": "5.16", "t": "Hesperidumque vigil custos et divitis auri"}, {"st": "5.17", "t": "et Canis in totum portans incendia mundum"}, {"st": "5.18", "t": "araque divorum, cui votum solvit Olympus;"}, {"st": "5.19", "t": "illinc per geminas Anguis qui labitur Arctos"}, {"st": "5.20", "t": "Heniochusque memor currus plaustrique Bootes"}, {"st": "5.21", "t": "atque Ariadnaeae caelestia dona coronae,"}, {"st": "5.22", "t": "victor et invisae Perseus cum falce Medusae"}, {"st": "5.23", "t": "Andromedanque necans genitor cum coniuge Cepheus,"}, {"st": "5.24", "t": "quaque volat stellatus Equus celerique Sagittae"}, {"st": "5.25", "t": "Delphinus certans et Iuppiter alite tectus,"}, {"st": "5.26", "t": "ceteraque in toto passim labentia caelo."}, {"st": "5.27", "t": "quae mihi per proprias vires sunt cuncta canenda"}, {"st": "5.28", "t": "quid valeant ortu, quid cum merguntur in undas,"}, {"st": "5.29", "t": "et quota de bis sex astris pars quaeque reducat."}, {"st": "5.32", "t": "Vir gregis et ponti victor, cui parte relicta"}, {"st": "5.33", "t": "nomen onusque dedit nec pelle immunis ab ipsa,"}, {"st": "5.34", "t": "Colchidos et magicas artes qui visere Iolcon"}, {"st": "5.35", "t": "Medeae iussit movitque venena per orbem,"}, {"st": "5.36", "t": "nunc quoque vicinam puppi, ceu naviget, Argo"}, {"st": "5.37", "t": "a dextri lateris ducit regione per astra."}, {"st": "5.38", "t": "sed tum prima suos puppis consurgit in ignes,"}, {"st": "5.39", "t": "quattuor in partes cum Corniger extulit ora."}, {"st": "5.40", "t": "illa quisquis erit terris oriente creatus,"}, {"st": "5.41", "t": "rector erit puppis clavoque immobilis haerens"}, {"st": "5.42", "t": "mutabit pelago terras ventisque sequetur"}, {"st": "5.43", "t": "fortunam totumque volet tranare profundum"}, {"st": "5.44", "t": "classibus atque alios menses altumque videre"}, {"st": "5.45", "t": "Phasin et in cautes Tiphyn superare ruentem."}, {"st": "5.46", "t": "tolle sitos ortus hominum sub sidere tali,"}, {"st": "5.47", "t": "sustuleris bellum Troiae classemque solutam"}, {"st": "5.48", "t": "sanguine et appulsam terris; non invehet undis"}, {"st": "5.49", "t": "Persida nec pelagus Xerxes facietque tegetque;"}, {"st": "5.50", "t": "versa Syracusis Salamis non merget Athenas,"}, {"st": "5.51", "t": "Punica nec toto fluitabunt aequore rostra"}, {"st": "5.52", "t": "Actiacosque sinus inter suspensus utrimque"}, {"st": "5.53", "t": "orbis et in ponto caeli fortuna natabit."}, {"st": "5.54", "t": "his ducibus caeco ducuntur in aequore classes"}, {"st": "5.55", "t": "et coit ipsa sibi tellus totusque per usus"}, {"st": "5.56", "t": "diversos rerum ventis arcessitur orbis."}, {"st": "5.57", "t": "Sed decima lateris surgens de parte sinistri"}, {"st": "5.58", "t": "maximus Orion magnumque amplexus Olympum,"}, {"st": "5.59", "t": "quo fulgente super terras caelumque trahente"}, {"st": "5.60", "t": "ementita diem nigras nox contrahit alas,"}, {"st": "5.61", "t": "sollertis animos, velocia corpora finget"}, {"st": "5.62", "t": "atque agilem officio mentem curasque per omnis"}, {"st": "5.63", "t": "indelassato properantia corda vigore."}, {"st": "5.64", "t": "instar erit populi totaque habitabit in urbe"}, {"st": "5.65", "t": "limina pervolitans unumque per omnia verbum"}, {"st": "5.66", "t": "mane salutandi portans communis amicus."}, {"st": "5.67", "t": "Sed, cum se terris Aries ter quinque peractis"}, {"st": "5.68", "t": "partibus extollit, primum iuga tollit ab undis"}, {"st": "5.69", "t": "Heniochus clivoque rotas convellit ab imo,"}, {"st": "5.70", "t": "qua gelidus Boreas aquilonibus instat acutis."}, {"st": "5.71", "t": "ille dabit proprium studium caeloque retentas"}, {"st": "5.72", "t": "quas prius in terris agitator amaverat artes:"}, {"st": "5.73", "t": "stare levi curru moderantem quattuor ora"}, {"st": "5.74", "t": "spumigeris frenata lupis et flectere equorum"}, {"st": "5.75", "t": "praevalidas vires ac torto stringere gyro;"}, {"st": "5.76", "t": "at, cum laxato fugerunt cardine claustra,"}, {"st": "5.77", "t": "exagitare feros pronumque antire volantis"}, {"st": "5.78", "t": "vixque rotis levibus summum contingere campum"}, {"st": "5.79", "t": "vincentem pedibus ventos, vel prima tenentem"}, {"st": "5.80", "t": "agmina in obliquum cursus agitare malignos"}, {"st": "5.81", "t": "obstantemque mora totum praecludere circum,"}, {"st": "5.82", "t": "vel medium turbae nunc dextros ire per orbes"}, {"st": "5.83", "t": "fidentem campo, nunc meta currere acuta"}, {"st": "5.84", "t": "spemque sub extremo dubiam suspendere casu."}, {"st": "5.85", "t": "nec non alterno desultor sidere dorso"}, {"st": "5.86", "t": "quadrupedum et stabilis poterit defigere plantas,"}, {"st": "5.87", "t": "pervolitans et equos ludet per terga volantum;"}, {"st": "5.88", "t": "aut solo vectatus equo nunc arma movebit,"}, {"st": "5.89", "t": "nunc leget in longo per cursum praemia circo."}, {"st": "5.90", "t": "quidquid de tali studio formatur habebit."}, {"st": "5.91", "t": "hinc mihi Salmoneus (qui caelum imitatus in orbe,"}, {"st": "5.92", "t": "pontibus impositis missisque per aera quadrigis"}, {"st": "5.93", "t": "expressisse sonum mundi sibi visus et ipsum"}, {"st": "5.94", "t": "admovisse Iovem terris, dum fulmina fingit"}, {"st": "5.95", "t": "sensit, et immissos ignes super ipse secutus"}, {"st": "5.96", "t": "morte Iovem didicit) generatus possit haberi."}, {"st": "5.97", "t": "hoc genitum credas de sidere Bellerophonten"}, {"st": "5.98", "t": "imposuisse viam mundo per signa volantem,"}, {"st": "5.99", "t": "cui caelum campus fuerat, terraeque fretumque"}, {"st": "5.100", "t": "sub pedibus, non ulla tulit vestigia cursus."}, {"st": "5.101", "t": "his erit Heniochi surgens tibi forma notanda."}, {"st": "5.102", "t": "Cumque decem partes Aries duplicaverit ortus,"}, {"st": "5.103", "t": "incipient Haedi tremulum producere mentum"}, {"st": "5.104", "t": "hirtaque tum demum terris promittere terga"}, {"st": "5.105", "t": "qua dexter Boreas spirat. ne crede severae"}, {"st": "5.106", "t": "frontis opus fingi, strictosque hinc ora Catones"}, {"st": "5.107", "t": "abruptumque pari Torquatum et Horatia facta."}, {"st": "5.108", "t": "maius onus signo est, Haedis nec tanta petulcis"}, {"st": "5.109", "t": "conveniunt: levibus gaudent lascivaque signant"}, {"st": "5.110", "t": "pectora; et in lusus facilis agilemque vigorem"}, {"st": "5.111", "t": "desudant; vario ducunt in amore iuventam;"}, {"st": "5.112", "t": "in vulnus numquam virtus sed saepe libido"}, {"st": "5.113", "t": "impellit, turpisque emitur vel morte voluptas;"}, {"st": "5.114", "t": "et minimum cecidisse malum est, quia crimine vincunt."}, {"st": "5.115", "t": "nec non et cultus pecorum nascentibus addunt"}, {"st": "5.116", "t": "pastoremque suum generant, cui fistula collo"}, {"st": "5.117", "t": "haereat et voces alterna per oscula ducat."}, {"st": "5.118", "t": "Sed, cum bis denas augebit septima partes"}, {"st": "5.119", "t": "Lanigeri, surgent Hyades. quo tempore natis"}, {"st": "5.120", "t": "nulla quies placet, in nullo sunt otia fructu,"}, {"st": "5.121", "t": "sed populum turbamque petunt rerumque tumultus."}, {"st": "5.122", "t": "seditio clamorque iuvat, Gracchosque tenentis"}, {"st": "5.123", "t": "rostra volunt Montemque Sacrum rarosque Quirites;"}, {"st": "5.124", "t": "pacis bella probant curaeque alimenta ministrant."}, {"st": "5.125", "t": "immundosque greges agitant per sordida rura;"}, {"st": "5.126", "t": "et fidum Laertiadae genuere syboten."}, {"st": "5.127", "t": "hos generant Hyades mores surgentibus astris."}, {"st": "5.128", "t": "Ultima Lanigeri cum pars excluditur orbi,"}, {"st": "5.129", "t": "quae totum ostendit terris atque eruit undis,"}, {"st": "5.130", "t": "Olenie servans praegressos tollitur Haedos"}, {"st": "5.131", "t": "egelido stellata polo, qua dextera pars est,"}, {"st": "5.132", "t": "officio magni mater Iovis. illa Tonanti"}, {"st": "5.133", "t": "fida alimenta dedit pectusque implevit hiantis"}, {"st": "5.134", "t": "lacte suo, dedit et dignas ad fulmina vires."}, {"st": "5.135", "t": "hinc trepidae mentes tremebundaque corda creantur"}, {"st": "5.136", "t": "suspensa ad strepitus levibusque obnoxia causis."}, {"st": "5.137", "t": "his etiam ingenita est visendi ignota cupido,"}, {"st": "5.138", "t": "ut nova per montes quaerunt arbusta capellae,"}, {"st": "5.139", "t": "semper et ulterius pascentes tendere gaudent."}, {"st": "5.140", "t": "Taurus, in aversos praeceps cum tollitur ortus,"}, {"st": "5.141", "t": "sexta parte sui certantis luce sorores"}, {"st": "5.142", "t": "Pleiadas ducit. quibus aspirantibus almam"}, {"st": "5.143", "t": "in lucem eduntur Bacchi Venerisque sequaces"}, {"st": "5.144", "t": "perque dapes mensasque super petulantia corda"}, {"st": "5.145", "t": "et sale mordaci dulcis quaerentia risus."}, {"st": "5.146", "t": "illis cura sui cultus frontisque decorae"}, {"st": "5.147", "t": "semper erit: tortos in fluctum ponere crines"}, {"st": "5.148", "t": "aut vinclis revocare comas et vertice denso"}, {"st": "5.149", "t": "fingere et appositis caput emutare capillis"}, {"st": "5.150", "t": "pumicibusque cavis horrentia membra polire"}, {"st": "5.151", "t": "atque odisse virum teretisque optare lacertos."}, {"st": "5.152", "t": "femineae vestes, nec in usum tegmina plantis"}, {"st": "5.153", "t": "sed speciem, fictique placent ad mollia gressus."}, {"st": "5.154", "t": "naturae pudet, atque habitat sub pectore caeca"}, {"st": "5.155", "t": "ambitio, et morbum virtutis nomine iactant."}, {"st": "5.156", "t": "semper amare parum est: cupient et amare videri."}, {"st": "5.157", "t": "Iam vero Geminis fraterna ferentibus astra"}, {"st": "5.158", "t": "in caelum summoque natantibus aequore ponti"}, {"st": "5.159", "t": "septima pars Leporem tollit. quo sidere natis"}, {"st": "5.160", "t": "vix alas natura negat volucrisque meatus:"}, {"st": "5.161", "t": "tantus erit per membra vigor referentia ventos."}, {"st": "5.162", "t": "ille prius victor stadio quam missus abibit;"}, {"st": "5.163", "t": "ille cito motu rigidos eludere caestus,"}, {"st": "5.164", "t": "nunc exire levis missas nunc mittere palmas,"}, {"st": "5.165", "t": "ille pilam celeri fugientem reddere planta"}, {"st": "5.166", "t": "et pedibus pensare manus et ludere fulcro"}, {"st": "5.167", "t": "mobilibusque citos ictus glomerare lacertis,"}, {"st": "5.168", "t": "ille potens turba perfundere membra pilarum"}, {"st": "5.169", "t": "per totumque vagas corpus disponere palmas,"}, {"st": "5.170", "t": "ut teneat tantos orbes sibique ipse reludat"}, {"st": "5.171", "t": "et velut edoctos iubeat volitare per ipsum."}, {"st": "5.172", "t": "invigilat curis, somnos industria vincit,"}, {"st": "5.173", "t": "otia per varios exercet dulcia lusus."}, {"st": "5.174", "t": "Nunc Cancro vicina canam, cui parte sinistra"}, {"st": "5.175", "t": "consurgunt Iugulae. quibus aspirantibus orti"}, {"st": "5.176", "t": "te, Meleagre, colunt flammis absentibus ustum"}, {"st": "5.177", "t": "reddentemque tuae per mortem munera matri,"}, {"st": "5.178", "t": "cuius et ante necem paulatim vita sepulta est,"}, {"st": "5.179", "t": "atque Atalantaeos conatum ferre labores,"}, {"st": "5.180", "t": "et Calydonea bellantem rupe puellam"}, {"st": "5.181", "t": "vincentemque viros et quam potuisse videre"}, {"st": "5.182", "t": "virgine maius erat sternentem vulnere primo."}, {"st": "5.183", "t": "quaque erat Actaeon silvis mirandus, et ante"}, {"st": "5.184", "t": "quam canibus nova praeda fuit, ducuntur et ipsi,"}, {"st": "5.185", "t": "retibus et claudunt campos, formidine montes."}, {"st": "5.186", "t": "mendacisque parant foveas laqueosque tenacis"}, {"st": "5.187", "t": "currentisque feras pedicarum compede nectunt"}, {"st": "5.188", "t": "aut canibus ferrove necant praedasque reportant."}, {"st": "5.189", "t": "sunt quibus in ponto studium est cepisse ferarum"}, {"st": "5.190", "t": "diversas facies et caeco mersa profundo"}, {"st": "5.191", "t": "sternere litoreis monstrorum corpora harenis"}, {"st": "5.192", "t": "horrendumque fretis in bella lacessere pontum"}, {"st": "5.193", "t": "et colare vagos inductis retibus amnes"}, {"st": "5.194", "t": "ac per nulla sequi dubias vestigia praedas,"}, {"st": "5.195", "t": "luxuriae quia terra parum, fastidit et orbem"}, {"st": "5.196", "t": "venter, et ipse gulam Nereus ex aequore pascit."}, {"st": "5.197", "t": "At Procyon oriens, cum iam vicesima Cancro"}, {"st": "5.198", "t": "septimaque ex undis pars sese emergit in astra,"}, {"st": "5.199", "t": "venatus non ille quidem verum arma creatis"}, {"st": "5.200", "t": "venandi tribuit. catulos nutrire sagacis"}, {"st": "5.201", "t": "et genus a proavis, mores numerare per urbes,"}, {"st": "5.202", "t": "retiaque et valida venabula cuspide fixa"}, {"st": "5.203", "t": "lentaque correctis formare hastilia nodis,"}, {"st": "5.204", "t": "et quaecumque solet venandi poscere cura"}, {"st": "5.205", "t": "in proprios fabricare dabit venalia quaestus."}, {"st": "5.206", "t": "Cum vero in vastos surget Nemeaeus hiatus,"}, {"st": "5.207", "t": "exoritur candens latratque Canicula flammas"}, {"st": "5.208", "t": "et rabit igne suo geminatque incendia solis."}, {"st": "5.209", "t": "qua subdente facem terris radiosque vomente"}, {"st": "5.210", "t": "divinat cineres orbes fatumque supremum"}, {"st": "5.211", "t": "sortitur, languetque suis Neptunus in undis,"}, {"st": "5.212", "t": "et viridis nemori sanguis decedit et herbis."}, {"st": "5.213", "t": "cuncta peregrinos orbes animalia quaerunt"}, {"st": "5.214", "t": "atque eget alterius mundus; natura suismet"}, {"st": "5.215", "t": "aegrotat morbis nimios obsessa per aestus"}, {"st": "5.216", "t": "inque rogo vivit: tantus per sidera fervor"}, {"st": "5.217", "t": "funditur atque uno cessant in lumine cuncta."}, {"st": "5.218", "t": "haec ubi se ponto per primas extulit oras,"}, {"st": "5.219", "t": "nascentem quam nec pelagi restinxerit unda,"}, {"st": "5.220", "t": "effrenos animos violentaque pectora finget"}, {"st": "5.221", "t": "irarumque dabit fluctus odiumque metumque"}, {"st": "5.222", "t": "totius vulgi. praecurrunt verba loquentis,"}, {"st": "5.223", "t": "ante os est animus nec magnis concita causis"}, {"st": "5.224", "t": "corda micant et lingua rabit latratque loquendo,"}, {"st": "5.225", "t": "morsibus et crebris dentes in voce relinquit."}, {"st": "5.226", "t": "ardescit vino vitium, viresque ministrat"}, {"st": "5.227", "t": "Bacchus et in flammam saevas exsuscitat iras."}, {"st": "5.228", "t": "nec silvas rupesque timent vastosque leones"}, {"st": "5.229", "t": "aut spumantis apri dentes atque arma ferarum,"}, {"st": "5.230", "t": "effunduntque suas concesso in corpore flammas."}, {"st": "5.231", "t": "ne talis mirere artes sub sidere tali,"}, {"st": "5.232", "t": "cernis ut ipsum etiam sidus venetur in astris;"}, {"st": "5.233", "t": "praegressum quaerit Leporem comprendere cursu."}, {"st": "5.234", "t": "Ultima pars magni cum tollitur orta Leonis,"}, {"st": "5.235", "t": "Crater auratis surgit caelatus ab astris."}, {"st": "5.236", "t": "inde trahit quicumque genus moresque, sequetur"}, {"st": "5.237", "t": "irriguos ruris campos amnesque lacusque,"}, {"st": "5.238", "t": "et te, Bacche, tuas nubentem iunget ad ulmos,"}, {"st": "5.239", "t": "disponetve iugis imitatus fronde choreas,"}, {"st": "5.240", "t": "robore vel proprio fidentem in bracchia ducet"}, {"st": "5.241", "t": "teque tibi credet semperque, ut matre resectum,"}, {"st": "5.242", "t": "abiunget thalamis, segetemque interseret uvis,"}, {"st": "5.243", "t": "quaeque alia innumeri cultus est forma per orbem"}, {"st": "5.244", "t": "pro regione colet. nec parce vina recepta"}, {"st": "5.245", "t": "hauriet, emeritis et fructibus ipse fruetur"}, {"st": "5.246", "t": "gaudebitque mero mergetque in pocula mentem."}, {"st": "5.247", "t": "nec solum terrae spem credet in annua vota:"}, {"st": "5.248", "t": "annonae quoque vectigal mercesque sequetur"}, {"st": "5.249", "t": "praecipue quas umor alit nec deserit unda."}, {"st": "5.250", "t": "talis effinget Crater umoris amator."}, {"st": "5.251", "t": "Iam subit Erigone. quae cum tibi quinque feretur"}, {"st": "5.252", "t": "partibus ereptis ponto, tollentur ab undis"}, {"st": "5.253", "t": "clara Ariadnaeae quondam monumenta coronae"}, {"st": "5.254", "t": "et mollis tribuent artes. hinc dona puellae"}, {"st": "5.255", "t": "namque nitent, illinc oriens est ipsa puella."}, {"st": "5.256", "t": "ille colet nitidis gemmantem floribus hortum"}, {"st": "5.260", "t": "caeruleumque oleis viridemve in gramine collem."}, {"st": "5.257", "t": "pallentis violas et purpureos hyacinthos"}, {"st": "5.258", "t": "liliaque et Tyrias imitata papavera luces"}, {"st": "5.259", "t": "vernantisque rosae rubicundo sanguine florem"}, {"st": "5.261", "t": "conseret et veris depinget prata figuris."}, {"st": "5.262", "t": "aut varios nectet flores sertisque locabit"}, {"st": "5.263", "t": "effingetque suum sidus similisque &lt;coronas"}, {"st": "5.264", "t": "Cnosiacae faciet; calamosque&gt; in mutua pressos 263a"}, {"st": "5.265", "t": "incoquet atque Arabum Syriis mulcebit odores"}, {"st": "5.266", "t": "et medios unguenta dabit referentia flatus,"}, {"st": "5.267", "t": "ut sit adulterio sucorum gratia maior."}, {"st": "5.268", "t": "munditiae &lt;cordi&gt; cultusque artesque decorae"}, {"st": "5.269", "t": "et lenocinium vitae praesensque voluptas."}, {"st": "5.270", "t": "Virginis hoc anni poscunt floresque Coronae."}, {"st": "5.270b", "t": "At, cum per decimam consurgens horrida partem"}, {"st": "5.271", "t": "Spica feret prae se vallantis corpus aristas,"}, {"st": "5.272", "t": "arvorum ingenerat studium rurisque colendi"}, {"st": "5.273", "t": "seminaque in faenus sulcatis credere terris"}, {"st": "5.274", "t": "usuramque sequi maiorem sorte receptis"}, {"st": "5.275", "t": "frugibus innumeris atque horrea quaerere messi"}, {"st": "5.276", "t": "(quod solum decuit mortalis nosse metallum:"}, {"st": "5.277", "t": "nulla fames, non ulla forent ieiunia terris;"}, {"st": "5.278", "t": "dives erat census saturatis gentibus &lt;olim"}, {"st": "5.279", "t": "argenti venis aurique latentibus&gt; orbi) 278a"}, {"st": "5.280", "t": "et, si forte labor vires tardaverit, artes"}, {"st": "5.281", "t": "quis sine nulla Ceres, non ullus seminis usus,"}, {"st": "5.282", "t": "subdere fracturo silici frumenta superque"}, {"st": "5.283", "t": "ducere pendentis orbes et mergere farra"}, {"st": "5.284", "t": "ac torrere focis hominumque alimenta parare"}, {"st": "5.285", "t": "atque unum genus in multas variare figuras."}, {"st": "5.285b", "t": "et, quia dispositis habitatur spica per artem"}, {"st": "5.286", "t": "frugibus, ac structo similis componitur ordo,"}, {"st": "5.287", "t": "seminibusque suis cellas atque horrea praebet,"}, {"st": "5.288", "t": "sculpentem faciet sanctis laquearia templis"}, {"st": "5.289", "t": "condentemque novum caelum per tecta Tonantis."}, {"st": "5.290", "t": "haec fuerat quondam divis concessa figura,"}, {"st": "5.291", "t": "nunc iam luxuriae pars est: triclinia templis"}, {"st": "5.292", "t": "concertant, tectique auro iam vescimur auro."}, {"st": "5.293", "t": "Sed parte octava surgentem cerne Sagittam"}, {"st": "5.294", "t": "Chelarum. dabit haec iaculum torquere lacertis,"}, {"st": "5.295", "t": "et calamum nervis, glaebas et mittere virgis,"}, {"st": "5.296", "t": "pendentemque suo volucrem deprendere caelo,"}, {"st": "5.297", "t": "cuspide vel triplici securum figere piscem."}, {"st": "5.298", "t": "quod potius dederim Teucro sidusve genusve,"}, {"st": "5.299", "t": "teve, Philoctete, cui malim credere parti?"}, {"st": "5.300", "t": "Hectoris ille faces arcu taedamque fugavit,"}, {"st": "5.301", "t": "mittebat saevos ignes quae mille carinis."}, {"st": "5.302", "t": "hic sortem pharetra Troiae bellique gerebat,"}, {"st": "5.303", "t": "maior et armatis hostis subsederat exul."}, {"st": "5.304", "t": "quin etiam ille pater tali de sidere cretus"}, {"st": "5.305", "t": "esse potest, qui serpentem super ora cubantem"}, {"st": "5.306", "t": "infelix nati somnumque animamque bibentem"}, {"st": "5.307", "t": "sustinuit misso petere ac prosternere telo."}, {"st": "5.308", "t": "ars erat esse patrem; vicit natura periclum"}, {"st": "5.309", "t": "et pariter iuvenem somnoque ac morte levavit"}, {"st": "5.310", "t": "tunc iterum natum et fato per somnia raptum."}, {"st": "5.311", "t": "At, cum secretis improvidus Haedus in antris"}, {"st": "5.312", "t": "erranti similis fratrum vestigia quaerit"}, {"st": "5.313", "t": "postque gregem longo producitur intervallo,"}, {"st": "5.314", "t": "sollertis animos agitataque pectora in usus"}, {"st": "5.315", "t": "effingit varios nec deficientia curis"}, {"st": "5.316", "t": "nec contenta domo. populi sunt illa ministra"}, {"st": "5.317", "t": "perque magistratus et publica iura feruntur."}, {"st": "5.318", "t": "non illo coram digitos quaesiverit hasta,"}, {"st": "5.319", "t": "defueritque bonis sector, poenamque lucretur"}, {"st": "5.320", "t": "noxius et patriam fraudarit debitor aeris."}, {"st": "5.321", "t": "cognitor est urbis. nec non lascivit amores"}, {"st": "5.322", "t": "in varios ponitque forum suadente Lyaeo,"}, {"st": "5.323", "t": "mobilis in saltus et scaenae mollior arte."}, {"st": "5.324", "t": "Nunc surgente Lyra testudinis enatat undis"}, {"st": "5.325", "t": "forma per heredem tantum post fata sonantis,"}, {"st": "5.326", "t": "qua quondam somnumque fretis Oeagrius Orpheus"}, {"st": "5.327", "t": "et sensus scopulis et silvis addidit aures"}, {"st": "5.328", "t": "et Diti lacrimas et morti denique finem."}, {"st": "5.329", "t": "hinc venient vocis dotes chordaeque sonantis"}, {"st": "5.330", "t": "garrulaque &lt;in&gt; modulos diversa tibia forma"}, {"st": "5.331", "t": "et quodcumque manu loquitur flatuque movetur."}, {"st": "5.332", "t": "ille dabit cantus inter convivia dulcis"}, {"st": "5.333", "t": "mulcebitque sono Bacchum noctemque tenebit."}, {"st": "5.334", "t": "quin etiam curas inter secreta movebit"}, {"st": "5.335", "t": "carmina furtivo modulatus murmure vocem,"}, {"st": "5.336", "t": "solus et ipse suas semper cantabit ad aures,"}, {"st": "5.337", "t": "sic dictante Lyra, cum pars vicesima sexta"}, {"st": "5.338", "t": "Chelarum surget, quae cornua ducet ad astra."}, {"st": "5.339", "t": "Quid regione Nepae vix partes octo trahentis"}, {"st": "5.340", "t": "Ara ferens turis stellis imitantibus ignem,"}, {"st": "5.341", "t": "in qua devoti quondam cecidere Gigantes,"}, {"st": "5.342", "t": "nec prius armavit violento fulmine dextram"}, {"st": "5.343", "t": "Iuppiter, ante deos quam constitit ipse sacerdos?"}, {"st": "5.344", "t": "quos potius fingent ortus quam templa colentis"}, {"st": "5.345", "t": "atque auctoratos in tertia iura ministros,"}, {"st": "5.346", "t": "divorumque sacra venerantis numina voce,"}, {"st": "5.347", "t": "paene deos et qui possint ventura videre?"}, {"st": "5.348", "t": "Quattuor appositis Centaurus partibus effert"}, {"st": "5.349", "t": "sidera et ex ipso mores nascentibus addit."}, {"st": "5.350", "t": "aut stimulis agitabit onus mixtasque iugabit"}, {"st": "5.351", "t": "semine quadrupedes aut curru celsior ibit"}, {"st": "5.352", "t": "aut onerabit equos armis aut ducet in arma."}, {"st": "5.353", "t": "ille tenet medicas artes ad membra ferarum"}, {"st": "5.354", "t": "et non auditos mutarum tollere morbos."}, {"st": "5.355", "t": "hoc est artis opus, non exspectare gementis"}, {"st": "5.356", "t": "et sibi non aegrum iamdudum credere corpus."}, {"st": "5.357", "t": "Hunc subit Arcitenens, cuius pars quinta nitentem"}, {"st": "5.358", "t": "Arcturum ostendit ponto. quo tempore natis"}, {"st": "5.359", "t": "Fortuna ipsa suos audet committere census,"}, {"st": "5.360", "t": "regalis ut opes et sancta aeraria servent"}, {"st": "5.361", "t": "regnantes sub rege suo rerumque ministri,"}, {"st": "5.362", "t": "tutelamque gerant populi, domibusve regendis"}, {"st": "5.363", "t": "praepositi curas alieno limine claudant."}, {"st": "5.364", "t": "Arcitenens cum se totum produxerit undis,"}, {"st": "5.365", "t": "ter decima sub parte feri formantibus astris"}, {"st": "5.366", "t": "plumeus in caelum nitidis Olor evolat alis."}, {"st": "5.367", "t": "quo surgente trahens lucem matremque relinquens"}, {"st": "5.368", "t": "ipse quoque aerios populos caeloque dicatum"}, {"st": "5.369", "t": "alituum genus in studium censusque vocabit."}, {"st": "5.370", "t": "mille fluent artes: aut bellum indicere mundo"}, {"st": "5.371", "t": "et medios inter volucrem prensare meatus,"}, {"st": "5.372", "t": "aut nidis damnare suis, ramove sedentem"}, {"st": "5.373", "t": "pascentemve super surgentia ducere lina."}, {"st": "5.374", "t": "atque haec in luxum. iam ventri longius itur"}, {"st": "5.375", "t": "quam modo militiae: Numidarum pascimur oris"}, {"st": "5.376", "t": "Phasidos et lucis; arcessitur inde macellum"}, {"st": "5.377", "t": "unde aurata novo devecta est aequore pellis."}, {"st": "5.378", "t": "quin etiam linguas hominum sensusque docebit"}, {"st": "5.379", "t": "aerias volucres novaque in commercia ducet"}, {"st": "5.380", "t": "verbaque praecipiet naturae lege negata."}, {"st": "5.381", "t": "ipse deum Cycnus condit vocemque sub illo"}, {"st": "5.382", "t": "non totus volucer, secumque immurmurat intus."}, {"st": "5.383", "t": "nec te praetereant clausas qui culmine summo"}, {"st": "5.384", "t": "pascere aves Veneris gaudent et reddere caelo"}, {"st": "5.385", "t": "aut certis revocare notis, totamve per urbem"}, {"st": "5.386", "t": "qui gestant caveis volucres ad iussa paratas,"}, {"st": "5.387", "t": "quorum omnis parvo consistit passere census."}, {"st": "5.388", "t": "has erit et similis tribuens Olor aureus artes."}, {"st": "5.389", "t": "Anguitenens magno circumdatus orbe draconis,"}, {"st": "5.390", "t": "cum venit in regione tuae, Capricorne, figurae,"}, {"st": "5.391", "t": "non inimica facit serpentum membra creatis."}, {"st": "5.392", "t": "accipient sinibusque suis peploque fluenti"}, {"st": "5.393", "t": "osculaque horrendis iungent impune venenis."}, {"st": "5.394", "t": "At, cum se patrio producens aequore Piscis"}, {"st": "5.395", "t": "in caelumque ferens alienis finibus ibit,"}, {"st": "5.396", "t": "quisquis erit tali capiens sub tempore vitam,"}, {"st": "5.397", "t": "litoribus ripisve suos circumferet annos,"}, {"st": "5.398", "t": "pendentem et caeco captabit in aequore piscem,"}, {"st": "5.531", "t": "et perlucentis cupiens prensare lapillos"}, {"st": "5.532", "t": "verticibus mediis oculos immittet avaros"}, {"st": "5.399", "t": "cumque suis domibus concha valloque latentis"}, {"st": "5.400", "t": "protrahet immersus. nihil est audere relictum:"}, {"st": "5.401", "t": "quaestus naufragio petitur corpusque profundo"}, {"st": "5.402", "t": "immissum pariter quam praeda exquiritur ipsa."}, {"st": "5.403", "t": "nec semper tanti merces est parva laboris:"}, {"st": "5.404", "t": "censibus aequantur conchae, lapidumque nitore"}, {"st": "5.405", "t": "vix quisquam est locuples. oneratur terra profundo."}, {"st": "5.406", "t": "tali sorte suas artes per litora tractat,"}, {"st": "5.407", "t": "aut emit externos pretio mutatque labores"}, {"st": "5.408", "t": "institor aequoreae varia sub imagine mercis."}, {"st": "5.409", "t": "Cumque Fidis magno succedunt sidera mundo"}, {"st": "5.410", "t": "quaesitor scelerum veniet vindexque reorum,"}, {"st": "5.411", "t": "qui commissa suis rimabitur argumentis"}, {"st": "5.412", "t": "in lucemque trahet tacita latitantia fraude."}, {"st": "5.413", "t": "hinc etiam immitis tortor poenaeque minister"}, {"st": "5.414", "t": "et quisquis verove favet culpamve perodit"}, {"st": "5.415", "t": "proditur atque alto qui iurgia pectore tollat."}, {"st": "5.416", "t": "Caeruleus ponto cum se Delphinus in astra"}, {"st": "5.417", "t": "erigit et squamam stellis imitantibus exit,"}, {"st": "5.418", "t": "ambiguus terrae partus pelagique creatur."}, {"st": "5.419", "t": "nam, velut ipse citis perlabitur aequora pinnis"}, {"st": "5.420", "t": "nunc summum scindens pelagus nunc alta profundi"}, {"st": "5.421", "t": "et sinibus vires sumit fluctumque figurat,"}, {"st": "5.422", "t": "sic, venit ex illo quisquis, volitabit in undis."}, {"st": "5.423", "t": "nunc alterna ferens in lentos bracchia tractus"}, {"st": "5.424", "t": "&lt;conspicuus franget spumanti limite pontum&gt; 423a"}, {"st": "5.425", "t": "et plausa resonabit aqua, nunc aequore mersas"}, {"st": "5.426", "t": "diducet palmas furtiva biremis in ipso,"}, {"st": "5.427", "t": "nunc in aquas rectus veniet passuque natabit"}, {"st": "5.428", "t": "et vada mentitus reddet super aequora campum;"}, {"st": "5.429", "t": "aut immota ferens in tergus membra latusque"}, {"st": "5.430", "t": "non onerabit aquas summisque accumbet in undis"}, {"st": "5.430b", "t": "pendebitque super, totus sine remige velum."}, {"st": "5.431", "t": "illis in ponto iucundum est quaerere pontum,"}, {"st": "5.432", "t": "corporaque immergunt undis ipsumque sub antris"}, {"st": "5.433", "t": "Nerea et aequoreas conantur visere Nymphas,"}, {"st": "5.434", "t": "exportantque maris praedas et rapta profundo"}, {"st": "5.435", "t": "naufragia atque imas avidi scrutantur harenas."}, {"st": "5.436", "t": "par ex diverso studium sociatur utrumque"}, {"st": "5.437", "t": "in genus atque uno digestum semine surgit."}, {"st": "5.438", "t": "adnumeres etiam illa licet cognata per artem"}, {"st": "5.439", "t": "corpora, quae valido saliunt excussa petauro"}, {"st": "5.440", "t": "alternosque cient motus, elatus et ante"}, {"st": "5.441", "t": "nunc iacet atque huius casu suspenditur ille,"}, {"st": "5.442", "t": "membrave per flammas orbesque emissa flagrantis,"}, {"st": "5.444", "t": "quae delphina suo per inane imitantia motu"}, {"st": "5.443", "t": "molliter ut liquidis per humum ponuntur in undis"}, {"st": "5.445", "t": "et viduata volant pinnis et in aere ludunt."}, {"st": "5.446", "t": "at, si deficient artes, remanebit in illis"}, {"st": "5.447", "t": "materies tamen apta; dabit natura vigorem"}, {"st": "5.448", "t": "atque alacris cursus campoque volantia membra."}, {"st": "5.449", "t": "Sed regione means Cepheus umentis Aquari"}, {"st": "5.450", "t": "non dabit in lusum mores. facit ora severae"}, {"st": "5.451", "t": "frontis &lt;is&gt; ac vultus componit pondere mentis."}, {"st": "5.452", "t": "pascentur curis veterumque exempla revolvent"}, {"st": "5.453", "t": "semper et antiqui laudabunt verba Catonis."}, {"st": "5.455", "t": "componet teneros etiam qui nutriat annos"}, {"st": "5.456", "t": "et dominum dominus praetextae lege sequatur"}, {"st": "5.457", "t": "quodque agat id credat, stupefactus imagine iuris,"}, {"st": "5.454", "t": "tutorisve supercilium patruive rigorem."}, {"st": "5.458", "t": "quin etiam tragico praestabunt verba coturno,"}, {"st": "5.459", "t": "cuius erit, quamquam in chartis, stilus ipse cruentus"}, {"st": "5.460", "t": "nec minus hae scelerum facie rerumque tumultu"}, {"st": "5.461", "t": "gaudebunt. vix una trium memorare sepulcra"}, {"st": "5.462", "t": "ructantemque patrem natos solemque reversum"}, {"st": "5.463", "t": "et caecum sine nube diem, Thebana iuvabit"}, {"st": "5.464", "t": "dicere bella uteri mixtumque in fratre parentem,"}, {"st": "5.465", "t": "quin et Medeae natos fratremque patremque,"}, {"st": "5.466", "t": "hinc vestes flammas illinc pro munere missas"}, {"st": "5.467", "t": "aeriamque fugam natosque ex ignibus annos."}, {"st": "5.468", "t": "mille alias rerum species in carmina ducent;"}, {"st": "5.469", "t": "forsitan ipse etiam Cepheus referetur in actus."}, {"st": "5.470", "t": "et, siquis studio scribendi mitior ibit,"}, {"st": "5.471", "t": "comica componet laetis spectacula ludis,"}, {"st": "5.472", "t": "ardentis iuvenes raptasque in amore puellas"}, {"st": "5.473", "t": "elusosque senes agilisque per omnia servos,"}, {"st": "5.474", "t": "quis in cuncta suam produxit saecula vitam"}, {"st": "5.475", "t": "doctior urbe sua linguae sub flore Menander,"}, {"st": "5.476", "t": "qui vitae ostendit vitam chartisque sacravit."}, {"st": "5.477", "t": "et, si tanta operum vires commenta negarint,"}, {"st": "5.478", "t": "externis tamen aptus erit, nunc voce poetis"}, {"st": "5.479", "t": "nunc tacito gestu referensque affectibus ora,"}, {"st": "5.480", "t": "et sua dicendo faciet, 480a"}, {"st": "5.481", "t": "scaenisque togatos 482b"}, {"st": "5.482", "t": "aut magnos heroas aget, 482a"}, {"st": "5.483", "t": "solusque per omnis 480b"}, {"st": "5.484", "t": "ibit personas et turbam reddet in uno;"}, {"st": "5.483b", "t": "omnis fortunae vultum per membra reducet,"}, {"st": "5.484b", "t": "aequabitque choros gestu cogetque videre"}, {"st": "5.485", "t": "praesentem Troiam Priamumque ante ora cadentem."}, {"st": "5.486", "t": "Nunc Aquilae sidus referam, quae parte sinistra"}, {"st": "5.487", "t": "rorantis iuvenis, quem terris sustulit ipsa,"}, {"st": "5.488", "t": "fertur et extentis praedam circumvolat alis."}, {"st": "5.489", "t": "fulmina missa refert et caelo militat ales"}, {"st": "5.490", "t": "bis sextamque notat partem fluvialis Aquari."}, {"st": "5.491", "t": "illius in terris orientis tempore natus"}, {"st": "5.492", "t": "ad spolia et partas surget vel caede rapinas"}, {"st": "5.494", "t": "nec pacem bello, civem discernet ab hoste,"}, {"st": "5.493", "t": "cumque hominum derit strages, dabit ille ferarum."}, {"st": "5.495", "t": "ipse sibi lex est, et qua fert cumque voluntas"}, {"st": "5.496", "t": "praecipitant vires; laus est contemnere cuncta."}, {"st": "5.497", "t": "et, si forte bonis accesserit impetus ausis,"}, {"st": "5.498", "t": "improbitas fiet virtus, et condere bella"}, {"st": "5.499", "t": "et magnis patriam poterit ditare triumphis."}, {"st": "5.500", "t": "et, quia non tractat volucris sed suggerit arma"}, {"st": "5.501", "t": "immissosque refert ignes et fulmina reddit,"}, {"st": "5.502", "t": "regis erit magnive ducis per bella minister"}, {"st": "5.503", "t": "ingentisque suis praestabit viribus usus."}, {"st": "5.504", "t": "At, cum Cassiope bis denis partibus actis"}, {"st": "5.505", "t": "aequorei iuvenis dextra de parte resurgit,"}, {"st": "5.506", "t": "artifices auri faciet, qui mille figuris"}, {"st": "5.507", "t": "vertere opus possint caraeque acquirere dotem"}, {"st": "5.508", "t": "materiae et lapidum vivos miscere colores."}, {"st": "5.509", "t": "hinc Augusta nitent sacratis munera templis,"}, {"st": "5.511", "t": "aurea Phoebeis certantia lumina flammis"}, {"st": "5.512", "t": "gemmarumque umbra radiantes lucibus ignes."}, {"st": "5.513", "t": "hinc Pompeia manent veteris monumenta triumphi"}, {"st": "5.510", "t": "et Mithridateos vultus induta tropaea,"}, {"st": "5.515", "t": "non exstincta die semperque recentia flammis."}, {"st": "5.516", "t": "hinc lenocinium formae cultusque repertus"}, {"st": "5.517", "t": "corporis atque auro quaesita est gratia frontis"}, {"st": "5.518", "t": "perque caput ducti lapides per colla manusque"}, {"st": "5.519", "t": "et pedibus niveis fulserunt aurea vincla."}, {"st": "5.520", "t": "quid potius matrona velit tractare creatos"}, {"st": "5.521", "t": "quam factum revocare suos quod possit ad usus?"}, {"st": "5.522", "t": "ac, ne materies tali sub munere desit,"}, {"st": "5.523", "t": "quaerere sub terris aurum furtoque latentem"}, {"st": "5.524", "t": "naturam eruere &lt;omnem&gt; orbemque invertere praedae"}, {"st": "5.525", "t": "imperat et glaebas inter deprendere gazam"}, {"st": "5.526", "t": "invitamque novo tandem producere caelo."}, {"st": "5.527", "t": "ille etiam fulvas avidus numerabit harenas"}, {"st": "5.528", "t": "perfundetque novo stillantia litora ponto"}, {"st": "5.529", "t": "parvaque ramentis faciet momenta minutis"}, {"st": "5.530", "t": "Pactolive leget census spumantis in aurum;"}, {"st": "5.533", "t": "aut coquet argenti glaebas venamque latentem"}, {"st": "5.534", "t": "eruet et silicem rivo saliente liquabit;"}, {"st": "5.535", "t": "aut facti mercator erit per utrumque metalli,"}, {"st": "5.536", "t": "alterum et alterius semper mutabit ad usus."}, {"st": "5.537", "t": "talia Cassiope nascentum pectora finget."}, {"st": "5.538", "t": "Andromedae sequitur sidus, quae Piscibus ortis"}, {"st": "5.539", "t": "bis sex in partes caelo venit aurea dextro."}, {"st": "5.540", "t": "hanc quondam poenae dirorum culpa parentum"}, {"st": "5.541", "t": "prodidit, infestus totis cum finibus omnis"}, {"st": "5.542", "t": "incubuit pontus, fluitavit naufraga tellus,"}, {"st": "5.514", "t": "et quod erat regnum pelagus fuit. una malorum"}, {"st": "5.543", "t": "proposita est merces, vesano dedere ponto"}, {"st": "5.544", "t": "Andromedan, teneros ut belua manderet artus."}, {"st": "5.545", "t": "hic hymenaeus erat, solataque publica damna"}, {"st": "5.546", "t": "privatis lacrimans ornatur victima poenae"}, {"st": "5.547", "t": "induiturque sinus non haec ad vota paratos,"}, {"st": "5.548", "t": "virginis et vivae rapitur sine funere funus."}, {"st": "5.549", "t": "at, simul infesti ventum est ad litora ponti,"}, {"st": "5.550", "t": "mollia per duras panduntur bracchia cautes;"}, {"st": "5.551", "t": "astrinxere pedes scopulis, iniectaque vincla,"}, {"st": "5.552", "t": "et cruce virginea moritura puella pependit."}, {"st": "5.553", "t": "servatur tamen in poena vultusque pudorque;"}, {"st": "5.554", "t": "supplicia ipsa decent; nivea cervice reclinis"}, {"st": "5.555", "t": "molliter ipsa suae custos est visa figurae."}, {"st": "5.556", "t": "defluxere sinus umeris fugitque lacertos"}, {"st": "5.557", "t": "vestis et effusi scapulis haesere capilli."}, {"st": "5.558", "t": "te circum alcyones pinnis planxere volantes"}, {"st": "5.559", "t": "fleveruntque tuos miserando carmine casus"}, {"st": "5.560", "t": "et tibi contextas umbram fecere per alas."}, {"st": "5.561", "t": "ad tua sustinuit fluctus spectacula pontus"}, {"st": "5.562", "t": "assuetasque sibi desit perfundere rupes,"}, {"st": "5.563", "t": "extulit et liquido Nereis ab aequore vultus"}, {"st": "5.564", "t": "et, casus miserata tuos, roravit et undas."}, {"st": "5.565", "t": "ipsa levi flatu refovens pendentia membra"}, {"st": "5.566", "t": "aura per extremas resonavit flebile rupes."}, {"st": "5.567", "t": "tandem Gorgonei victorem Persea monstri"}, {"st": "5.568", "t": "felix illa dies redeuntem ad litora duxit."}, {"st": "5.569", "t": "isque, ubi pendentem vidit de rupe puellam,"}, {"st": "5.570", "t": "deriguit, facie quem non stupefecerat hostis,"}, {"st": "5.571", "t": "vixque manu spolium tenuit, victorque Medusae"}, {"st": "5.572", "t": "victus in Andromeda est. iam cautibus invidet ipsis"}, {"st": "5.573", "t": "felicisque vocat, teneant quae membra, catenas;"}, {"st": "5.574", "t": "et, postquam poenae causam cognovit ab ipsa,"}, {"st": "5.575", "t": "destinat in thalamos per bellum vadere ponti,"}, {"st": "5.576", "t": "altera si Gorgo veniat, non territus illa."}, {"st": "5.577", "t": "concitat aerios cursus flentisque parentes"}, {"st": "5.578", "t": "promissu vitae recreat pactusque maritam"}, {"st": "5.579", "t": "ad litus remeat. gravidus iam surgere pontus"}, {"st": "5.580", "t": "coeperat ac longo fugiebant agmine fluctus"}, {"st": "5.581", "t": "impellentis onus monstri. caput eminet undas"}, {"st": "5.582", "t": "scindentis pelagusque vomit, circumsonat aequor"}, {"st": "5.583", "t": "dentibus, inque ipso rapidum mare navigat ore;"}, {"st": "5.584", "t": "hinc vasti surgunt immensis torquibus orbes"}, {"st": "5.585", "t": "tergaque consumunt pelagus. sonat undique Phorcys"}, {"st": "5.586", "t": "atque ipsi metuunt montes scopulique ruentem."}, {"st": "5.587", "t": "infelix virgo, quamvis sub vindice tanto"}, {"st": "5.588", "t": "quae tua tunc fuerat facies! quam fugit in auras"}, {"st": "5.589", "t": "spiritus! ut toto caruerunt sanguine membra,"}, {"st": "5.590", "t": "cum tua fata cavis e rupibus ipsa videres"}, {"st": "5.591", "t": "adnantemque tibi poenam pelagusque ferentem"}, {"st": "5.592", "t": "quantula praeda maris! quassis hic subvolat alis"}, {"st": "5.593", "t": "Perseus et semet caelo iaculatur in hostem"}, {"st": "5.594", "t": "Gorgoneo tinctum defigens sanguine ferrum."}, {"st": "5.595", "t": "illa subit contra versamque a gurgite frontem"}, {"st": "5.596", "t": "erigit et tortis innitens orbibus alte"}, {"st": "5.597", "t": "emicat ac toto sublimis corpore fertur."}, {"st": "5.598", "t": "sed, quantum illa subit, semper, iaculata profundo,"}, {"st": "5.599", "t": "in tantum revolat laxumque per aethera ludit"}, {"st": "5.600", "t": "Perseus et ceti subeuntis verberat ora."}, {"st": "5.601", "t": "nec cedit tamen illa viro, sed saevit in auras"}, {"st": "5.602", "t": "morsibus, et vani crepitant sine vulnere dentes;"}, {"st": "5.603", "t": "efflat et in caelum pelagus mergitque volantem"}, {"st": "5.604", "t": "sanguineis undis pontumque exstillat in astra."}, {"st": "5.605", "t": "spectabat pugnam pugnandi causa puella,"}, {"st": "5.606", "t": "iamque oblita sui metuit pro vindice tali"}, {"st": "5.607", "t": "suspirans animoque magis quam corpore pendet."}, {"st": "5.608", "t": "tandem confossis subsedit belua membris"}, {"st": "5.609", "t": "plena maris summasque iterum remeavit ad undas"}, {"st": "5.610", "t": "et magnum vasto contexit corpore pontum,"}, {"st": "5.611", "t": "tum quoque terribilis nec virginis ore videnda."}, {"st": "5.612", "t": "perfundit liquido Perseus in marmore corpus,"}, {"st": "5.613", "t": "maior et ex undis ad cautes pervolat altas"}, {"st": "5.614", "t": "solvitque haerentem vinclis de rupe puellam"}, {"st": "5.615", "t": "desponsam pugna, nupturam dote mariti."}, {"st": "5.616", "t": "hic dedit Andromedae caelum stellisque sacravit"}, {"st": "5.617", "t": "mercedem tanti belli, quo concidit ipsa"}, {"st": "5.618", "t": "Gorgone non levius monstrum pelagusque levavit."}, {"st": "5.619", "t": "Quisquis in Andromedae surgentis tempora ponto"}, {"st": "5.620", "t": "nascitur, immitis veniet poenaeque minister"}, {"st": "5.621", "t": "carceris et duri custos, quo stante superbe"}, {"st": "5.622", "t": "prostratae iaceant miserorum in limine matres"}, {"st": "5.623", "t": "pernoctesque patres cupiant extrema suorum"}, {"st": "5.624", "t": "oscula et in proprias animam transferre medullas."}, {"st": "5.625", "t": "carnificisque venit mortem vendentis imago"}, {"st": "5.626", "t": "accensosque rogos, cui stricta saepe securi"}, {"st": "5.627", "t": "supplicium vectigal erit, qui denique posset"}, {"st": "5.628", "t": "pendentem e scopulis ipsam spectare puellam,"}, {"st": "5.629", "t": "vinctorum dominus sociusque in parte catenae"}, {"st": "5.630", "t": "interdum, poenis ut noxia corpora servet."}, {"st": "5.631", "t": "Piscibus exortis cum pars vicesima prima"}, {"st": "5.632", "t": "signabit terrae limen, fulgebit et orbi,"}, {"st": "5.633", "t": "aerius nascetur Equus caeloque volabit,"}, {"st": "5.634", "t": "velocisque dabit sub tali tempore partus"}, {"st": "5.635", "t": "omne per officium vigilantia membra ferentis."}, {"st": "5.636", "t": "hic glomerabit equo gyros dorsoque superbus"}, {"st": "5.637", "t": "ardua bella geret rector cum milite mixtus;"}, {"st": "5.638", "t": "hic stadium fraudare fide poteritque videri"}, {"st": "5.639", "t": "mentitus passus et campum tollere cursu."}, {"st": "5.640", "t": "nam quis ab extremo citius revolaverit orbe"}, {"st": "5.641", "t": "nuntius extremumve levis penetraverit orbem?"}, {"st": "5.642", "t": "vilibus ille etiam sanabit vulnera sucis"}, {"st": "5.643", "t": "quadrupedum, et medicas herbas in membra ferarum"}, {"st": "5.644", "t": "noverit, humanos et quae nascentur ad usus."}, {"st": "5.645", "t": "Nixa genu species et Graio nomine dicta"}, {"st": "5.646", "t": "Engonasin, cui nulla fides sub origine constat,"}, {"st": "5.647", "t": "dextra per extremos attollit lumina Pisces."}, {"st": "5.648", "t": "hinc fuga nascentum, dolus insidiaeque creantur,"}, {"st": "5.649", "t": "grassatorque venit media metuendus in urbe."}, {"st": "5.650", "t": "et, si forte aliquas animus consurget in artes,"}, {"st": "5.651", "t": "in praerupta dabit studium, vendetque periclo"}, {"st": "5.652", "t": "ingenium, ac tenuis ausus sine limite gressus"}, {"st": "5.653", "t": "certa per extentos ponet vestigia funes"}, {"st": "5.654", "t": "et caeli meditatus iter vestigia perdet"}, {"st": "5.655", "t": "paene sua et pendens populum suspendet ab ipso."}, {"st": "5.656", "t": "Laeva sub extremis consurgunt sidera Ceti"}, {"st": "5.657", "t": "Piscibus Andromedan ponto caeloque sequentis."}, {"st": "5.658", "t": "hoc trahit in pelagi caedes et vulnera natos"}, {"st": "5.659", "t": "squamigeri gregis, extentis laqueare profundum"}, {"st": "5.660", "t": "retibus et pontum vinclis artare furentis;"}, {"st": "5.661", "t": "et velut in laxo securas aequore phocas"}, {"st": "5.662", "t": "carceribus claudent raris et compede nectent"}, {"st": "5.663", "t": "incautosque trahent macularum nemine thynnos."}, {"st": "5.664", "t": "nec cepisse sat est: luctantur corpora nodis"}, {"st": "5.665", "t": "exceptantque novas acies ferroque necantur,"}, {"st": "5.666", "t": "inficiturque suo permixtus sanguine pontus."}, {"st": "5.667", "t": "tum quoque, cum toto iacuerunt litore praedae,"}, {"st": "5.668", "t": "altera fit caedis caedes: scinduntur in artus,"}, {"st": "5.669", "t": "corpore et ex uno varius discribitur usus."}, {"st": "5.670", "t": "illa datis melior, sucis pars illa retentis."}, {"st": "5.671", "t": "hinc sanies pretiosa fluit floremque cruoris"}, {"st": "5.672", "t": "evomit ex mixto gustum sale temperat oris;"}, {"st": "5.673", "t": "illa putris turbae strages confunditur omnis"}, {"st": "5.674", "t": "permiscetque suas alterna in damna figuras"}, {"st": "5.675", "t": "communemque cibis usum sucumque ministrat."}, {"st": "5.676", "t": "aut, cum caeruleo stetit ipsa simillima ponto"}, {"st": "5.677", "t": "squamigerum nubes turbaque immobilis haeret,"}, {"st": "5.678", "t": "excipitur vasta circum vallata sagena"}, {"st": "5.679", "t": "ingentisque lacus et Bacchi dolia complet"}, {"st": "5.680", "t": "umorisque vomit socias per mutua dotes"}, {"st": "5.681", "t": "et fluit in liquidam tabem resoluta medullas."}, {"st": "5.682", "t": "quin etiam magnas poterunt celebrare salinas"}, {"st": "5.683", "t": "et pontum coquere et ponti secernere virus,"}, {"st": "5.684", "t": "cum solidum certo distendunt margine campum"}, {"st": "5.685", "t": "appelluntque suo deductum ex aequore fluctum"}, {"st": "5.686", "t": "claudendoque negant abitum: sic suscipit undas"}, {"st": "5.687", "t": "area et epoto per solem umore nitescit."}, {"st": "5.688", "t": "congeritur siccum pelagus mensisque profundi"}, {"st": "5.689", "t": "canities detonsa maris, spumaeque rigentis"}, {"st": "5.690", "t": "ingentis faciunt tumulos, pelagique venenum,"}, {"st": "5.691", "t": "quo perit usus aquae suco corruptus amaro,"}, {"st": "5.692", "t": "vitali sale permutant redduntque salubre."}, {"st": "5.693", "t": "At, revoluta polo cum primis vultibus Arctos"}, {"st": "5.694", "t": "ad sua perpetuos revocat vestigia passus"}, {"st": "5.695", "t": "numquam tincta vadis sed semper flexilis orbe,"}, {"st": "5.696", "t": "[aut Cynosura minor cum prima luce resurgit"}, {"st": "5.697", "t": "et pariter vastusve Leo vel Scorpius acer"}, {"st": "5.698", "t": "nocte sub extrema promittunt iura diei]"}, {"st": "5.699", "t": "non inimica ferae tali sub tempore natis"}, {"st": "5.700", "t": "ora ferent, placidasque regent commercia gentes."}, {"st": "5.701", "t": "ille manu vastos poterit frenare leones"}, {"st": "5.702", "t": "et palpare lupos, pantheris ludere captis,"}, {"st": "5.703", "t": "nec fugiet validas cognati sideris ursas"}, {"st": "5.704", "t": "inque artes hominum perversaque munera ducet;"}, {"st": "5.705", "t": "ille elephanta premet dorso stimulisque movebit"}, {"st": "5.706", "t": "turpiter in tanto cedentem pondere punctis;"}, {"st": "5.707", "t": "ille tigrim rabie solvet pacique domabit,"}, {"st": "5.708", "t": "quaeque alia infestant furiis animalia terras"}, {"st": "5.709", "t": "iunget amicitia secum, catulosque sagacis"}, {"st": "5.710", "t": "* 709a"}, {"st": "5.30", "t": "has stellis proprias vires et tempora rerum"}, {"st": "5.31", "t": "constituit magni quondam fabricator Olympi."}, {"st": "5.32b", "t": "* 709b"}, {"st": "5.33b", "t": "tertia Pleiadas dotavit forma sorores"}, {"st": "5.34b", "t": "femineum rubro vultum suffusa pyropo,"}, {"st": "5.35b", "t": "invenitque parem sub te, Cynosura, colorem,"}, {"st": "5.36b", "t": "et quos Delphinus iaculatur quattuor ignes"}, {"st": "5.37b", "t": "Deltotonque tribus facibus, similique nitentem"}, {"st": "5.715", "t": "luce Aquilam et flexos per lubrica terga dracones."}, {"st": "5.716", "t": "tum quartum sextumque genus discernitur omni"}, {"st": "5.717", "t": "e numero, summamque gradus qui iungit utramque."}, {"st": "5.718", "t": "maxima pars numero censu concluditur imo,"}, {"st": "5.719", "t": "quae neque per cunctas noctes neque tempore in omni"}, {"st": "5.720", "t": "resplendet vasto caeli summota profundo,"}, {"st": "5.721", "t": "sed, cum clara suos avertit Delia cursus"}, {"st": "5.722", "t": "cumque vagae stellae terris sua lumina condunt,"}, {"st": "5.723", "t": "mersit et ardentis Orion aureus ignes"}, {"st": "5.724", "t": "signaque transgressus permutat tempora Phoebus,"}, {"st": "5.725", "t": "effulget tenebris et nocte accenditur atra."}, {"st": "5.726", "t": "tum conferta licet caeli fulgentia templa"}, {"st": "5.727", "t": "cernere seminibus &lt;minimis&gt; totumque micare"}, {"st": "5.729", "t": "stipatum stellis mundum nec cedere summa"}, {"st": "5.730", "t": "floribus aut siccae curvum per litus harenae,"}, {"st": "5.731", "t": "sed, quot eant semper nascentes aequore fluctus,"}, {"st": "5.732", "t": "quot delapsa cadant foliorum milia silvis,"}, {"st": "5.733", "t": "amplius hoc ignes numero volitare per orbem."}, {"st": "5.734", "t": "utque per ingentis populus discribitur urbes,"}, {"st": "5.735", "t": "principiumque patres retinent et proximum equester"}, {"st": "5.736", "t": "ordo locum, populumque equiti populoque subire"}, {"st": "5.737", "t": "vulgus iners videas et iam sine nomine turbam,"}, {"st": "5.738", "t": "sic etiam magno quaedam res publica mundo est"}, {"st": "5.739", "t": "quam natura facit, quae caelo condidit urbem."}, {"st": "5.740", "t": "sunt stellae procerum similes, sunt proxima primis"}, {"st": "5.741", "t": "sidera, suntque gradus atque omnia iusta priorum:"}, {"st": "5.742", "t": "maximus est populus summo qui culmine fertur;"}, {"st": "5.743", "t": "cui si pro numero vires natura dedisset,"}, {"st": "5.744", "t": "ipse suas aether flammas sufferre nequiret,"}, {"st": "5.745", "t": "totus et accenso mundus flagraret Olympo."}], [])})();
